/** Reopen the same package after the authoring directory has moved or disappeared. */
export async function inspectMssqlRelease(directory) {
  const root = resolve(directory);
  const manifestBytes = await bytes(join(root, 'manifest.json'), 2 * MiB), manifest = parse(manifestBytes);
  if (manifest.schema !== MSSQL_SOURCE_SCHEMA || manifest.packagePath !== PACKAGE || !manifest.mssql || !Array.isArray(manifest.files))
    fail('Expected a retained original SQL Server merchant release.');
  const prepared = await prepareMssqlRelease(join(root, PACKAGE));
  if (!isDeepStrictEqual(manifest.files, prepared.files) || !isDeepStrictEqual(manifest.mssql, prepared.mssql))
    fail('The retained SQL Server query, connection, plan or client changed. Stage a new release.');
  const offersBytes = await bytes(join(root, 'offers.json'), 2 * MiB), serviceBytes = await bytes(join(root, 'seller-service.json'), 262144);
  if (hash(offersBytes) !== manifest.offersSha256 || hash(serviceBytes) !== manifest.serviceConfigSha256 ||
      !offersBytes.equals(prepared.offersBytes) || !serviceBytes.equals(prepared.serviceBytes))
    fail('The retained SQL Server offers or service differ from the original package.');
  return { manifest, mssql: prepared.mssql, offers: prepared.offers, service: prepared.service,
    package: prepared.bundle, hasApplication: true,
