    sourceFileSha256:origin.discoveryFileSha256, rowIndex, acceptIndex,
    intentId:op.intentId, sellerUrl:op.url, method:op.method, acceptedTerms:op.expect, pathBinding,
    requestHeaderNames:Object.keys(op.headers),
