    r?.extensions?.bazaar?.info?.input?.type === 'http' &&
    r?.extensions?.bazaar?.info?.input?.method === eInput.method);
  const sameTerms = (actual, wanted) => PAYMENT_FIELDS.every(key =>
    isDeepStrictEqual(actual?.[key], wanted[key]));
