      u.username || u.password || u.pathname !== '/' || u.search || u.hash)
    throw new TypeError('Only explicit http://127.0.0.1:PORT/ catalog is permitted');
  const path = new URL('/discovery/resources', u);
  path.searchParams.set('type', 'http');
