        !reasonValid(row.reason) || !Array.isArray(row.routeIds) || !row.routeIds.length || row.routeIds.length > 100 ||
        new Set(row.routeIds).size !== row.routeIds.length || row.routeIds.some(id => !ID.test(id)))
