}

/** Keep the ORIGINAL payment terms/compiler. Binary bytes must not be falsely
 * advertised as a JSON result in Bazaar metadata. Imported offers stay exact. */
export function compileAssetRouteOffer(route, origin, compileOffer, allowLocalhost = false) {
  validateResponseAssetRoute(route);
  if (route.offer) return route.offer;
  const offer = compileOffer({ ...route.definition, url: origin + route.path }, { allowLocalhost });
  offer.resource.mimeType = route.responseAsset.contentType;
  delete offer.extensions.bazaar.info.output;
  delete offer.extensions.bazaar.schema.properties.output;
  offer.extensions.bazaar.schema.required = offer.extensions.bazaar.schema.required.filter(key => key !== 'output');
  return offer;
}

"""Stable application errors; native stderr and signer output are never echoed."""


class BuyerError(RuntimeError):
    def __init__(self, code: str, *, operation=None):
        self.code = code
        self.operation = operation
        super().__init__(code)


class NativeError(BuyerError):
    def __init__(self, code: str, *, returncode=None, operation=None):
        self.returncode = returncode
        super().__init__(code, operation=operation)


class StateError(BuyerError):
    pass


class DeliveryError(BuyerError):
    def __init__(self, code: str, *, operation=None, record=None):
        self.record = record
        native = (record or {}).get("native") or {}
        self.partial_path = native.get("partialPath")
        self.transfer_state_path = native.get("transferState")
        self.retained_bytes = native.get("retainedBytes", 0)
        self.resumable = native.get("resumable", False)
        super().__init__(code, operation=operation)

