  if(prefix[1].includes('@')) return fail('RESOURCE_URL_USERINFO');
  if(input.includes('#')) return fail('RESOURCE_URL_FRAGMENT');
  const rawPath=input.slice(prefix[0].length).split(/[?#]/,1)[0]||'/';
  if(!rawPath.startsWith('/')) return fail('RESOURCE_PATH_NOT_ABSOLUTE');
  for(const segment of rawPath.split('/')) {
    if(!segment) continue;
    let value=segment;
    for(let pass=0;pass<5;pass++) {
      let next;
      try { next=decodeURIComponent(value); }
      catch { return fail('RESOURCE_PATH_PERCENT_ENCODING'); }
      if(next==='.'||next==='..') return fail('RESOURCE_PATH_DOT_SEGMENT');
      if(next.includes('/')||next.includes('\\')) return fail('RESOURCE_PATH_ENCODED_SEPARATOR');
      if(next===value) break;
      value=next;
      if(pass===4) return fail('RESOURCE_PATH_ENCODING_DEPTH');
    }
  }
  let url;
  try { url=new URL(input); } catch { return fail('RESOURCE_URL_INVALID'); }
  if(!['http:','https:'].includes(url.protocol)) return fail('RESOURCE_URL_SCHEME');
  if(!url.hostname) return fail('RESOURCE_URL_HOST');
  if(url.username||url.password) return fail('RESOURCE_URL_USERINFO');
  return {ok:true,canonicalURL:url.href,url};
}

/** Bind a real resource path and optional echoed parameter claims to a template. */
function bindPath(template, actual, claimed) {
  const parts=template.split('/'), values=actual.split('/');
  if(parts.length!==values.length) return fail('TEMPLATE_PATH_MISMATCH');
  const bindings={};
  for(let i=1;i<parts.length;i++) {
    let value;
    try { value=decodeURIComponent(values[i]); }
    catch { return fail('RESOURCE_PATH_PERCENT_ENCODING'); }
    if(value.includes('/')||value.includes('\\')||value==='.'||value==='..') {
      return fail('RESOURCE_PATH_ENCODED_SEPARATOR');
    }
    const p=PARAM.exec(parts[i]);
    if(p) {
      if(!value) return fail('TEMPLATE_EMPTY_PARAM');
      Object.defineProperty(bindings,p[1],{value,enumerable:true,writable:true,configurable:true});
    } else if(value!==parts[i]) {
      return fail('TEMPLATE_PATH_MISMATCH');
    }
  }
  if(claimed!==undefined) {
    if(claimed===null||Array.isArray(claimed)||typeof claimed!=='object') {
      return fail('TEMPLATE_PARAMS_INVALID');
    }
    const want=Object.keys(bindings).sort(),got=Object.keys(claimed).sort();
    if(JSON.stringify(want)!==JSON.stringify(got)) return fail('TEMPLATE_PARAMS_MISMATCH');
    for(const key of want) if(String(claimed[key])!==bindings[key]) {
      return fail('TEMPLATE_PARAMS_MISMATCH');
    }
  }
  return {ok:true,bindings};
}

/**
 * Input: {resourceURL, input:{type:'http',method,pathParams?} or
 * input:{type:'mcp',toolName}, routeTemplate?}.
 * Outputs an implementation-private catalogKey, NOT authentication.
 * Independently verify seller, payTo, schema, settlement before any write.
 */
export function resolveCatalogIdentity(record) {
  if(!record||typeof record!=='object') return {status:'rejected',reason:'RECORD_INVALID'};
  const resource=inspectResourceURL(record.resourceURL);
  if(!resource.ok) return {status:'rejected',reason:resource.reason};
  if(!record.input||typeof record.input!=='object') return {status:'rejected',reason:'INPUT_MISSING'};
  const {canonicalURL,url}=resource;
  if(record.input.type==='mcp') {
    const name=record.input.toolName;
    if(typeof name!=='string'||!/^[A-Za-z0-9_.\-]{1,128}$/.test(name)) {
      return {status:'rejected',reason:'MCP_TOOL_NAME_INVALID'};
    }
    return {status:'accepted',kind:'mcp',resourceURL:canonicalURL,
      catalogKey:'mcp|'+canonicalURL+'|'+name,toolName:name};
  }
  if(record.input.type!=='http'||!METHODS.has(record.input.method)) {
    return {status:'rejected',reason:'HTTP_METHOD_INVALID'};
  }
  const method=record.input.method;
  const concrete={status:'accepted',kind:'http',resourceURL:canonicalURL,
    catalogKey:'http|'+method+'|'+canonicalURL,method};
  if(record.routeTemplate===undefined||record.routeTemplate===null) return concrete;
  const template=inspectRouteTemplate(record.routeTemplate);
  if(!template.ok) return {...concrete,status:'fallback',reason:template.reason};
  const matched=bindPath(template.canonicalPath,url.pathname,record.input.pathParams);
  if(!matched.ok) return {...concrete,status:'fallback',reason:matched.reason};
  const keyURL=url.origin+template.canonicalPath;
  return {status:'accepted',kind:'http',resourceURL:keyURL,
    catalogKey:'http|'+method+'|'+keyURL,method,
    canonicalRouteTemplate:template.canonicalPath,pathParams:matched.bindings};
}

"""Complete, portable query results from the original customer DatasetDatabase.

Run ``python -m stellar_forge_buyer.query_export --help`` for the offline CLI.
"""
from __future__ import annotations

import argparse
import base64
from contextlib import ExitStack, contextmanager
from copy import deepcopy
from datetime import datetime, timezone
import csv
import hashlib
import io
import json
import math
import os
from pathlib import Path
import re
import sqlite3
import stat
import sys
import time

from .errors import BuyerError, StateError
from .storage import digest, dump, parse, private_directory, read, sync_directory, write as atomic_write

_SCHEMA = "stellar-forge.python-query-export.v1"
_REQUEST = "stellar-forge.python-query-request.v1"
_FILES = {"jsonl": "rows.jsonl", "csv": "rows.csv", "sqlite": "rows.sqlite3"}
_HEX = re.compile(r"[a-f0-9]{64}")
_ROW_LIMIT = 128 * 1024 * 1024
_MANIFEST_LIMIT = 16 * 1024 * 1024
_ORDINAL = "_sf_export_row"


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"), sort_keys=True)


def _encode(value):
    if isinstance(value, bytes):
        return {"$sqliteBlob": base64.b64encode(value).decode("ascii")}
    if type(value) is float and not math.isfinite(value):
        return {"$sqliteFloat": "Infinity" if value > 0 else "-Infinity" if value < 0 else "NaN"}
    if value is None or type(value) in (str, int, float, bool):
        return value
    raise StateError("QUERY_EXPORT_VALUE_INVALID")


def _decode(value):
    if isinstance(value, dict):
        if set(value) == {"$sqliteBlob"} and isinstance(value["$sqliteBlob"], str):
            try:
                return base64.b64decode(value["$sqliteBlob"], validate=True)
            except ValueError:
                pass
        if set(value) == {"$sqliteFloat"} and value["$sqliteFloat"] in ("Infinity", "-Infinity", "NaN"):
            return float(value["$sqliteFloat"])
        raise StateError("QUERY_EXPORT_TYPED_VALUE_INVALID")
    return _encode(value)


def _bindings(parameters, *, decode=False):
    convert = _decode if decode else _encode
    if isinstance(parameters, dict) and all(isinstance(key, str) for key in parameters):
        return {key: convert(value) for key, value in parameters.items()}
    if isinstance(parameters, (list, tuple)):
        return [convert(value) for value in parameters]
    raise StateError("QUERY_EXPORT_PARAMETERS_INVALID")


def _path(value):
    return Path(os.path.abspath(Path(value).expanduser()))


def _new_directory(destination):
    target = _path(destination)
    if private_directory(target.parent, create=False) != target.parent:
        raise StateError("QUERY_EXPORT_CANONICAL_PARENT_REQUIRED")
    try:
        target.mkdir(mode=0o700)
    except FileExistsError:
        raise StateError("QUERY_EXPORT_DESTINATION_EXISTS_USE_OPEN") from None
    sync_directory(target.parent)
    return target


def _cleanup(directory):
    # A completed record, including a lost final reply, is retained for reopen.
    if (directory / "manifest.json").exists():
        return
    for name in (*_FILES.values(), *("." + name + ".part" for name in _FILES.values()),
                 ".rows.sqlite3.part-journal"):
        try:
            (directory / name).unlink(missing_ok=True)
        except OSError:
            pass
    try:
        directory.rmdir()
        sync_directory(directory.parent)
    except OSError:
        pass  # Preserve any other files; never recursively remove this directory.


@contextmanager
def _private_file(path):
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1
                    or info.st_mode & 0o077 or info.st_uid != os.getuid()):
                raise StateError("QUERY_EXPORT_PRIVATE_FILE_REQUIRED")
            yield stream
    except OSError as exc:
        raise StateError("QUERY_EXPORT_FILE_UNAVAILABLE") from exc


def _file_record(path):
    checksum, total = hashlib.sha256(), 0
    with _private_file(path) as source:
        while chunk := source.read(1024 * 1024):
            checksum.update(chunk)
            total += len(chunk)
    return {"bytes": total, "sha256": checksum.hexdigest()}


def _columns(columns, *, sqlite=False):
    if (not columns or any(not isinstance(name, str) or not name
            or len(name.encode("utf-8")) > 512 or any(ord(c) < 32 for c in name) for name in columns)
            or len(set(columns)) != len(columns)):
        raise StateError("QUERY_EXPORT_COLUMN_NAMES_REQUIRE_UNIQUE_ALIASES")
    if sqlite and (len({name.lower() for name in columns}) != len(columns)
                   or _ORDINAL in {name.lower() for name in columns} or len(columns) > 1999):
        raise StateError("QUERY_EXPORT_SQLITE_COLUMNS_REQUIRE_ALIASES")


def _quoted(name):
    return '"' + name.replace('"', '""') + '"'


def _csv_value(value, safe):
    if isinstance(value, bytes):
        return "base64:" + base64.b64encode(value).decode("ascii")
    if isinstance(value, str) and safe and (value.startswith(("\t", "\r", "\n"))
            or value.lstrip(" \t\r\n").startswith(("=", "+", "-", "@"))):
        return "'" + value
    return value


def export_query(database, sql, parameters=(), *, destination, formats=("jsonl", "csv", "sqlite"),
                 expected_views=None, timeout=300, cancel=None, max_rows=None,
                 max_output_bytes=None, spreadsheet_safe=True, progress=None):
    """Export every result row once; errors never publish a complete manifest.

    The query is read-only and uses the existing DatasetDatabase reader. A
    caller may set whole-output limits; reaching one raises instead of silently
    truncating the result. Limits apply to the complete selected output set.
    """
    if (not isinstance(formats, (list, tuple)) or not formats
            or any(not isinstance(value, str) or value not in _FILES for value in formats) or len(set(formats)) != len(formats)
            or any(value is not None and (type(value) is not int or value < 1)
                   for value in (max_rows, max_output_bytes))
            or type(spreadsheet_safe) is not bool or progress is not None and not callable(progress)):
        raise StateError("QUERY_EXPORT_OPTIONS_INVALID")
    formats = tuple(formats)
    parameters = _bindings(_bindings(parameters), decode=True)  # Copy and validate before entering SQL.
    encoded_parameters = _bindings(parameters)
    target = _new_directory(destination)
    started = time.monotonic()
    output_db = None
    try:
        with ExitStack() as stack, database.stream_query(sql, parameters, timeout=timeout,
                expected_views=expected_views, cancel=cancel) as rows:
            _columns(rows.columns, sqlite="sqlite" in formats)
            handles = {}
            hashes = {}
            lengths = {}
            sqlite_bytes = 0
            for kind in formats:
                name = _FILES[kind]
                fd = os.open(target / ("." + name + ".part"), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
                if kind == "sqlite":
                    os.close(fd)
                    output_db = sqlite3.connect((target / ("." + name + ".part")).as_uri() + "?mode=rw", uri=True)
                    output_db.execute("PRAGMA synchronous=FULL")
                    output_db.execute("PRAGMA cache_size=-2048")
                    output_db.execute("PRAGMA application_id=1397117272")
                    output_db.execute("PRAGMA user_version=1")
                    output_db.execute("BEGIN IMMEDIATE")
                    output_db.execute(f"CREATE TABLE result({_quoted(_ORDINAL)} INTEGER PRIMARY KEY,"
                                      + ",".join(_quoted(column) for column in rows.columns) + ")")
                    insert = "INSERT INTO result VALUES(" + ",".join("?" for _ in range(len(rows.columns) + 1)) + ")"
                else:
                    handles[kind] = stack.enter_context(os.fdopen(fd, "wb"))
                    hashes[kind] = hashlib.sha256()
                    lengths[kind] = 0
            csv_buffer = io.StringIO(newline="")
            csv_writer = csv.writer(csv_buffer, lineterminator="\n")

            def check_size():
                if max_output_bytes is not None and sum(lengths.values()) + sqlite_bytes > max_output_bytes:
                    raise StateError("QUERY_EXPORT_OUTPUT_LIMIT_EXCEEDED")

            def write(kind, raw):
                lengths[kind] += len(raw)
                check_size()
                handles[kind].write(raw)
                hashes[kind].update(raw)

            def write_csv(values):
                csv_buffer.seek(0)
                csv_buffer.truncate()
                csv_writer.writerow(values)
                write("csv", csv_buffer.getvalue().encode("utf-8"))

            if "csv" in formats:
                write_csv([_csv_value(column, spreadsheet_safe) for column in rows.columns])
            count = 0
            for values in rows:
                if max_rows is not None and count == max_rows:
                    raise StateError("QUERY_EXPORT_ROW_LIMIT_EXCEEDED")
                if "jsonl" in formats:
                    write("jsonl", (_json(dict(zip(rows.columns, map(_encode, values)))) + "\n").encode("utf-8"))
                if "csv" in formats:
                    write_csv([_csv_value(value, spreadsheet_safe) for value in values])
                if output_db is not None:
                    output_db.execute(insert, (count + 1, *values))
                count += 1
                if count % 4096 == 0:
                    if output_db is not None:
                        sqlite_bytes = output_db.execute("PRAGMA page_count").fetchone()[0] * output_db.execute("PRAGMA page_size").fetchone()[0]
                    check_size()
                    if progress:
                        progress({"rows": count, "outputBytes": sum(lengths.values()) + sqlite_bytes, "complete": False})
            binding = {"database": str(database.path), "sql": sql, "parameters": encoded_parameters,
                       "views": rows.views, "readTables": list(rows.read_tables), "sourceVersions": rows.source_versions()}
            if isinstance(expected_views, dict):
                binding["viewSelection"] = expected_views
            binding_sha = digest(_json(binding).encode("utf-8"))
            if output_db is not None:
                output_db.execute("CREATE TABLE export_metadata(record TEXT NOT NULL)")
                output_db.execute("INSERT INTO export_metadata VALUES(?)", (_json({"schema": _SCHEMA,
                    "bindingSha256": binding_sha, "columns": list(rows.columns), "rowCount": count,
                    "orderColumn": _ORDINAL}),))
                output_db.commit()
                output_db.close()
                output_db = None
            for handle in handles.values():
                handle.flush()
                os.fsync(handle.fileno())
            manifest = {"schema": _SCHEMA, "queryComplete": rows.complete,
                        "rowCount": count, "columns": list(rows.columns), "binding": binding,
                        "bindingSha256": binding_sha, "createdAt": datetime.now(timezone.utc).isoformat(),
                        "elapsedMs": round((time.monotonic() - started) * 1000),
                        "largestRowBytes": rows.largest_row_bytes,
                        "jsonlEncoding": "sqlite-scalars-v1", "sqliteOrderColumn": _ORDINAL,
                        "csv": {"spreadsheetSafe": spreadsheet_safe, "null": "empty field", "blob": "base64: prefix"},
                        "outputs": {}}
            rows.check()
        # The original snapshot is released before file hashing/publication.
        for kind in formats:
            name = _FILES[kind]
            temporary = target / ("." + name + ".part")
            if kind == "sqlite":
                with _private_file(temporary) as source:
                    os.fsync(source.fileno())
                record = _file_record(temporary)
            else:
                record = {"bytes": lengths[kind], "sha256": hashes[kind].hexdigest()}
            manifest["outputs"][name] = record
        total = sum(record["bytes"] for record in manifest["outputs"].values())
        if max_output_bytes is not None and total > max_output_bytes:
            raise StateError("QUERY_EXPORT_OUTPUT_LIMIT_EXCEEDED")
        if cancel is not None and cancel():
            raise StateError("DATASET_SQL_QUERY_CANCELLED")
        for name in manifest["outputs"]:
            os.rename(target / ("." + name + ".part"), target / name)
        sync_directory(target)
        manifest_raw = (_json(manifest) + "\n").encode("utf-8")
        if len(manifest_raw) > _MANIFEST_LIMIT:
            raise StateError("QUERY_EXPORT_MANIFEST_TOO_LARGE")
        atomic_write(target / "manifest.json", manifest_raw, exclusive=True)
        result = QueryExport(target)
        if progress:
            progress({"rows": count, "outputBytes": total, "complete": True})
        return result
    except BaseException:
        if output_db is not None:
            output_db.close()
        _cleanup(target)
        raise


class QueryExport:
    """Reopen/copy a completed result without its source database or runtime."""

    def __init__(self, directory):
        self.directory = _path(directory)
        if private_directory(self.directory, create=False) != self.directory:
            raise StateError("QUERY_EXPORT_CANONICAL_DIRECTORY_REQUIRED")
        try:
            with _private_file(self.directory / "manifest.json") as source:
                raw = source.read(_MANIFEST_LIMIT + 1)
        except StateError as exc:
            raise StateError("QUERY_EXPORT_MANIFEST_UNAVAILABLE_OR_INCOMPLETE") from exc
        if len(raw) > _MANIFEST_LIMIT:
            raise StateError("QUERY_EXPORT_MANIFEST_TOO_LARGE")
        value = parse(raw)
        if (not isinstance(value, dict) or value.get("schema") != _SCHEMA or value.get("queryComplete") is not True
                or type(value.get("rowCount")) is not int or value["rowCount"] < 0
                or not isinstance(value.get("columns"), list) or not isinstance(value.get("binding"), dict)
                or value.get("bindingSha256") != digest(_json(value["binding"]).encode("utf-8"))
                or not isinstance(value.get("outputs"), dict) or not value["outputs"]
                or set(value["outputs"]) - set(_FILES.values())):
            raise StateError("QUERY_EXPORT_MANIFEST_INVALID")
        _columns(value["columns"], sqlite="rows.sqlite3" in value["outputs"])
        for record in value["outputs"].values():
            if (not isinstance(record, dict) or type(record.get("bytes")) is not int or record["bytes"] < 0
                    or not isinstance(record.get("sha256"), str) or not _HEX.fullmatch(record["sha256"])):
                raise StateError("QUERY_EXPORT_OUTPUT_METADATA_INVALID")
        self._manifest = value
        self._raw = raw

    @property
    def manifest(self):
        return deepcopy(self._manifest)

    @contextmanager
    def open(self, name):
        record = self._manifest["outputs"].get(name)
        if record is None:
            raise StateError("QUERY_EXPORT_OUTPUT_NOT_SELECTED")
        if private_directory(self.directory, create=False) != self.directory:
            raise StateError("QUERY_EXPORT_DIRECTORY_CHANGED")
        with _private_file(self.directory / name) as source:
            if os.fstat(source.fileno()).st_size != record["bytes"]:
                raise StateError("QUERY_EXPORT_FILE_CHANGED")
            checksum, total = hashlib.sha256(), 0
            while chunk := source.read(1024 * 1024):
                total += len(chunk)
                if total > record["bytes"]:
                    raise StateError("QUERY_EXPORT_FILE_CHANGED")
                checksum.update(chunk)
            if total != record["bytes"] or checksum.hexdigest() != record["sha256"]:
                raise StateError("QUERY_EXPORT_FILE_CHANGED")
            source.seek(0)
            yield source

    def inspect(self):
        for name in self._manifest["outputs"]:
            with self.open(name):
                pass
        return self.manifest

    def rows(self):
        columns = self._manifest["columns"]
        count = 0
        with self.open("rows.jsonl") as source:
            while raw := source.readline(_ROW_LIMIT + 1):
                if len(raw) > _ROW_LIMIT or not raw.endswith(b"\n"):
                    raise StateError("QUERY_EXPORT_ROW_FORMAT_INVALID")
                row = parse(raw)
                if not isinstance(row, dict) or set(row) != set(columns):
                    raise StateError("QUERY_EXPORT_ROW_COLUMNS_INVALID")
                count += 1
                if count > self._manifest["rowCount"]:
                    raise StateError("QUERY_EXPORT_ROW_COUNT_CHANGED")
                yield {name: _decode(row[name]) for name in columns}
        if count != self._manifest["rowCount"]:
            raise StateError("QUERY_EXPORT_ROW_COUNT_CHANGED")

    def copy_to(self, destination):
        """Create a verified portable private copy; the original SQL is not run."""
        target = _new_directory(destination)
        try:
            for name in self._manifest["outputs"]:
                with self.open(name) as source:
                    fd = os.open(target / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    with os.fdopen(fd, "wb") as output:
                        checksum, total = hashlib.sha256(), 0
                        while chunk := source.read(1024 * 1024):
                            total += len(chunk)
                            checksum.update(chunk)
                            output.write(chunk)
                        record = self._manifest["outputs"][name]
                        if total != record["bytes"] or checksum.hexdigest() != record["sha256"]:
                            raise StateError("QUERY_EXPORT_FILE_CHANGED")
                        output.flush()
                        os.fsync(output.fileno())
            # Publish the exact manifest bytes so transfer retains its identity.
            atomic_write(target / "manifest.json", self._raw, exclusive=True)
            return QueryExport(target)
        except BaseException:
            _cleanup(target)
            raise


def prepare_query(database, sql, parameters=(), *, destination, preview_rows=20, timeout=10):
    """Retain query text, bindings, reviewed views and a native preview."""
    bindings = _bindings(parameters)
    preview = database.query(sql, _bindings(bindings, decode=True), max_rows=preview_rows,
                             max_result_bytes=1024 * 1024, timeout=timeout)
    request = {"schema": _REQUEST, "database": str(database.directory), "sql": sql,
               "parameters": bindings, "expectedViews": list(preview.views),
               "preview": {"columns": list(preview.columns), "rows": [[_encode(v) for v in row] for row in preview.rows],
                           "truncated": preview.truncated}}
    path = _path(destination)
    if private_directory(path.parent, create=False) != path.parent:
        raise StateError("QUERY_EXPORT_CANONICAL_PARENT_REQUIRED")
    dump(path, request, exclusive=True)
    return request


def main(argv=None):
    parser = argparse.ArgumentParser(description="Review, export and reopen complete local customer SQL results.")
    commands = parser.add_subparsers(dest="command", required=True)
    prepare = commands.add_parser("prepare", help="Save SQL, typed bindings, native preview and exact selected views")
    prepare.add_argument("--database", required=True)
    prepare.add_argument("--sql-file", required=True)
    prepare.add_argument("--parameters-file")
    prepare.add_argument("--out", required=True)
    run = commands.add_parser("run", help="Export a saved reviewed query into a new private directory")
    run.add_argument("--request", required=True)
    run.add_argument("--out", required=True)
    run.add_argument("--formats", default="jsonl,csv,sqlite")
    run.add_argument("--timeout", type=float, default=300)
    run.add_argument("--max-rows", type=int)
    run.add_argument("--max-output-bytes", type=int)
    run.add_argument("--literal-csv", action="store_true")
    inspect = commands.add_parser("inspect", help="Verify and inspect an existing export, independently of its source")
    inspect.add_argument("--directory", required=True)
    copy = commands.add_parser("copy", help="Copy a verified export without querying or purchasing again")
    copy.add_argument("--directory", required=True)
    copy.add_argument("--out", required=True)
    args = parser.parse_args(argv)
    try:
        if args.command == "prepare":
            from .sqlite_dataset import DatasetDatabase
            database = DatasetDatabase(args.database, create=False)
            sql = read(_path(args.sql_file), 1024 * 1024).decode("utf-8")
            parameters = parse(read(_path(args.parameters_file), 1024 * 1024)) if args.parameters_file else []
            result = prepare_query(database, sql, _bindings(parameters, decode=True), destination=args.out)
        elif args.command == "run":
            from .sqlite_dataset import DatasetDatabase
            with _private_file(_path(args.request)) as source:
                raw = source.read(_MANIFEST_LIMIT + 1)
            if len(raw) > _MANIFEST_LIMIT:
                raise StateError("QUERY_EXPORT_REQUEST_TOO_LARGE")
            request = parse(raw)
            if (not isinstance(request, dict) or request.get("schema") != _REQUEST
                    or not isinstance(request.get("expectedViews"), list)):
                raise StateError("QUERY_EXPORT_REQUEST_INVALID")
            database = DatasetDatabase(request["database"], create=False)
            result = export_query(database, request["sql"], _bindings(request["parameters"], decode=True),
                destination=args.out, expected_views=request["expectedViews"], formats=args.formats.split(","),
                timeout=args.timeout, max_rows=args.max_rows, max_output_bytes=args.max_output_bytes,
                spreadsheet_safe=not args.literal_csv).manifest
        elif args.command == "copy":
            result = QueryExport(args.directory).copy_to(args.out).inspect()
        else:
            result = QueryExport(args.directory).inspect()
        print(_json(result))
        return 0
    except BuyerError as exc:
        print(_json({"error": exc.code}), file=sys.stderr)
        return 2
    except KeyboardInterrupt:
        print(_json({"error": "QUERY_EXPORT_INTERRUPTED"}), file=sys.stderr)
        return 130
    except (OSError, sqlite3.Error, ValueError, KeyError, TypeError) as exc:
        print(_json({"error": "QUERY_EXPORT_FAILED", "kind": type(exc).__name__}), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Typed, reusable records from the original Node retained-response reader."""
from __future__ import annotations

from dataclasses import dataclass
import json
import os
from pathlib import Path
import shutil
import tempfile
from typing import Any, Iterator
from types import SimpleNamespace

from .errors import DeliveryError, StateError
from .storage import digest, lock, parse, private_directory, read, sync_directory, write

SCHEMA = "stellar-forge.python-stream-export.v1"
MAX_EXPORT_BYTES = 256 * 1024 * 1024


@dataclass(frozen=True)
class SSEEvent:
    index: int
    event: str
    data: str
    id: str
    retry: int | None = None

    def json(self) -> Any:
        """Parse application JSON explicitly; ordinary SSE data stays text."""
        return parse(self.data.encode("utf-8"))


@dataclass(frozen=True)
class NDJSONRecord:
    index: int
    value: Any


@dataclass(frozen=True)
class StreamDelivery:
    """The fully validated native record export; original raw bytes stay retained."""
    directory: Path
    manifest: dict

    @property
    def format(self):
        return self.manifest["format"]

    @property
    def complete(self):
        return self.manifest["complete"]

    @property
    def count(self):
        return self.manifest["records"]

    @property
    def source(self):
        return dict(self.manifest["source"])

    @property
    def file(self):
        from .result import FileDelivery
        metadata = {**self.manifest["file"], "path": str(self.directory / "records.jsonl")}
        return FileDelivery({"returncode": 0, "native": {"status": "FILE_SAVED", "file": metadata}},
                            Path(metadata["path"]), self.manifest["maxExportBytes"])

    def records(self, *, start=0) -> Iterator[SSEEvent | NDJSONRecord]:
        """Resume application consumption by original zero-based record index."""
        if type(start) is not int or not 0 <= start <= self.count:
            raise DeliveryError("STREAM_RECORD_INDEX_INVALID")
        # Reuse the existing Python file reader: it hashes the complete file
        # before exposing the same open descriptor, including when resuming.
        with self.file.open() as stream:
            index = 0
            maximum = self.manifest["maxExportBytes"]
            while raw := stream.readline(maximum + 1):
                if len(raw) > maximum or not raw.endswith(b"\n"):
                    raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                value = parse(raw)
                if (not isinstance(value, dict) or value.get("format") != self.format
                        or type(value.get("index")) is not int or value["index"] != index):
                    raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                if self.format == "sse":
                    if (not all(isinstance(value.get(key), str) for key in ("event", "data", "id"))
                            or ("retry" in value and (type(value["retry"]) is not int or value["retry"] < 0))):
                        raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                    record = SSEEvent(index, value["event"], value["data"], value["id"], value.get("retry"))
                else:
                    if "value" not in value:
                        raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                    record = NDJSONRecord(index, value["value"])
                if index >= start:
                    yield record
                index += 1
            if index != self.count:
                raise DeliveryError("STREAM_EXPORT_COUNT_CHANGED")

    def events(self, *, start=0) -> Iterator[SSEEvent]:
        if self.format != "sse":
            raise DeliveryError("RESPONSE_STREAM_FORMAT_MISMATCH")
        yield from self.records(start=start)

    def ndjson(self, *, start=0) -> Iterator[Any]:
        if self.format != "ndjson":
            raise DeliveryError("RESPONSE_STREAM_FORMAT_MISMATCH")
        for record in self.records(start=start):
            yield record.value


def _manifest(directory, fingerprint):
    result = parse(read(directory / "manifest.json", 1_048_576))
    if (not isinstance(result, dict) or result.get("schema") != SCHEMA
            or result.get("requestSha256") != fingerprint
            or result.get("format") not in ("sse", "ndjson")
            or type(result.get("complete")) is not bool
            or type(result.get("records")) is not int or result["records"] < 0
            or not isinstance(result.get("source"), dict)
            or not isinstance(result.get("file"), dict)
            or result["file"].get("path") != "records.jsonl"
            or type(result.get("maxExportBytes")) is not int
            or not 1 <= result["maxExportBytes"] <= 1_073_741_824):
        raise DeliveryError("STREAM_EXPORT_MANIFEST_INVALID")
    return StreamDelivery(directory, result)


def export_stream(result, *, format=None, allow_partial=False, max_record_bytes=None,
                  max_records=None, max_export_bytes=MAX_EXPORT_BYTES, cache_dir=None):
    runtime = result._runtime
    configuration = result._response_file
    if runtime is None or not isinstance(configuration, dict):
        raise StateError("ORIGINAL_STREAM_RUNTIME_REQUIRED")
    selected = configuration.get("stream") or result.delivery.get("stream") or {}
    format = selected.get("format") if format is None else format
    if format not in ("sse", "ndjson") or type(allow_partial) is not bool:
        raise DeliveryError("RESPONSE_STREAM_READ_OPTIONS_INVALID")
    if type(max_export_bytes) is not int or not 1 <= max_export_bytes <= 1_073_741_824:
        raise DeliveryError("STREAM_EXPORT_BYTE_LIMIT_INVALID")
    options = {"allowPartial": allow_partial}
    if max_record_bytes is not None:
        options["maxRecordBytes"] = max_record_bytes
    if max_records is not None:
        options["maxRecords"] = max_records
    payload = {"schema": "stellar-forge.python-stream-request.v1", "record": result.record,
               "responseFile": configuration, "format": format, "options": options,
               "maxExportBytes": max_export_bytes}
    raw = (json.dumps(payload, sort_keys=True, ensure_ascii=False, allow_nan=False,
                      separators=(",", ":")) + "\n").encode("utf-8")
    fingerprint = digest(raw)
    if cache_dir is None:
        if result._operation_directory is None:
            raise StateError("STREAM_EXPORT_DIRECTORY_REQUIRED")
        cache_dir = result._operation_directory / "stream-exports"
    root = private_directory(Path(cache_dir))
    destination = root / fingerprint
    with lock(root):
        if destination.exists():
            private_directory(destination, create=False)
            return _manifest(destination, fingerprint)
        temporary = Path(tempfile.mkdtemp(prefix=".stream-", dir=root))
        try:
            request = temporary / "source.json"
            write(request, raw, exclusive=True)
            native = runtime.checked(["export-stream", "--input", request, "--out", temporary],
                                     mode="ORIGINAL_PYTHON_STREAM_EXPORTED", target="consumer")
            saved = _manifest(temporary, fingerprint)
            if native != saved.manifest:
                raise DeliveryError("STREAM_EXPORT_RESULT_CHANGED")
            # Publish a complete directory only after the original reader's
            # framing and both source hash passes have finished successfully.
            os.rename(temporary, destination)
            sync_directory(root)
            return StreamDelivery(destination, saved.manifest)
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)


def read_retained_response(*, checkout, config_file, result_file, cache_dir,
                           node="node", timeout=360):
    """Open an existing SF88 result for local consumption without buyer import.

    Accept the original CLI result or its existing Node/Python application
    envelope. This does not create an operation, approval or payment record.
    """
    from .result import BuyerResult
    from .runtime import Runtime
    config_raw = read(Path(config_file).expanduser().absolute(), 65536)
    result_raw = read(Path(result_file).expanduser().absolute(), 2_097_152)
    config, record = parse(config_raw), parse(result_raw)
    if not isinstance(config, dict) or not isinstance(record, dict):
        raise StateError("ORIGINAL_RETAINED_RESULT_REQUIRED")
    if record.get("mode") == "ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT":
        record = {"native": record}
    native = record.get("native")
    if (not isinstance(native, dict) or native.get("mode") != "ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT"
            or native.get("intentId") != config.get("operation", {}).get("intentId")):
        raise StateError("ORIGINAL_RETAINED_RESULT_REQUIRED")
    # Bind these original files into the export identity without changing them
    # or pretending a raw CLI result recorded a process exit code.
    if record.get("configSha256") is not None and record["configSha256"] != digest(config_raw):
        raise StateError("RESULT_CONFIG_MISMATCH")
    record = {**record, "retainedSourceFiles": {"configSha256": digest(config_raw),
                                              "resultSha256": digest(result_raw)}}
    response = config.get("responseFile")
    if not isinstance(response, dict) or not response.get("destination"):
        raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
    root = private_directory(Path(cache_dir))
    return BuyerResult(record, Path(response["destination"]), response.get("maxBytes", 67_108_864),
                       _runtime=Runtime(checkout, node=node, timeout=timeout),
                       _response_file={"maxBytes": 67_108_864, **response}, _operation_directory=root)


def export_saved_stream(*, checkout, response_file, saved, cache_dir, node="node", timeout=360, **options):
    """Consume an original SF31 writer receipt without creating a buyer attempt.

    ``response_file`` is the actual writer configuration. ``saved`` is its
    retained SAVED/FAILED responseFile view, including original stream metadata.
    The existing Node reader validates the full source hash and framed prefix.
    """
    from .runtime import Runtime
    if not isinstance(response_file, dict) or not isinstance(saved, dict):
        raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
    source = SimpleNamespace(
        record={"retainedSourceKind": "SF31_RESPONSE_FILE", "native": {"responseFile": saved}},
        delivery=saved, _response_file={"maxBytes": 67_108_864, **response_file},
        _runtime=Runtime(checkout, node=node, timeout=timeout),
        _operation_directory=private_directory(Path(cache_dir)),
    )
    return export_stream(source, **options)

"""Python access to the original Research Documents and Pipelines workspace.

Provider state, payment evidence, dossier revisions and download publication are
owned by the existing Node SDK. This module retains exact caller requests so an
interrupted application can reopen the same native action.
"""
from __future__ import annotations

from copy import deepcopy
from contextlib import contextmanager
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import re
import tempfile
import threading

from .errors import NativeError, StateError
from .result import FileDelivery
from .runtime import Runtime
from .storage import digest, dump, lock, parse, private_directory, read

_CALL = "stellar-forge.research-python-call.v1"
_CLIENT = "stellar-forge.research-python-client.v1"
_RECORD = "stellar-forge.research-python-attempt.v1"
_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,159}")
_WORKSPACE = re.compile(r"research_[a-f0-9]{64}")
_HASH = re.compile(r"[a-f0-9]{64}")
_LIMIT = 16 * 1024 * 1024


def _json(value):
    try:
        return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True,
                          separators=(",", ":")).encode("utf-8")
    except (ValueError, TypeError):
        raise StateError("RESEARCH_JSON_REQUIRED") from None


def _now():
    return datetime.now(timezone.utc).isoformat()


def _request_id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise StateError("RESEARCH_REQUEST_ID_REQUIRED")
    return value


class ResearchError(NativeError):
    """Original native failure, including uncertain writes and published files."""
    def __init__(self, record, *, request_id=None):
        self.record = deepcopy(record)
        native = record.get("native") or {}
        super().__init__(record.get("runtimeError") or native.get("error") or
                         "RESEARCH_NATIVE_CALL_FAILED",
                         returncode=record.get("returncode"), operation=request_id)
        self.request_id = request_id
        self.status = native.get("status")
        self.outcome_unknown = native.get("outcomeUnknown", record.get("outcomeUnknown", False))
        self.recovery = native.get("recovery")
        self.operation_id = native.get("operationId")
        self.destination_published = native.get("destinationPublished", False)
        self.file = deepcopy(native.get("file"))
        self.source_cleanup_failed = native.get("sourceCleanupFailed")


class _Cancellation(threading.Event):
    def __init__(self, external=None):
        super().__init__()
        self.external = external

    def is_set(self):
        return super().is_set() or self.external is not None and self.external.is_set()


def _completed_reply(record):
    native = record.get("native") or {}
    return (record.get("returncode") == 0 and native.get("mode") == "RESEARCH_WORKSPACE_BRIDGE"
            and native.get("ok") is True and "result" in native)


def _value(record, request_id=None):
    native = record.get("native") or {}
    if not _completed_reply(record):
        raise ResearchError(record, request_id=request_id)
    result = deepcopy(native["result"])
    if isinstance(result, dict) and (record.get("runtimeError") or record.get("interrupted")):
        result["pythonRuntime"] = {"error": record.get("runtimeError"),
                                   "interrupted": bool(record.get("interrupted")),
                                   "completedReply": True}
    if isinstance(result, dict) and native.get("sourceCleanupFailed"):
        result["sourceCleanupFailed"] = native["sourceCleanupFailed"]
    return result


def _file_delivery(value):
    if (not isinstance(value, dict) or not isinstance(value.get("file"), str) or
            not Path(value["file"]).is_absolute() or type(value.get("bytes")) is not int or
            not 0 <= value["bytes"] <= 256 * 1024 * 1024 or
            not isinstance(value.get("sha256"), str) or not _HASH.fullmatch(value["sha256"])):
        raise StateError("RESEARCH_DOWNLOAD_RECORD_INVALID")
    path = Path(value["file"])
    return FileDelivery({"returncode": 0, "native": {
        "status": "RETAINED_RESEARCH_FILE", "file": {"path": str(path), **value}}},
        path, 256 * 1024 * 1024)


class ResearchWorkspace:
    def __init__(self, *, checkout, connection_file=None, directory, node="node",
                 environment=None, timeout=360, request_timeout_ms=120000,
                 expected_workspace_id=None):
        if (type(request_timeout_ms) is not int or not 1000 <= request_timeout_ms <= 900000 or
                expected_workspace_id is not None and (not isinstance(expected_workspace_id, str) or not _WORKSPACE.fullmatch(expected_workspace_id))):
            raise StateError("RESEARCH_CLIENT_OPTIONS_INVALID")
        self.directory = private_directory(Path(directory))
        self.connection_file = (Path(connection_file).expanduser().absolute()
                                if connection_file is not None else None)
        self.runtime = Runtime(checkout, node=node, environment=environment,
                               timeout=timeout, output_limit=_LIMIT)
        self.request_timeout_ms = request_timeout_ms
        self._condition = threading.Condition()
        self._active = set()
        self._closed = False
        private_directory(self.directory / "calls")
        with lock(self.directory):
            path = self.directory / "client.json"
            if path.exists():
                current = parse(read(path, 65536))
                if current.get("schema") != _CLIENT or not _WORKSPACE.fullmatch(current.get("workspaceId", "")):
                    raise StateError("RESEARCH_CLIENT_STATE_CHANGED")
                if expected_workspace_id and expected_workspace_id != current["workspaceId"]:
                    raise StateError("RESEARCH_WORKSPACE_CHANGED")
                expected_workspace_id = current["workspaceId"]
        self.workspace_id = expected_workspace_id

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def close(self):
        """Cancel local in-flight calls and detach; the original server stays open."""
        with self._condition:
            self._closed = True
            for event in self._active:
                event.set()
            while self._active:
                self._condition.wait(0.5)

    def _bind(self, workspace_id):
        if not isinstance(workspace_id, str) or not _WORKSPACE.fullmatch(workspace_id):
            raise StateError("RESEARCH_WORKSPACE_ID_INVALID")
        with lock(self.directory):
            path = self.directory / "client.json"
            prior = parse(read(path, 65536)) if path.exists() else None
            if (self.workspace_id and self.workspace_id != workspace_id or
                    prior and (prior.get("schema") != _CLIENT or prior.get("workspaceId") != workspace_id)):
                raise StateError("RESEARCH_WORKSPACE_CHANGED")
            if prior is None:
                dump(path, {"schema": _CLIENT, "workspaceId": workspace_id,
                            "firstObservedAt": _now()}, exclusive=True)
            self.workspace_id = workspace_id

    @contextmanager
    def _operation(self, cancel_event=None, *, owned_event=None):
        if owned_event is not None:
            with self._condition:
                if owned_event not in self._active:
                    raise StateError("RESEARCH_CALL_OWNERSHIP_LOST")
            yield owned_event
            return
        if cancel_event is not None and not isinstance(cancel_event, threading.Event):
            raise StateError("NATIVE_CANCEL_EVENT_INVALID")
        event = _Cancellation(cancel_event)
        with self._condition:
            if self._closed:
                raise StateError("RESEARCH_CLIENT_CLOSED")
            self._active.add(event)
        try:
            yield event
        finally:
            with self._condition:
                self._active.discard(event)
                self._condition.notify_all()

    def _invoke(self, action, value, request_file, *, mutating=False, local=False, event):
        if local and (action not in {"commerce-operation", "commerce-archive-inspect",
                                    "commerce-archive-receive"} or
                      mutating and action != "commerce-archive-receive"):
            raise StateError("RESEARCH_LOCAL_ACTION_INVALID")
        request = {"schema": _CALL, "action": action, "input": deepcopy(value),
                   "timeoutMs": self.request_timeout_ms}
        if self.connection_file is not None:
            request["connectionFile"] = str(self.connection_file)
        if self.workspace_id and not local:
            request["expectedWorkspaceId"] = self.workspace_id
        _json(request)
        dump(request_file, request, exclusive=True)
        try:
            native = self.runtime.run(["--request", request_file], target="research",
                                      cancel_event=event)
            record = {"schema": _RECORD, "returncode": native.returncode,
                      "runtimeError": native.error, "interrupted": native.interrupted,
                      "processStarted": True,
                      "outcomeUnknown": bool(mutating and (native.interrupted or native.output is None)),
                      "native": native.output, "finishedAt": _now()}
        except NativeError as error:
            record = {"schema": _RECORD, "returncode": None, "runtimeError": error.code,
                      "processStarted": False, "outcomeUnknown": False, "native": None, "finishedAt": _now()}
        except StateError as error:
            if error.code not in {"NATIVE_CANCELLED_BEFORE_START", "NATIVE_CANCEL_EVENT_INVALID",
                    "ORIGINAL_RUNTIME_TARGET_INVALID", "ORIGINAL_APPLICATION_RUNTIME_REQUIRED"}:
                raise
            record = {"schema": _RECORD, "returncode": None, "runtimeError": error.code,
                      "processStarted": False, "outcomeUnknown": False, "native": None, "finishedAt": _now()}
        result = record.get("native") or {}
        if _completed_reply(record):
            record["outcomeUnknown"] = False
        elif "outcomeUnknown" in result:
            record["outcomeUnknown"] = bool(result["outcomeUnknown"])
        if result.get("workspaceId"):
            if local:
                raise StateError("RESEARCH_LOCAL_WORKSPACE_CHANGED")
            self._bind(result["workspaceId"])
        return record

    def _read(self, action, value=None, *, cancel_event=None, _owned_event=None, local=False):
        with self._operation(cancel_event, owned_event=_owned_event) as event:
            with tempfile.TemporaryDirectory(prefix=".research-read-", dir=self.directory) as temporary:
                record = self._invoke(action, value or {}, Path(temporary) / "request.json",
                                      event=event, local=local)
            return _value(record)

    def _directory_for_call(self, request_id, *, create=False):
        selected = self.directory / "calls" / digest(_request_id(request_id).encode())
        return private_directory(selected, create=create)

    def _write(self, action, value, *, request_id, replay_safe, resume=False, cancel_event=None,
               local=False):
        with self._operation(cancel_event) as event:
            return self._write_call(action, value, request_id=request_id, replay_safe=replay_safe,
                                    resume=resume, event=event, local=local)

    def _write_call(self, action, value, *, request_id, replay_safe, resume, event, local=False):
        request_id = _request_id(request_id)
        if local and action != "commerce-archive-receive":
            raise StateError("RESEARCH_LOCAL_ACTION_INVALID")
        if self.workspace_id is None and not local:
            self._read("status", _owned_event=event)
        value = parse(_json(value))
        selected = self._directory_for_call(request_id, create=True)
        with lock(selected):
            path = selected / "request.json"
            identity = {"schema": _CALL, "requestId": request_id, "action": action,
                        "input": value, "workspaceId": None if local else self.workspace_id,
                        "replaySafe": bool(replay_safe), **({"local": True} if local else {})}
            if path.exists():
                saved = parse(read(path, 32 * 1024 * 1024))
                if _json({k: saved[k] for k in identity}) != _json(identity):
                    raise StateError("RESEARCH_REQUEST_ID_REUSED")
            else:
                saved = {**identity, "createdAt": _now()}
                dump(path, saved, exclusive=True)
            attempts = private_directory(selected / "attempts")
            existing = sorted(p for p in attempts.iterdir() if p.is_dir())
            previous = None
            if existing:
                result_path = existing[-1] / "result.json"
                previous = parse(read(result_path, _LIMIT)) if result_path.exists() else {
                    "schema": _RECORD, "returncode": None, "native": None,
                    "runtimeError": "RESEARCH_CALL_INTERRUPTED", "outcomeUnknown": True}
                native = previous.get("native") or {}
                if _completed_reply(previous):
                    return _value(previous, request_id)
                if not resume:
                    raise ResearchError(previous, request_id=request_id)
                if not replay_safe and previous.get("processStarted") is not False:
                    raise StateError("RESEARCH_RECONCILE_DOSSIER_BEFORE_NEW_WRITE")
            attempt = private_directory(attempts / str(len(existing) + 1).zfill(8))
            dump(attempt / "attempt.json", {"requestId": request_id, "startedAt": _now(),
                                           "number": len(existing) + 1}, exclusive=True)
            try:
                record = self._invoke(action, value, attempt / "call.json", mutating=True,
                                      event=event, local=local)
            except StateError as error:
                if error.code not in {"RESEARCH_CLIENT_CLOSED", "NATIVE_CANCEL_EVENT_INVALID"}:
                    raise
                record = {"schema": _RECORD, "returncode": None, "runtimeError": error.code,
                          "processStarted": False, "outcomeUnknown": False, "native": None, "finishedAt": _now()}
            dump(attempt / "result.json", record, exclusive=True)
            return _value(record, request_id)

    def call_record(self, request_id):
        selected = self._directory_for_call(request_id)
        request = parse(read(selected / "request.json", 32 * 1024 * 1024))
        attempts = sorted(p for p in (selected / "attempts").iterdir() if p.is_dir()) if (selected / "attempts").exists() else []
        last = attempts[-1] / "result.json" if attempts else None
        return {"request": request, "attempts": len(attempts),
                "result": parse(read(last, _LIMIT)) if last and last.exists() else None}

    def calls(self, *, offset=0, limit=100):
        if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 250:
            raise StateError("RESEARCH_CALL_PAGE_INVALID")
        records = []
        for selected in (self.directory / "calls").iterdir():
            if selected.is_dir() and (selected / "request.json").is_file():
                request = parse(read(selected / "request.json", 32 * 1024 * 1024))
                records.append({key: request[key] for key in
                                ("requestId", "action", "createdAt", "workspaceId", "replaySafe")})
        records.sort(key=lambda item: (item["createdAt"], item["requestId"]))
        end = offset + limit
        return {"items": records[offset:end], "total": len(records),
                "nextOffset": end if end < len(records) else None}

    def resume(self, request_id, *, cancel_event=None):
        """Replay only an original native idempotent request, with unchanged IDs."""
        saved = self.call_record(request_id)["request"]
        return self._write(saved["action"], saved["input"], request_id=request_id,
                           replay_safe=saved["replaySafe"], resume=True, cancel_event=cancel_event,
                           local=saved.get("local", False))

    def status(self, *, cancel_event=None):
        return self._read("status", cancel_event=cancel_event)

    def dossiers(self, **options):
        return self._read("dossiers", {"options": options})

    def metadata(self, dossier_id, *, revision=None):
        return self._read("metadata", {"dossierId": dossier_id,
                          "options": {} if revision is None else {"revision": revision}})

    def section(self, dossier_id, section, **options):
        return self._read("section", {"dossierId": dossier_id, "options": {"section": section, **options}})

    def compare(self, dossier_id, **options):
        return self._read("compare", {"dossierId": dossier_id, "options": options})

