      url.search || url.hash || (url.pathname && url.pathname !== '/') ||
      (url.port && (!Number.isInteger(Number(url.port)) || Number(url.port) < 1 || Number(url.port) > 65535))) {
    throw proxyError('PROXY_MUST_BE_HTTP_HOST_PORT_WITHOUT_CREDENTIALS');
  }
