"""Report what the schema says about itself, before generating anything.

Two artefacts share every property name in DCAT-US: the JSON key and the RDF
property it stands for. A generator has to reconcile them, and the act of
reconciling exposes places where the schema disagrees with itself. Those
disagreements are recorded here rather than silently resolved.
"""

from __future__ import annotations

from collections import Counter, defaultdict

from .schema import ClassDef, Property, expand


def binding_of(prop: Property) -> tuple[str | None, str | None, str | None]:
    """The (iri, coercion, container) triple a property declares."""
    if prop.iri is None:
        return (None, None, None)
    if prop.range_is_resource:
        coercion = "@id"
    else:
        coercion = prop.declared_datatype
    container = "@set" if prop.is_list else None
    return (prop.iri, coercion, container)


def term_bindings(classes: dict[str, ClassDef]) -> dict[str, dict[str, tuple]]:
    """term -> {owning class -> binding}, bound properties only."""
    out: dict[str, dict[str, tuple]] = defaultdict(dict)
    for cls in classes.values():
        for prop in cls.properties.values():
            if prop.bound:
                out[prop.name][cls.name] = binding_of(prop)
    return dict(out)


def resolve_term(owners: dict[str, tuple]) -> tuple[tuple, dict[str, tuple]]:
    """Split a term into one dominant binding plus per-class overrides.

    Dominance is by count of owning classes, ties broken on the sorted
    binding so a rebuild is byte-identical.
    """
    counts = Counter(owners.values())
    dominant = sorted(counts.items(), key=lambda kv: (-kv[1], str(kv[0])))[0][0]
    overrides = {c: b for c, b in sorted(owners.items()) if b != dominant}
    return dominant, overrides


def audit(classes: dict[str, ClassDef], namespaces: dict[str, str]) -> dict:
    bindings = term_bindings(classes)

    unbound = [
        {"class": cls.name, "property": p.name, "requirementLevel": p.requirement_level,
         "range": p.range, "jsonTypes": list(p.json_types), "ref": p.ref}
        for cls in classes.values()
        for p in cls.properties.values()
        if not p.bound
    ]

    iri_conflicts, shape_conflicts = [], []
    for term, owners in sorted(bindings.items()):
        distinct_iris = {b[0] for b in owners.values()}
        dominant, overrides = resolve_term(owners)
        if len(distinct_iris) > 1:
            iri_conflicts.append({
                "term": term,
                "dominant": {"iri": dominant[0],
                             "classes": sorted(c for c, b in owners.items() if b[0] == dominant[0])},
                "overrides": [{"class": c, "iri": b[0]} for c, b in sorted(overrides.items())
                              if b[0] != dominant[0]],
            })
        elif overrides:
            shape_conflicts.append({
                "term": term,
                "iri": dominant[0],
                "dominant": {"coercion": dominant[1], "container": dominant[2],
                             "classes": sorted(c for c, b in owners.items() if b == dominant)},
                "overrides": [{"class": c, "coercion": b[1], "container": b[2]} for c, b in sorted(overrides.items())],
            })

    unresolvable = []
    for cls in classes.values():
        if cls.rdf_class and expand(cls.rdf_class, namespaces) is None:
            unresolvable.append({"class": cls.name, "curie": cls.rdf_class, "kind": "rdfClass"})
        for p in cls.properties.values():
            if p.iri and expand(p.iri, namespaces) is None:
                unresolvable.append({"class": cls.name, "property": p.name, "curie": p.iri, "kind": "property"})

    missing_default_type = sorted(c.name for c in classes.values() if not c.default_type)

    total_props = sum(len(c.properties) for c in classes.values())
    return {
        "counts": {
            "classes": len(classes),
            "classesWithRdfClass": sum(1 for c in classes.values() if c.rdf_class),
            "properties": total_props,
            "propertiesWithIri": total_props - len(unbound),
            "propertiesWithoutIri": len(unbound),
            "distinctTerms": len(bindings),
            "termsWithIriConflict": len(iri_conflicts),
            "termsWithShapeConflict": len(shape_conflicts),
        },
        "unboundProperties": sorted(unbound, key=lambda d: (d["class"], d["property"])),
        "iriConflicts": iri_conflicts,
        "shapeConflicts": shape_conflicts,
        "unresolvablePrefixes": unresolvable,
        "classesWithoutDefaultType": missing_default_type,
    }

"""Generate the JSON-LD context from the JSON Schema.

The context is derived, never hand-edited. Every term maps to an IRI the
schema already declared, so the schema stays the single source of truth and
the two artefacts cannot drift apart.
"""

from __future__ import annotations

from .audit import binding_of, resolve_term, term_bindings
from .schema import ClassDef

DECLARED = "declared"
OBSERVED = "observed"


def _term_definition(binding: tuple, lenient_terms: set[str] | None, term: str) -> dict | str:
    iri, coercion, container = binding
    if lenient_terms and term in lenient_terms and coercion == "@id":
        coercion = None
    definition: dict = {"@id": iri}
    if coercion:
        definition["@type"] = coercion
    if container:
        definition["@container"] = container
    if list(definition) == ["@id"]:
        return iri
    return definition


def build_context(
    classes: dict[str, ClassDef],
    namespaces: dict[str, str],
    lenient_terms: set[str] | None = None,
) -> dict:
    ctx: dict = {"@version": 1.1}
    ctx.update({prefix: iri for prefix, iri in sorted(namespaces.items())})

    scoped: dict[str, dict] = {name: {} for name in classes}
    bindings = term_bindings(classes)
    terms: dict[str, object] = {}

    for term, owners in sorted(bindings.items()):
        dominant, overrides = resolve_term(owners)
        terms[term] = _term_definition(dominant, lenient_terms, term)
        for cls_name, binding in overrides.items():
            scoped[cls_name][term] = _term_definition(binding, lenient_terms, term)

    for cls in sorted(classes.values(), key=lambda c: c.name):
        if not cls.rdf_class:
            continue
        if scoped[cls.name]:
            ctx[cls.name] = {"@id": cls.rdf_class, "@context": dict(sorted(scoped[cls.name].items()))}
        else:
            ctx[cls.name] = cls.rdf_class

    ctx.update(dict(sorted(terms.items())))
    return {"@context": ctx}


def context_stats(context: dict) -> dict:
    ctx = context["@context"]
    scoped = {k: v for k, v in ctx.items() if isinstance(v, dict) and "@context" in v}
    return {
        "terms": sum(1 for k in ctx if not k.startswith("@")),
        "typeScopedClasses": sorted(scoped),
        "scopedOverrides": sum(len(v["@context"]) for v in scoped.values()),
        "idCoerced": sum(1 for v in ctx.values() if isinstance(v, dict) and v.get("@type") == "@id"),
        "datatypeCoerced": sum(
            1 for v in ctx.values()
            if isinstance(v, dict) and isinstance(v.get("@type"), str) and v["@type"].startswith("xsd:")
        ),
        "setContainers": sum(1 for v in ctx.values() if isinstance(v, dict) and v.get("@container") == "@set"),
    }

"""Expand the published examples and measure what reaches RDF.

The measurement is the point. A context that is never run against the corpus
is a claim; a context that is run and counted is evidence.
"""

from __future__ import annotations

import json
import re
from collections import Counter
from pathlib import Path

from rdflib import Dataset as RDFDataset
from rdflib import URIRef

from .audit import binding_of
from .schema import ClassDef

ABSOLUTE_IRI = re.compile(r"^[A-Za-z][A-Za-z0-9+.\-]*:")
DCAT_NS = "http://www.w3.org/ns/dcat#"
RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type"
DEFAULT_BASE = "https://example.gov/"


def ranked(counter: Counter, limit: int) -> list:
    """Counter.most_common with ties broken on the key.

    Insertion order varies with filesystem iteration, so an unsorted tie makes
    the committed measurements differ between machines for no reason.
    """
    return [list(item) for item in sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))[:limit]]


def load_examples(examples_dir: Path, quality: str = "good") -> list[Path]:
    return sorted(Path(examples_dir).glob(f"*/{quality}/*.json"))


def expand_file(path: Path, context: dict | None, base: str = DEFAULT_BASE):
    """Expand one example, optionally injecting a context. Returns (graph, error)."""
    doc = json.loads(path.read_text())
    if context is not None:
        if isinstance(doc, dict):
            doc = {**context, **{k: v for k, v in doc.items() if k != "@context"}}
        else:
            doc = {**context, "@graph": doc}
    graph = RDFDataset()
    try:
        graph.parse(data=json.dumps(doc), format="json-ld", base=base)
    except Exception as exc:  # noqa: BLE001 - the failure itself is a result
        return None, f"{type(exc).__name__}: {exc}"
    return graph, None


def verbatim_strings(node, out: set[str] | None = None) -> set[str]:
    """Every string the document actually contains, at any depth.

    An IRI in the output that appears here came from the data. One that does
    not was assembled by the processor out of a label.
    """
    out = set() if out is None else out
    if isinstance(node, list):
        for item in node:
            verbatim_strings(item, out)
    elif isinstance(node, dict):
        for key, child in node.items():
            if isinstance(key, str):
                out.add(key)
            verbatim_strings(child, out)
    elif isinstance(node, str):
        out.add(node)
    return out


def measure(files: list[Path], context: dict | None, base: str = DEFAULT_BASE) -> dict:
    """Expand every example and count what survives.

    `manufacturedIris` are object IRIs under the expansion base that the
    document never declared. They are identifiers the processor invented from
    a plain string, which is the failure mode a JSON-only pipeline cannot see.
    """
    triples = 0
    zero_files: list[str] = []
    failures: list[dict] = []
    predicates: Counter = Counter()
    types: Counter = Counter()
    manufactured: Counter = Counter()
    manufactured_files: set[str] = set()

    for path in files:
        graph, error = expand_file(path, context, base)
        if error:
            failures.append({"file": path.name, "error": error})
            continue
        written = verbatim_strings(json.loads(path.read_text()))
        count = 0
        for subject, predicate, obj, _ in graph.quads((None, None, None, None)):
            count += 1
            predicate_iri = str(predicate)
            predicates[predicate_iri] += 1
            if predicate_iri == RDF_TYPE:
                types[str(obj)] += 1
            elif isinstance(obj, URIRef) and str(obj).startswith(base) and str(obj) not in written:
                manufactured[str(obj)] += 1
                manufactured_files.add(path.name)
        triples += count
        if count == 0:
            zero_files.append(path.name)

    return {
        "files": len(files),
        "triples": triples,
        "distinctPredicates": len(predicates),
        "dcatNamespaceTriples": sum(v for k, v in predicates.items() if k.startswith(DCAT_NS)),
        "zeroTripleFiles": len(zero_files),
        "zeroTripleFileNames": zero_files,
        "failures": failures,
        "topPredicates": ranked(predicates, 15),
        "typeValues": ranked(types, 30),
        "manufacturedIris": ranked(manufactured, 20),
        "manufacturedIriCount": sum(manufactured.values()),
        "manufacturedIriFiles": len(manufactured_files),
    }


def _binding_index(classes: dict[str, ClassDef]) -> tuple[dict[str, tuple], dict[str, dict[str, tuple]]]:
    from .audit import resolve_term, term_bindings

    dominant: dict[str, tuple] = {}
    scoped: dict[str, dict[str, tuple]] = {}
    for term, owners in term_bindings(classes).items():
        dom, overrides = resolve_term(owners)
        dominant[term] = dom
        for cls_name, binding in overrides.items():
            scoped.setdefault(cls_name, {})[term] = binding
    return dominant, scoped


def scan_bare_values(files: list[Path], classes: dict[str, ClassDef]) -> dict:
    """Find IRI-coerced terms whose published values are not IRIs.

    These are the properties where the JSON carries a label and the schema
    promises a resource. Under a faithful context they become relative IRIs
    resolved against the base, which is how a catalogue silently invents
    identifiers that nothing else in the world uses.
    """
    dominant, scoped = _binding_index(classes)
    offenders: dict[str, Counter] = {}
    per_file: dict[str, set[str]] = {}

    def binding_for(term: str, enclosing_type: str | None):
        if enclosing_type and term in scoped.get(enclosing_type, {}):
            return scoped[enclosing_type][term]
        return dominant.get(term)

    def walk(node, enclosing_type: str | None, filename: str):
        if isinstance(node, list):
            for item in node:
                walk(item, enclosing_type, filename)
            return
        if not isinstance(node, dict):
            return
        node_type = node.get("@type") if isinstance(node.get("@type"), str) else enclosing_type
        for key, value in node.items():
            if key.startswith("@"):
                continue
            binding = binding_for(key, node_type)
            values = value if isinstance(value, list) else [value]
            for item in values:
                if isinstance(item, (dict, list)):
                    walk(item, node_type, filename)
                elif isinstance(item, str) and binding and binding[1] == "@id":
                    if not ABSOLUTE_IRI.match(item):
                        offenders.setdefault(key, Counter())[item] += 1
                        per_file.setdefault(filename, set()).add(key)

    for path in files:
        walk(json.loads(path.read_text()), None, path.name)

    return {
        "terms": {
            term: {"occurrences": sum(counter.values()), "examples": [v for v, _ in counter.most_common(3)]}
            for term, counter in sorted(offenders.items())
        },
        "termCount": len(offenders),
        "occurrenceTotal": sum(sum(c.values()) for c in offenders.values()),
        "affectedFiles": len(per_file),
    }

"""Read the DCAT-US 3.0 JSON Schema as the single source of truth.

Nothing in this module invents RDF. Every IRI it returns was already written
into the schema by the DCAT-US maintainers, in the `_oldDocs` blocks that were
carried over when the SHACL definition was retired.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path

# Ranges are prose in places, so a declared range is matched by prefix.
LITERAL_RANGE_PREFIXES = ("rdfs:Literal", "xsd:")
ANY_RESOURCE_RANGES = {"rdfs:Resource"}


@dataclass(frozen=True)
class Property:
    name: str
    owner: str
    iri: str | None
    range: str | None
    requirement_level: str | None
    json_types: tuple[str, ...]
    is_list: bool
    ref: str | None
    title: str | None
    description: str | None

    @property
    def bound(self) -> bool:
        return self.iri is not None

    @property
    def range_is_literal(self) -> bool:
        if not self.range:
            return False
        return self.range.startswith(LITERAL_RANGE_PREFIXES)

    @property
    def range_is_resource(self) -> bool:
        if not self.range:
            return False
        return not self.range_is_literal

    @property
    def declared_datatype(self) -> str | None:
        """A single xsd datatype, only when the schema names exactly one.

        `rdfs:Literal (typed as xsd:date, xsd:dateTime, xsd:gYear or
        xsd:gYearMonth)` names four and is deliberately not coerced.
        """
        if not self.range:
            return None
        hits = sorted({t for t in _xsd_tokens(self.range)})
        if len(hits) == 1:
            return hits[0]
        return None


def _xsd_tokens(text: str) -> list[str]:
    out, cursor = [], 0
    while True:
        i = text.find("xsd:", cursor)
        if i == -1:
            return out
        j = i + 4
        while j < len(text) and (text[j].isalnum() or text[j] in "_-"):
            j += 1
        out.append(text[i:j])
        cursor = j


@dataclass(frozen=True)
class ClassDef:
    name: str
    rdf_class: str | None
    title: str | None
    description: str | None
    required: tuple[str, ...]
    default_type: str | None
    properties: dict[str, Property] = field(default_factory=dict)


def _walk_ref(node: dict) -> str | None:
    """Find the definition a property points at, through arrays and anyOf."""
    if not isinstance(node, dict):
        return None
    if "$ref" in node:
        return str(node["$ref"]).rstrip("/").split("/")[-1]
    for key in ("items", "contains"):
        if key in node:
            found = _walk_ref(node[key])
            if found:
                return found
    for key in ("anyOf", "oneOf", "allOf"):
        for branch in node.get(key, []):
            found = _walk_ref(branch)
            if found:
                return found
    return None


def _json_types(node: dict) -> tuple[tuple[str, ...], bool]:
    raw = node.get("type")
    types: list[str] = []
    if isinstance(raw, str):
        types = [raw]
    elif isinstance(raw, list):
        types = [t for t in raw if isinstance(t, str)]
    is_list = "array" in types
    if not types:
        for key in ("anyOf", "oneOf"):
            for branch in node.get(key, []):
                sub, sub_list = _json_types(branch)
                types.extend(sub)
                is_list = is_list or sub_list
    return tuple(dict.fromkeys(t for t in types if t != "null")), is_list


def _property_blocks(raw: dict) -> tuple[dict, tuple[str, ...]]:
    """Collect declared properties, including those inside anyOf/oneOf branches.

    Concept and Identifier accept either a bare string or an object, so their
    properties live one level down in `anyOf`. Reading only the top level
    silently drops the two most frequently instantiated classes in the
    example corpus.
    """
    props: dict = dict(raw.get("properties") or {})
    required: list[str] = list(raw.get("required") or ())
    for key in ("anyOf", "oneOf", "allOf"):
        for branch in raw.get(key, []):
            if not isinstance(branch, dict):
                continue
            for prop_name, node in (branch.get("properties") or {}).items():
                props.setdefault(prop_name, node)
            required.extend(branch.get("required") or ())
    return props, tuple(dict.fromkeys(required))


def load_classes(definitions_dir: Path) -> dict[str, ClassDef]:
    classes: dict[str, ClassDef] = {}
    for path in sorted(Path(definitions_dir).glob("*.json")):
        raw = json.loads(path.read_text())
        name = path.stem
        old = raw.get("_oldDocs") or {}
        declared, required = _property_blocks(raw)
        props: dict[str, Property] = {}
        for prop_name, node in declared.items():
            if prop_name.startswith("@"):
                continue
            prop_old = node.get("_oldDocs") or {}
            json_types, is_list = _json_types(node)
            props[prop_name] = Property(
                name=prop_name,
                owner=name,
                iri=prop_old.get("uri"),
                range=prop_old.get("range"),
                requirement_level=node.get("requirementLevel"),
                json_types=json_types,
                is_list=is_list,
                ref=_walk_ref(node),
                title=node.get("title"),
                description=node.get("description"),
            )
        type_node = declared.get("@type") or {}
        classes[name] = ClassDef(
            name=name,
            rdf_class=old.get("rdfClass"),
            title=raw.get("title"),
            description=raw.get("description"),
            required=required,
            default_type=type_node.get("default"),
            properties=props,
        )
    return classes


def load_namespaces(path: Path) -> dict[str, str]:
    raw = json.loads(Path(path).read_text())
    return {k: v["iri"] for k, v in raw["prefixes"].items()}


def load_namespace_records(path: Path) -> dict[str, dict]:
    return json.loads(Path(path).read_text())["prefixes"]


def expand(curie: str, namespaces: dict[str, str]) -> str | None:
    """Expand a prefixed name. Returns None when the prefix is not declared."""
    if not curie or "://" in curie:
        return curie or None
    if ":" not in curie:
        return None
    prefix, local = curie.split(":", 1)
    base = namespaces.get(prefix)
    return f"{base}{local}" if base else None

"""Generate SHACL shapes from the same JSON Schema the context comes from.

This is the whole argument for generation in one file. The shapes and the
context are two projections of one source, so they cannot contradict each
other. The question 'which of the two artefacts is authoritative' stops
being answerable, because neither is: the schema is.
"""

from __future__ import annotations

from .schema import ClassDef, Property

SHAPES_PREFIX = "shp"
LITERAL_RANGES = {"rdfs:Literal"}
ANY_RESOURCE = {"rdfs:Resource"}


def _range_head(range_text: str | None) -> str | None:
    """The CURIE at the front of a range, ignoring any prose after it."""
    if not range_text:
        return None
    head = range_text.strip().split()[0].strip("(),.")
    return head if ":" in head else None


def _escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "")


def _constraints(prop: Property, known_classes: set[str]) -> list[str]:
    out = [f"sh:path {prop.iri}"]
    if prop.title:
        out.append(f'sh:name "{_escape(prop.title)}"')
    if prop.description:
        out.append(f'sh:description "{_escape(prop.description)}"')

    head = _range_head(prop.range)
    datatype = prop.declared_datatype

    if prop.range_is_resource:
        if head in ANY_RESOURCE or head is None:
            out.append("sh:nodeKind sh:IRI")
        elif head in known_classes or (head and head.split(":")[-1][:1].isupper()):
            out.append("sh:nodeKind sh:BlankNodeOrIRI")
            out.append(f"sh:class {head}")
        else:
            out.append("sh:nodeKind sh:BlankNodeOrIRI")
    elif datatype:
        out.append(f"sh:datatype {datatype}")
    else:
        out.append("sh:nodeKind sh:Literal")

    if prop.requirement_level == "Mandatory":
        out.append("sh:minCount 1")
    if not prop.is_list:
        out.append("sh:maxCount 1")
    if prop.requirement_level:
        out.append(f'sh:severity {"sh:Violation" if prop.requirement_level == "Mandatory" else "sh:Warning"}')
    return out


def build_shapes(classes: dict[str, ClassDef], namespaces: dict[str, str], shapes_base: str) -> str:
    known = {c.rdf_class for c in classes.values() if c.rdf_class}
    lines: list[str] = []
    for prefix, iri in sorted(namespaces.items()):
        lines.append(f"@prefix {prefix}: <{iri}> .")
    lines.append(f"@prefix {SHAPES_PREFIX}: <{shapes_base}> .")
    lines.append("@prefix sh: <http://www.w3.org/ns/shacl#> .")
    lines.append("")
    lines.append(f"<{shapes_base.rstrip('#')}>")
    lines.append("    a <http://www.w3.org/2002/07/owl#Ontology> ;")
    lines.append('    <http://purl.org/dc/terms/title> "DCAT-US 3.0 generated SHACL shapes" ;')
    lines.append(
        '    <http://purl.org/dc/terms/description> "Generated from the DCAT-US 3.0 JSON Schema '
        'definitions. Do not edit by hand: edit the schema and regenerate." .'
    )
    lines.append("")

    for cls in sorted(classes.values(), key=lambda c: c.name):
        if not cls.rdf_class:
            continue
        bound = [p for p in cls.properties.values() if p.bound]
        if not bound:
            continue
        lines.append(f"{SHAPES_PREFIX}:{cls.name}Shape")
        lines.append("    a sh:NodeShape ;")
        lines.append(f"    sh:targetClass {cls.rdf_class} ;")
        if cls.title:
            lines.append(f'    sh:name "{_escape(cls.title)}" ;')
        if cls.description:
            lines.append(f'    sh:description "{_escape(cls.description)}" ;')
        for index, prop in enumerate(sorted(bound, key=lambda p: p.name)):
            body = " ;\n        ".join(_constraints(prop, known))
            terminator = " ;" if index < len(bound) - 1 else " ."
            lines.append(f"    sh:property [\n        {body} ;\n    ]{terminator}")
        lines.append("")
    return "\n".join(lines) + "\n"

"""Run SHACL over the expanded corpus, and say how much of it was reached.

A SHACL run reports `conforms` whether or not any shape matched anything.
That makes a green result ambiguous, so every run here also reports how many
focus nodes the shapes actually selected. Zero focus nodes and zero
violations is not a pass, it is a miss.
"""

from __future__ import annotations

from pathlib import Path

from pyshacl import validate as pyshacl_validate
from rdflib import RDF, Graph, URIRef
from rdflib.namespace import Namespace

from .roundtrip import expand_file

SH = Namespace("http://www.w3.org/ns/shacl#")


def merge_corpus(files: list[Path], context: dict | None, base: str = "https://example.gov/") -> Graph:
    merged = Graph()
    for path in files:
        graph, error = expand_file(path, context, base)
        if error:
            continue
        for quad in graph.quads((None, None, None, None)):
            merged.add(quad[:3])
    return merged


def coverage(shapes: Graph, data: Graph) -> dict:
    targets = {o for o in shapes.objects(None, SH.targetClass) if isinstance(o, URIRef)}
    present = {o for o in data.objects(None, RDF.type) if isinstance(o, URIRef)}
    matched = targets & present
    focus_nodes = {s for cls in matched for s in data.subjects(RDF.type, cls)}
    return {
        "targetClasses": len(targets),
        "typesInData": len(present),
        "matchedClasses": sorted(str(c) for c in matched),
        "matchedClassCount": len(matched),
        "focusNodes": len(focus_nodes),
        "unmatchedTargetClasses": sorted(str(c) for c in targets - present),
    }


def run(shapes_path: Path, data: Graph) -> dict:
    shapes = Graph().parse(str(shapes_path), format="turtle")
    conforms, results_graph, _ = pyshacl_validate(
        data, shacl_graph=shapes, inference="none", advanced=True, debug=False
    )
    severities: dict[str, int] = {}
    for result in results_graph.subjects(RDF.type, SH.ValidationResult):
        for severity in results_graph.objects(result, SH.resultSeverity):
            key = str(severity).rsplit("#", 1)[-1]
            severities[key] = severities.get(key, 0) + 1
    paths: dict[str, int] = {}
    for result in results_graph.subjects(RDF.type, SH.ValidationResult):
        for path in results_graph.objects(result, SH.resultPath):
            paths[str(path)] = paths.get(str(path), 0) + 1
    return {
        "shapes": str(shapes_path),
        "shapeTriples": len(shapes),
        "conforms": bool(conforms),
        "results": sum(severities.values()),
        "bySeverity": dict(sorted(severities.items())),
        "topPaths": sorted(paths.items(), key=lambda kv: (-kv[1], kv[0]))[:15],
        "coverage": coverage(shapes, data),
    }

