      "description": "Authority, code list entry, or policy reference that defines the specific use restriction; consider using a controlled vocabulary such as the NARA https://www.archives.gov/research/catalog/lcdrg/authority-lists/specific-use-restriction",
      "anyOf": [
        {
          "type": "null",
          "title": "Null allowed when not required"
        },
        {
          "$ref": "/dcat-us/3.0.0/definitions/concept",
          "description": "inline description of the specific restriction"
        }
      ],
      "_oldDocs": {
        "uri": "dcat-us:specificRestriction",
        "range": "skos:Concept"
      },
      "examples": ["Copyright", "Trademark"],
      "requirementLevel": "Recommended"
    }
  },
  "required": ["restrictionStatus"],
  "_oldDocs": {
    "rdfClass": "dcat-us:UseRestriction",
    "rationale": "The introduction of dcat-us:UseRestriction in DCAT-US 3.0, aligned with NARA (National Archives and Records Administration) guidelines, enhances compliance and interoperability with NARA-specific use restriction standards. This enables organizations to accurately convey NARA-specific restrictions on data resources, ensuring adherence to archival and data preservation requirements, and promoting consistent data management practices within the DCAT-US framework."
  },
  "examples": [
    {
      "@type": "UseRestriction",
      "restrictionStatus": "Restricted - Fully",
      "specificRestriction": "Trademark",
      "restrictionNote": "This data may be used for any purpose without restriction."
    }
  ]
}

