#-------------------------------------------------------------------------
# The shapes in this file cover all classes in DCAT-AP 3.0.0
# It covers all constraints that must be satisfied except those verifying 
# the class ranges. This can be found in a separate file.
# 
#-------------------------------------------------------------------------

:Agent_Shape
    a sh:NodeShape ;
    rdfs:label "Agent"@en ;
    sh:property [
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
        sh:path foaf:name ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:path dct:type ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass foaf:Agent .

:CatalogRecord_Shape
    a sh:NodeShape ;
    rdfs:label "Catalog Record"@en ;
    sh:property [
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:node :DcatResource_Shape ;
        sh:path foaf:primaryTopic ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:path dct:modified ;
        sh:severity sh:Violation ;
        sh:shape :DateOrDateTimeDataType_Shape
    ], [
        sh:maxCount 1 ;
        sh:path dct:conformsTo ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:node :DateOrDateTimeDataType_Shape ;
        sh:path dct:issued ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:path adms:status ;
        sh:severity sh:Violation
    ], [
        sh:path dct:language ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:path dct:source ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:Literal ;
        sh:path dct:title ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:Literal ;
        sh:path dct:description ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass dcat:CatalogRecord .

:Catalog_Shape
    a sh:NodeShape ;
    rdfs:label "Catalog"@en ;
    sh:property [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dct:language ;
        sh:severity sh:Violation
    ], [
  	sh:path dcatap:applicableLegislation;
  	sh:nodeKind sh:IRI;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dct:license ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:node :DateOrDateTimeDataType_Shape ;
        sh:path dct:issued ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dct:spatial ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dct:hasPart ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:node :DateOrDateTimeDataType_Shape ;
        sh:path dct:modified ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dct:rights ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:record ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:themeTaxonomy ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:service ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:catalog ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:maxCount 1 ;
        sh:path dct:creator ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:dataset ;
        sh:severity sh:Violation
    ], [
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
        sh:path dct:description ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:path dct:publisher ;
        sh:severity sh:Violation
    ], [
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
        sh:path dct:title ;
        sh:severity sh:Violation
    ], [
        sh:maxCount 1 ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path foaf:homepage ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass dcat:Catalog .

:CategoryScheme_Shape
    a sh:NodeShape ;
    rdfs:label "Category Scheme"@en ;
    sh:property [
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
        sh:path dct:title ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass skos:ConceptScheme .

:Category_Shape
    a sh:NodeShape ;
    rdfs:label "Category"@en ;
    sh:property [
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
        sh:path skos:prefLabel ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass skos:Concept .

:Checksum_Shape
    a sh:NodeShape ;
    rdfs:label "Checksum"@en ;
    sh:property [
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:path spdx:algorithm ;
        sh:severity sh:Violation
    ], [
        sh:datatype xsd:hexBinary ;
        sh:maxCount 1 ;
        sh:minCount 1 ;
        sh:path spdx:checksumValue ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass spdx:Checksum .

:DataService_Shape
    a sh:NodeShape ;
    rdfs:label "Data Service"@en ;
    sh:property [
        sh:maxCount 1 ;
        sh:path dct:accessRights ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:severity sh:Violation
    ], [
  	sh:path dcatap:applicableLegislation;
  	sh:nodeKind sh:IRI;
        sh:severity sh:Violation
    ], [
        sh:path dct:conformsTo ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:contactPoint ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:Literal ;
        sh:path dct:description ;
        sh:severity sh:Violation
    ], [
        sh:minCount 1 ;
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:endpointURL ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:endpointDescription ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dct:format ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:Literal ;
        sh:path dcat:keyword ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:landingPage ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:maxCount 1 ;
        sh:path dct:license ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:maxCount 1 ;
        sh:path dct:publisher ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:BlankNodeOrIRI ;
        sh:path dcat:servesDataset ;
        sh:severity sh:Violation
    ], [
        sh:nodeKind sh:IRI ;
        sh:path dcat:theme ;
        sh:severity sh:Violation
    ], [
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
        sh:path dct:title ;
        sh:severity sh:Violation
    ] ;
    sh:targetClass dcat:DataService .

:Dataset_Shape
    a sh:NodeShape ;
    rdfs:label "Dataset"@en ;
