@prefix iso: <https://dcat.example.org/ISO-IEC-25012/> .
@prefix ldqd: <http://dcat.example.org/ldqd/> .
@prefix locn: <http://www.w3.org/ns/locn#> .
@prefix oa: <http://www.w3.org/ns/oa#> .
