# -- Organizational structure -----------------------------------------------------------

org:Organization a owl:Class, rdfs:Class;
    rdfs:subClassOf  foaf:Agent;
    owl:equivalentClass foaf:Organization;
    rdfs:label "Organization"@en;
    rdfs:label "Organisation"@fr;
    rdfs:label "Organizzazione"@it;

    owl:hasKey (org:identifier) ;
    rdfs:comment """Represents a collection of people organized together into a community or other social, commercial or political structure. The group has some common purpose or reason for existence which goes beyond the set of people belonging to it and can act as an Agent. Organizations are often decomposable into hierarchical structures.  It is recommended that SKOS lexical labels should be used to label the Organization. In particular `skos:prefLabel` for the primary (possibly legally recognized name), `skos:altLabel` for alternative names (trading names, colloquial names) and `skos:notation` to denote a code from a code list. Alternative names: _Collective_ _Body_ _Org_ _Group_"""@en;
    rdfs:comment """Représente un groupe de personnes organisées en communauté où tout autre forme de structure sociale, commerciale ou politique. Le groupe a un but commun ou une raison d'être qui va au-delà de la somme des personnes qui en font partie et peut agir en tant que "Agent". Les organisations sont souvent décomposables en structures hiérarchisées. Il est recommandé que des labels lexicaux SKOS soient utilisés pour nommer l'Organisation. En particulier `skos:prefLabel` pour le nom principal (en général le nom légal), `skos:altLabel` pour les noms alternatifs (marques, sigles, appellations familières) et `skos:notation` pour indiquer un code provenant d'une liste de code."""@fr;  
    rdfs:comment """Rappresenta una collezione di persone organizzate all'interno di una communità o di una qualche struttura sociale, commerciale o politica. Il gruppo condivide un obiettivo o una ragione d'essere che va oltre gli stessi membri appartenenti al gruppo e  può agire come un Agent. Le organizzazioni si possono spesso suddividere in strutture gerarchiche. Si raccomanda di usare le label per l'Organization mediante le proprietà di SKOS. In particolare, `skos:prefLabel` per il nome principale (possibilmente un nome legalmente riconosciuto)”, `skos:altLabel` come nome alternativo (denominazione commerciale, denominazione colloquiale) e `skos:notation` per indicare un codice di una lista di codici."""@it;
    rdfs:comment "コミュニティー、その他の社会、商業、政治的な構造に共に編入された人々の集合を表わします。グループには、そこに属する人々を超えた、存在に対するある共通の目的や理由があり、エージェント（代理）を務めることができます。組織は、多くの場合、階層構造に分割できます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:Organization rdfs:label "organización"@es ;
    rdfs:comment "Grupo de personas que se organiza en una comunidad u otro tipo de estructura social, comercial o política. Dicho grupo tiene un objetivo o motivo común para su existencia que va más allá del conjunto de personas que lo forman y que puede actuar como “agente”. A menudo las organizaciones se pueden agrupar en estructuras jerárquicas. Se recomienda el uso de etiquetas de SKOS para denominar a cada “organización”. En concreto, `skos:prefLabel` para la denominación principal o recomendada (aquella reconocida legalmente, siempre que sea posible), `skos:altLabel` para denominaciones alternativas (nombre comercial, sigla, denominación por la que se conoce a la organización coloquialmente) y `skos:notation` para referirse al código que identifique a la organización en una lista de códigos. Denominaciones alternativas: _colectivo_ _corporación_ _grupo_"@es .

org:FormalOrganization a owl:Class, rdfs:Class;

    rdfs:subClassOf  org:Organization, foaf:Organization;
    rdfs:label "Formal Organization"@en;
    rdfs:label "Organisation Formelle"@fr;
    rdfs:label "Organizzazione formale"@it;

    rdfs:comment """An Organization which is recognized in the world at large, in particular in legal jurisdictions, with associated rights and responsibilities. Examples include a Corporation, Charity, Government or Church. Note that this is a super class of `gr:BusinessEntity` and it is recommended to use the GoodRelations vocabulary to denote Business classifications such as DUNS or NAICS."""@en; 
    rdfs:comment """Une Organisation reconnue, en particulier par les juridictions locales, ayant des droits et des responsabilités. Exemples : entreprises, association à but non-lucratif, collectivité, église. Notez que c'est une super-classe de `gr:BusinessEntity` et qu'il est recommandé d'utiliser le vocabulaire GoodRelations pour indiquer les classifications économiques comme le code NACE."""@fr;     
    rdfs:comment """Un'organizzazione che è riconosciuta a livello mondiale o, in generale, all'interno di una qualche giurisdizione, e che quindi possiede diritti e responsabilità. Ad esempio aziende, enti governativi, associazioni di volontariato. Si noti che questa è una superclasse di `gr:BusinessEntity` e che quindi è raccomandabile usare il vocabolario GoodRelations per esprimere classificazioni di tipo industriale e commerciale come DUNS e NAICS."""@it;
    rdfs:comment "関連する権利と責任を有する（特に法的管轄区域において）世界中に広く認識されている組織。例には、企業、慈善団体、政府や教会が含まれます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:FormalOrganization rdfs:label "organización formal"@es ;
    rdfs:comment "Organización reconocida a nivel mundial, en particular en jurisdicciones legales, con derechos y responsabilidades asociadas. Algunos ejemplos son: organización corporativa, organización benéfica, organización gubernamental, organización religiosa. Se debe tener en cuenta que ésta es una superclase de `gr:BusinessEntity` y que se recomienda el uso del vocabulario GoodRelations para referirse a clasificaciones de negocios tales como DUNS o NAICS."@es .

gr:BusinessEntity rdfs:subClassOf org:FormalOrganization .

org:OrganizationalUnit a owl:Class, rdfs:Class;
    rdfs:subClassOf  org:Organization;

    rdfs:label "OrganizationalUnit"@en;
    rdfs:label "Unité opérationnelle"@fr;
    rdfs:label "Unità Organizzativa"@it;

    rdfs:comment """An Organization such as a University Support Unit which is part of some larger FormalOrganization and only has full recognition within the context of that FormalOrganization, it is not a Legal Entity in its own right. Units can be large and complex containing other Units and even FormalOrganizations. Alternative names: _OU_ _Unit_ _Department_"""@en;
    rdfs:comment """Une organisation telle que le support informatique d'une université, qui fait partie d'une Organisation Formelle plus importante et qui ne peut être reconnue qu'en tant que membre de cette organisation supérieure, ce n'est pas une entité légale en elle-même. Les unités opérationnelles peuvent être étendues, complexes et inclure elles-mêmes d'autres branches ou Unités Opérationnelles, voire des Organisations Formelles."""@fr;
    rdfs:comment """Un'organizzazione come ad esempio l'unità dei sistemi informativi che è parte di una più grande FormalOrganization e che, pur essendo riconosciuta nel contesto della propria organizzazione di riferimento, non è legalmente riconosciuta come entità a sé stante. Le unità possono essere ampie e complesse e contenere al loro interno sia altre unità che addirittura FormalOrganization."""@it;
    rdfs:comment "あるより大きな組織の一部であり、その組織の中においてのみ完全に認識される部局や支援部署などの組織です。特に、その単位はそれ自体では法的実体と見なされません。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:OrganizationalUnit rdfs:label "unidad organizativa"@es ;
    rdfs:comment "Organización que forma parte de una organización formal más amplia, como el servicio de informática o centro de cálculo de una universidad, y que sólo tiene reconocimiento pleno en el contexto de dicha organización formal, pero que no es una entidad legal propiamente dicha. Estas unidades pueden ser amplias y complejas, e incluir a otras unidades o incluso a otras organizaciones formales. Denominaciones alternativas: departamento."@es .


org:subOrganizationOf a owl:ObjectProperty, rdf:Property;
    rdfs:label "subOrganization of"@en;
    rdfs:label "sous-Organization de"@fr;
    rdfs:label "sotto-Organization di"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:Organization;
    rdfs:subPropertyOf  org:transitiveSubOrganizationOf;

    rdfs:comment """Represents hierarchical containment of Organizations or OrganizationalUnits; indicates an Organization which contains this Organization. Inverse of `org:hasSubOrganization`."""@en;
    rdfs:comment """Représente une relation hierarchique des Organisations ou des Unités Opérationnelles; indique une Organisation sujet qui contient cette Organisation. Inverse de `org:hasSubOrganization`."""@fr;    
    rdfs:comment """Rappresenta un contenimento gerarchico di una Organization o di una OrganizationalUnit. È l'inverso di `org:hasSubOrganization`. Ha nome come nome alternativo hasSubOrg."""@it;
    rdfs:comment "組織または組織単位の階層的包含を表わします。この組織を含む組織を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:subOrganizationOf rdfs:label "es suborganización de"@es ;
    rdfs:comment "Distribución jerárquica de organizaciones o unidades. Indica que una organización contiene a otra organización. Es la relación inversa de `org:hasSubOrganization`"@es .

org:transitiveSubOrganizationOf  a owl:ObjectProperty, owl:TransitiveProperty, rdf:Property;

    rdfs:label "transitive sub-organization"@en;
    rdfs:label "sous-Organization transitive de"@fr;
    rdfs:label "sotto-Organization transitiva"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:Organization;

    rdfs:comment """The transitive closure of subOrganizationOf, giving a representation of all organizations that contain this one. Note that technically this is a super property of the transitive closure so it could contain additional assertions but such usage is discouraged."""@en;    
    rdfs:comment """La version transitive de la propriété subOrganizationOf, renvoie une représentation de toutes les organisations qui contiennent celle-ci. Notez que ceci est une super-propriété de la relation transitive donc elle pourrait contenir des assertions additionnelles mais cet usage n'est pas recommandé."""@fr;
    rdfs:comment """È la chiusura transitiva di subOrganizationOf, quindi rappresenta tutte le organizzazioni che la contengono. Tecnicamente, essendo una chiusura transitiva, può contenere asserzioni che non la riguardano e quindi il suo uso è sconsigliato."""@it;
    rdfs:comment "subOrganizationOfの推移閉包で、これを含むすべての組織の表現を与える。技術的に、これが推移閉包のスーパープロパティーであるため、追加の言明を含むことができますが、そのような使用法はお勧めできないことに注意してください。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:transitiveSubOrganizationOf rdfs:label "es suborganización de manera transitiva de"@es ;
    rdfs:comment "La versión transitiva de la propiedad “subOrganizationOf”, es decir, la representación de todas las organizaciones en las que esta está contenida. Téngase en cuenta que desde el punto de vista técnico esta es una propiedad que contiene a todas las propiedades transitivas, de forma que podría contener afirmaciones adicionales, aunque su uso no está aconsejado."@es ;
    rdfs:label "es suborganización de (transitiva)"@es .

org:hasSubOrganization a owl:ObjectProperty, rdf:Property;
    rdfs:label "has SubOrganization"@en;
    rdfs:label "a une Sous-Organization"@fr;
    rdfs:label "ha sotto-Organization"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:Organization;

    rdfs:comment """Represents hierarchical containment of Organizations or Organizational Units; indicates an organization which is a sub-part or child of this organization.  Inverse of `org:subOrganizationOf`."""@en;
    rdfs:comment """Indique le statut de dépendance hiérarchique pour des Organisations ou des Unités Opérationnelles; indique une Organisation qui est une sous-partie ou une branche d'une Organisation plus large. C'est la propriété inverse de `org:subOrganizationOf`."""@fr;    
    rdfs:comment """Rappresenta un contenimento gerarchico di una Organization o di una OrganizationalUnit. Indica una organizzazione che è parte di una organizzazione più grande. È l'inverso di `org:subOrganizationOf`."""@it;
    rdfs:comment "組織または組織単位の階層的包含を表わします。この組織のサブパートまたは子である組織を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:hasSubOrganization rdfs:label "tiene suborganización"@es ;
    rdfs:comment "Organización jerárquica de organizaciones o unidades. Indica que una organización es parte de otra organización más amplia o pertenece a ella. Es la relación inversa de `org:subOrganizationOf`."@es .

org:subOrganizationOf  owl:inverseOf org:hasSubOrganization . 

org:hasSubOrganization owl:inverseOf  org:subOrganizationOf .


org:purpose a rdf:Property;
    rdfs:label "purpose"@en;
    rdfs:label "but"@fr;
    rdfs:label "obiettivo"@it;

    rdfs:domain org:Organization;

    rdfs:comment """Indicates the purpose of this Organization. There can be many purposes at different levels of abstraction but the nature of an organization is to have a reason for existence and this property is a means to document that reason. An Organization may have multiple purposes. It is recommended that the purpose be denoted by a controlled term or code list, ideally a `skos:Concept`. However, the range is left open to allow for other types of descriptive schemes. It is expected that specializations or application profiles of this vocabulary will constrain the range of the purpose. Alternative names: _remit_ _responsibility_ (esp. if applied to OrganizationalUnits such as Government Departments)."""@en;
    rdfs:comment """Indique le but de cette Organisation. Il peut exister plusieurs buts à différents niveaux d'abstraction mais la nature d'une organisation est d'avoir une raison d'exister et cette propriété doit servir à documenter cette raison d'être. Une Organisation peut avoir plusieurs Buts. Il est recommandé que le but soit libellé à l'aide d'un vocabulaire contrôlé ou autre code établi, idéalement avec un concept `skos:Concept`. Toutefois, le champ de cette propriété est laissé ouvert et pourrait accepter d'autres schémas de description. Il est préférable que les spécialisations ou les profils d'applications de ce vocabulaire contraignent le champ de cette propriété."""@fr;    
    rdfs:comment """Indica l'obiettivo di questa Organization. In generale, si possono esprimere gli obiettivi di un'organizzazione secondo diversi livelli di astrazione, ma la natura stessa dell'organizzazione ha una ragione d'essere ed è proprio questa che deve essere catturata con tale proprietà. Inoltre, un'Organization può avere obiettivi multipli. È raccomandabile che l'obiettivo faccia parte di una code list, e che sia preferibilmente un `skos:Concept`. Ad ogni modo, il codominio della proprietà è lasciato aperto per consentire altri tipi di di descrizione. Conseguentemente, eventuali specializzazioni o profili applicativi possono utilizzare quel vocabolario come codominio della proprietà."""@it;
    rdfs:comment "この組織の目的を示します。異なる抽象レベルの多くの目的がありえますが、組織の本質は存在理由を持つことであり、このプロパティーはその理由をドキュメント化する手段です。組織は、複数の目的を持っている可能性があります。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:purpose rdfs:label "tiene objetivo"@es ;
    rdfs:comment "Finalidad u objetivo de la organización. La organización puede tener muchos objetivos a diferentes niveles de abstracción, pero en la naturaleza de las organizaciones está el tener una razón para existir, y la finalidad de esta propiedad es documentar dicha razón. La organización podrá tener más de un objetivo. Se recomienda el uso de vocabularios controlados o listas de códigos para indicar el objetivo, preferentemente mediante el uso de un `skos:Concept`. Sin embargo, el rango no está predeterminado, de forma que otros tipos de esquemas descriptivos tiene cabida. Se espera que ciertas especializaciones de este vocabulario o ciertos perfiles de aplicaciones restrinjan el rango del objetivo. Denominaciones alternativas: área_ _jurisdicción_ _ responsabilidad _ (especialmente cuando se aplica a unidades tales como ministerios o divisiones administrativas de los gobiernos)"@es .

org:hasUnit a owl:ObjectProperty, rdf:Property;

    rdfs:label "has Unit"@en;
    rdfs:label "possède une Unité"@fr;
    rdfs:label "ha Unit"@it;

    rdfs:domain org:FormalOrganization;
    rdfs:range  org:OrganizationalUnit;
    rdfs:subPropertyOf org:hasSubOrganization;

    rdfs:comment """Indicates a unit which is part of this Organization, e.g. a Department within a larger FormalOrganization. Inverse of `org:unitOf`."""@en;
    rdfs:comment """Indique une Unité qui fait partie d'une Organisation, par exemple un Départment au sein d'une Organisation Formelle plus large. Inverse de `org:unitOf`."""@fr;    
    rdfs:comment """Indica un'unità che è parte di questa Organization, come ad esempio un dipartimento facente parte di una più ampia FormalOrganization. È l'inverso di `org:unitOf`."""@it;
    rdfs:comment "例えば、より大きな組織内の部局など、この組織の一部である単位を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:hasUnit rdfs:label "contiene unidad"@es ;
    rdfs:comment "Unidad que es parte de la organización, como, por ejemplo, un departamento incluido en una organización formal más amplia."@es .

org:unitOf a owl:ObjectProperty, rdf:Property;

    rdfs:label "unit Of"@en;
    rdfs:label "unité de"@fr;
    rdfs:label "unità di"@it;

    rdfs:domain org:OrganizationalUnit; 
    rdfs:range  org:FormalOrganization;  
    rdfs:subPropertyOf org:subOrganizationOf;

    rdfs:comment """Indicates an Organization of which this Unit is a part, e.g. a Department within a larger FormalOrganization. This is the inverse of `org:hasUnit`."""@en;
    rdfs:comment """Indique l'Organisation dont cette Organisation ou Unité fait partie, par exemple un Départment au sein d'une Organisation Formelle plus large. Inverse de `org:hasUnit`."""@fr;    
    rdfs:comment """Indica un Organization di cui questa Unit fa parte, come ad esempio un dipartimento all'interno di una più vasta FormalOrganization. È l'inverso di `org:hasUnit`."""@it;
    rdfs:comment "例えば、より大きな組織内の部局など、この単位がその一部分である組織を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:unitOf rdfs:label "es unidad de"@es ;
    rdfs:comment "Organización de la que es parte esta unidad, por ejemplo, un departamento incluido en una organización formal más amplia."@es .

org:unitOf owl:inverseOf org:hasUnit .

org:hasUnit owl:inverseOf org:unitOf .


org:classification a owl:ObjectProperty, rdf:Property;

    rdfs:label "classification"@en;
    rdfs:label "classification"@fr;
    rdfs:label "classificazione"@it;

    rdfs:domain org:Organization;
    rdfs:range  skos:Concept;  

    rdfs:comment """Indicates a classification for this Organization within some classification scheme. Extension vocabularies may wish to specialize this property to have a range corresponding to a specific `skos:ConceptScheme`. This property is under discussion and may be revised or removed - in many cases organizations are best categorized by defining a sub-class hierarchy in an extension vocabulary."""@en;
    rdfs:comment """Indique une classification pour cette Organisation dans le cadre d'un schéma de classification. Il est possible de spécialiser cette propriété en utilisant un vocabulaire spécialisé pour que le champ corresponde à un concept spécifique `skos:ConceptScheme`. Cette propriété est en discussion est pourrait être révisée ou supprimée - dans de nombreux cas, les organisations sont mieux catégorisées par une hiérarchie de sous-classe dans un vocabulaire externe."""@fr;  
    rdfs:comment """Indica una classificazione per questa Organization all'interno di un qualche schema di classificazione. Alcuni vocabolari potrebbero voler specializzare questa proprietà per avere un codominio corrispondente a uno specifico `skos:ConceptScheme`. Si noti che la presenza di questa proprietà è ancora in fase di discussione e potrebbe  essere revisionata o rimossa."""@it;
    rdfs:comment """ある分類表内のこの組織に対する分類を示します。
アプリケーションがorg:Organizationのサブクラスを組織的なカテゴリーを表わす手段として定義することも許容されることに注意してください。"""@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:classification rdfs:label "pertenece a la clasificación"@es ;
    rdfs:comment "Ordenación jerárquica que se hace de una organización dentro de un esquema de clasificación. Es posible que algunos vocabularios especifiquen esta propiedad de forma que el rango se corresponda con un `skos:ConceptScheme` específico. La conveniencia de incluir esta propiedad se está debatiendo y puede que se revise o elimine (en muchos casos las organizaciones se clasifican mejor si se define una jerarquía de subclases en un vocabulario aparte)"@es .

org:identifier a owl:DatatypeProperty, rdf:Property;

    rdfs:label "identifier"@en;
    rdfs:label "identifiant"@fr;
    rdfs:label "identificatore"@it;

    rdfs:domain org:Organization;
    rdfs:subPropertyOf skos:notation;

    rdfs:comment """Gives an identifier, such as a company registration number, that can be used to used to uniquely identify the organization. Many different national and international identier schemes are available. The org ontology is neutral to which schemes are used. The particular identifier scheme should be indicated by the datatype of the identifier value.  Using datatypes to distinguish the notation scheme used is consistent with recommended best practice for `skos:notation` of which this property is a specialization."""@en;
    rdfs:comment """Donne un identifiant, comme par exemple le numéro d'enregistrement d'une entreprise, qui peut être utilisé comme identifiant unique pour l'Organisation. De nombreux schémas nationaux et internationaux sont disponibles. Cette ontologie reste neutre par rapport au schéma utilisé. Le schéma particulier utilisé devrait être indiqué par le `datatype` de la valeur de l'identifiant. Utiliser les datatypes pour distinguer les schémas de notation est cohérent avec les bonnes pratiques pour `skos:notation` dont cette propriété est une spécialisation."""@fr;
    rdfs:comment """Indica un identificatore univoco per l'organizzazione, come ad esempio la partita IVA di un'azienda. Molti schemi di identificazione a livello nazionale e internazionale sono disponibili allo scopo. L'ontologia ORG è neutrale rispetto allo schema da utilizzare. Lo schema di identificazione dovrebbe essere indicato dal datatype del valore dell'identificatore. L'uso del datatype per distinguere lo schema di identificazione è coerente con le best practice per `skos:notation`, di cui questa proprietà è una specializzazione."""@it;
    rdfs:comment "組織を一意に識別するために使用できる会社登録番号などの識別子を与えます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:identifier rdfs:label "tiene identificador"@es ;
    rdfs:comment "Código o identificador, como por ejemplo el CIF de una empresa, que permite identificar de forma inequívoca a una organización. Existen muchos códigos de identificación tanto nacionales como internacionales. Esta ontología no obliga al uso de ningún esquema en concreto. Los códigos de identificación utilizados en cada caso se deberían indicar mediante el uso de la propiedad “datatype” del valor del identificador. El uso de la propiedad “datatype” para especificar el esquema de notación utilizado está en consonancia con las buenas prácticas recomendadas para el uso de la propiedad `skos:notation`, de la que esta propiedad es una especialización."@es .


org:linkedTo a owl:ObjectProperty, rdf:Property;

    rdfs:label "linked to"@en;
    rdfs:label "relié à"@fr;
    rdfs:label "collegato a"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:Organization;

    rdfs:comment """Indicates an arbitrary relationship between two organizations. Specializations of this can be used to, for example, denote funding or supply chain relationships."""@en;
    rdfs:comment """Indique une relation arbitraire entre deux Organisations. Des spécialisations peuvent être utilisées pour, par exemple, qualifier une relation de fournisseur ou de financeur."""@fr;    
    rdfs:comment """Indica una relazione arbitraria tra due organizzazioni. Ad esempio, specializzazioni di questa proprietà possono essere usate per denotare relazioni particolari tipo il finanziamento o la fornitura."""@it;
    rdfs:comment "2つの組織の任意の関係を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:linkedTo rdfs:label "está relacionado con"@es ;
    rdfs:label "está relacionada con"@es ;
    rdfs:comment "Relación arbitraria entre dos organizaciones. Las especializaciones de esta relación se pueden utilizar para denotar relaciones de financiación o suministro, entre otras."@es .

# -- Reporting relationships and roles -----------------------------------------------------------


org:memberOf a owl:ObjectProperty, rdf:Property;

    rdfs:label "member of"@en;
    rdfs:label "membre de"@fr;    
    rdfs:label "membro di"@it;

    rdfs:domain foaf:Agent;
    rdfs:range  org:Organization;

    rdfs:comment """Indicates that a person is a member of the Organization with no indication of the nature of that membership or the role played. Note that the choice of property name is not meant to limit the property to only formal membership arrangements, it is also indended to cover related concepts such as affilliation or other involvement in the organization. Extensions can specialize this relationship to indicate particular roles within the organization or more nuanced relationships to the organization. Has an optional inverse, `org:hasmember`."""@en;
    rdfs:comment """Indique qu'une personne est membre de l'Organisation sans précision sur la nature de cet engagement ou du rôle joué. Notez que le choix du nom de cette propriété ne vise pas à la limiter aux seuls engagements formels, elle peut également couvrir des concepts reliés comme l'affiliation ou le bénévolat. Des extensions peuvent spécialiser cette relation pour indiquer des rôles particuliers au sein de l'Organisation or des relations plus nuancées avec elle. Possède une propriété inverse optionnelle, `org:hasmember`."""@fr;
    rdfs:comment """Indica che una persona è membro di una Organization senza una precisa indicazione sulla natura di questa appartenenza e sul suo ruolo. Si noti che la scelta del nome di questa proprietà non intende limitarla alla sola  rappresentazione formalmente di un'appartenenza. La proprietà può coprire anche altri coinvolgimenti nell'organizzazione. Questa proprietà può essere specializzata per indicare ruoli all'interno organizzazione o relazioni di diverse tipologie. Ha `org:hasmember` come proprietà inversa opzionale."""@it;
    rdfs:comment "エージェント（人または他の組織）が組織のメンバーであることを示します。ただし、その構成員の本質や担う役割は示しません。プロパティー名の選択は、プロパティーを正式な構成員配置のみに制限することが目的ではないことに注意してください。所属や組織へのその他の関与などの関連する概念をカバーすることも意図されています。拡張により、この関係を特殊化し、組織内の特定の役割やよりニュアンスを含んだ組織との関係を示すことができます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:memberOf rdfs:label "es miembro de"@es ;
    rdfs:comment "Persona que pertenece a la organización o es miembro de la misma, sin que conste la naturaleza de dicha pertenencia o el papel que desempeña. Se debe tener en cuenta que la elección de una denominación para esta propiedad no significa que la propiedad esté limitada a ciertos tipos de pertenencia formales, sino que pretende cubrir conceptos relacionados como el de afiliación u otras formas de participación en la organización. Se puede hacer uso de extensiones para especializar esta relación de forma que incluya tipos específicos de pertenencia a las organizaciones o relaciones especiales con la organización."@es .


org:hasMember a owl:ObjectProperty, rdf:Property;

    rdfs:label "has member"@en;
    rdfs:label "possède un membre"@fr;
    rdfs:label "ha membro"@it;

    rdfs:domain org:Organization;
    rdfs:range  foaf:Agent;
    owl:equivalentProperty foaf:member;

    rdfs:comment """Indicates a person who is a member of the subject Organization. Inverse of `org:memberOf`, see that property for further clarification. Provided for compatibility with `foaf:member`."""@en;
    rdfs:comment """Indique une personne membre de l'Organisation sujet. Inverse de `org:memberOf`, voyez la description de cette propriété pour plus de précisions. Fourni pour la compatibilité avec `foaf:member`."""@fr;    
    rdfs:comment """Indica una persona che è membro della data Organization. È l'inverso di `org:memberOf` ed è fornita per  compatibilità con `foaf:member`."""@it;
    rdfs:comment "対象組織のメンバーであるエージェント（人または他の組織）を示します。org:memberOfの逆。さらに明確な説明については、そのプロパティーを参照してください。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:hasMember rdfs:label "tiene miembro"@es ;
    rdfs:comment "Persona que es miembro de la organización en cuestión. Es la relación inversa de `org:memberOf`, véase la descripción de esa propiedad para más detalles. Se prevé compatibilidad con foaf:member`."@es .

org:memberOf  owl:inverseOf org:hasMember .

org:hasMember owl:inverseOf org:memberOf  .



org:reportsTo a owl:ObjectProperty, rdf:Property;

    rdfs:label "reports to"@en;
    rdfs:label "est subordonné à"@fr;
    rdfs:label "riporta a"@it;

    rdfs:domain [a owl:Class; owl:unionOf (foaf:Agent org:Post)];
    rdfs:range  [a owl:Class; owl:unionOf (foaf:Agent org:Post)];

    rdfs:comment """Indicates a reporting relationship as might be depicted on an organizational chart. The precise semantics of the reporting relationship will vary by organization but is intended to encompass both direct supervisory relationships (e.g. carrying objective and salary setting authority) and more general reporting or accountability relationships (e.g. so called _dotted line_ reporting)."""@en;
    rdfs:comment """Indique une relation de subordination comme elle pourrait figurer dans un organigramme. La sémantique précise de cette subordination pourra varier selon l'Organisation mais vise à englober aussi bien les relations hiérarchiques directes (définition d'objectifs, montant du salaire) que des relations plus générales ou organisationnelles (les liens en pointillés dans les organigrammes)."""@fr;
    rdfs:comment """Indica una relazione di subordinazione all'interno dell'organigramma. La semantica precisa può variare a seconda dell'organizzazione, per esempio può essere usata per rappresentare la proprietà di supervisione oppure per le relazioni di rendicontazione."""@it;
    rdfs:comment "組織図で描かれるかもしれないような上下関係を示します。エージェント間またはエージェントが就くことができるポスト間の上下関係を直接的に示すために使用できます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:reportsTo rdfs:label "responde ante"@es ;
    rdfs:comment "Relación de subordinación que se representa en los organigramas de las organizaciones. La semántica de la relación de subordinación varía según las organizaciones, pero su intención es abarcar tanto a las relaciones de supervisión directa (por ejemplo, aquellas en las que la autoridad determina los objetivos o el salario) como a las relaciones de subordinación más generales (por ejemplo, las llamadas líneas de autoridad o de mando (y responsabilidad) (http://www.promonegocios.net/organigramas/tipos-de-organigramas.html))."@es .


org:Role a owl:Class, rdfs:Class;
    rdfs:subClassOf skos:Concept;

    rdfs:label "Role"@en;
    rdfs:label "Rôle"@fr;
    rdfs:label "Ruolo"@it;

    rdfs:comment """Denotes a role that a Person or other Agent can take in an organization. Instances of this class describe the abstract role; to denote a specific instance of a person playing that role in a specific organization use an instance of `org:Membership`. It is common for roles to be arranged in some taxonomic structure and we use SKOS to represent that. The normal SKOS lexical properties should be used when labelling the Role. Additional descriptive properties for the Role, such as a Salary band, may be added by extension vocabularies."""@en; 

    rdfs:comment """Indique le rôle qu'une Personne ou un autre Agent peut avoir dans une Organisation. Les instances de cette classe décrivent le rôle dans l'absolu; pour indiquer une personne ayant ce rôle spécifique dans une Organisation, utilisez une instance de `org:Membership`. Il est courant que les rôles soient organisés dans une sorte de taxonomie, ce qui peut être représenté avec SKOS. Les propriétés de libellés standards de SKOS devraient être utilisées pour libeller le Rôle. D'autres propriétés additionnelles pour ce rôle, comme une fourchette de Salaire peuvent être ajoutées par une extension de ce vocabulaire."""@fr;     
    rdfs:comment """Indica il ruolo che una Person o un altro Agent può assumere in un'organizzazione. Le istanze di questa classe descrivono un ruolo astratto; per esprimere il ruolo che una precisa persona ricopre in un'organizzazione si usi un'istanza di `org:Membership`. È comune organizzare i ruoli in una qualche struttura tassonomica e quindi si raccomanda SKOS per questo. Altre proprietà descrittive per il Role, come salario, possono essere aggiunte mediante l'uso di altri vocabolari."""@it;
    rdfs:comment "人またはその他のエージェントが組織で担うことができる役割を表わします。この種のインスタンスは、抽象的な役割を記述します。特定の組織でその役割を担っている人の特定のインスタンスを示すためには、org:Membershipのインスタンスを使用します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:Role rdfs:label "actividad"@es ;
    rdfs:comment "Función que una persona o agente desempeña en el seno de una organización. Las instancias de esta clase describen la actividad en abstracto; si lo que se pretende es incluir una instancia que refleje la función o actividad que desempeña una persona en concreto en una organización específica, se indica el uso de instancias de la clase `org:Membership`. Es común que dichas actividades se representen en una estructura taxonómica mediante SKOS. Las propiedades léxicas de SKOS deberían utilizarse a la hora de denominar o etiquetar la actividad desempeñada. Para añadir propiedades descriptivas adicionales, como rango salarial, se tendrá que recurrir a vocabularios externos."@es .

org:Membership a owl:Class, rdfs:Class;

    rdfs:label "Membership"@en;
    rdfs:label "Engagement"@fr;
    rdfs:label "Appartenenza"@it;

    rdfs:comment """Indicates the nature of an Agent's membership of an organization. Represents an n-ary relation between an Agent, an Organization and a Role. It is possible to directly indicate membership, independent of the specific Role, through use of the `org:memberOf` property."""@en; 
    rdfs:comment """Indique la nature de l'engagement d'un Agent dans une Organisation. Représente une relation n-aire entre un Agent, une Organisation et un Role. Il est possible d'indiquer directement l'appartenance à une organisation, independemment d'un rôle spécifique, à travers l'usage de la propriété `org:memberOf`."""@fr;     
    rdfs:comment """Indica la natura della relazione di appartenenza di un Agent in un'organizzazione. Rappresenta una relazione n-aria tra un'Agent, un Organization e un Role. È possibile indicare direttamente la membership, indipendentemente dallo specifico Role, attraverso l'uso della proprietà `org:memberOf`"""@it;
    rdfs:comment "組織のエージェントの構成員の本質を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:Membership rdfs:label "membresía"@es ;
    rdfs:comment "Pertenencia o afiliación de un agente a una organización. Es una relación n-aria entre un agente, una organización y una actividad. Es posible indicar pertenencia mediante el uso de la propiedad `org:memberOf`, independientemente de la actividad específica que se desempeñe."@es .


org:member a owl:ObjectProperty, rdf:Property, owl:FunctionalProperty;

    rdfs:label "member"@en;
    rdfs:label "membre"@fr;
    rdfs:label "membro"@it;

    rdfs:domain org:Membership;
    rdfs:range  foaf:Agent;

    rdfs:comment """Indicates the Person (or other Agent including Organization) involved in the Membership relationship. Inverse of `org:hasMembership`"""@en;
    rdfs:comment """Indique une personne (ou tout autre Agent, y compris une Organisation) impliqué dans la relation d'Engagement. Inverse de `org:hasMembership`"""@fr;
    rdfs:comment """Indica la Person (o un altro Agent) coinvolto in una relazione di Membership. È l'inverso di `org:hasMembership`."""@it;
    rdfs:comment "構成員関係に含まれている人（または、組織を含んでいる他のエージェント）を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:member rdfs:label "es condición de miembro sobre agente"@es ;
    rdfs:comment "Persona (u otro agente, incluyendo una organización) que participa en la relación de membresía. Es la relación inversa de `org:hasMembership`."@es .


org:organization a owl:ObjectProperty, rdf:Property, owl:FunctionalProperty;

    rdfs:label "organization"@en;
    rdfs:label "organisation"@fr;
    rdfs:label "organizzazione"@it;

    rdfs:domain org:Membership;
    rdfs:range  org:Organization;

    rdfs:comment """Indicates Organization in which the Agent is a member."""@en;
    rdfs:comment """Indique l'Organization dont l'agent est membre."""@fr;
    rdfs:comment """Indica l'Organization in cui l'Agent è un membro."""@it;
    rdfs:comment "エージェントがメンバーである組織を示します。"@ja;

    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:organization rdfs:label "es condición de miembro sobre organización"@es ;
    rdfs:comment "Organización a la que pertenece el agente en calidad de miembro."@es .



org:role a owl:ObjectProperty, rdf:Property;

    rdfs:label "role"@en;
    rdfs:label "rôle"@fr;
    rdfs:label "ruolo"@it;

    rdfs:domain [a owl:Class; owl:unionOf (org:Membership org:Post)];
#    rdfs:domain org:Membership;
    rdfs:range  org:Role;

    rdfs:comment """Indicates the Role that the Agent plays in a Membership relationship with an Organization."""@en;
    rdfs:comment """Indique le Rôle de l'Agent dans son Engagement avec l'Organisation."""@fr;    
    rdfs:comment """Indica il Role che un Agent ricopre in una relazione di Membership con una Organization"""@it;
    rdfs:comment "エージェントが組織との構成員関係において担う役割を示します。ポストの保持者が担う役割を示すためにorg:Postで用いることもできます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:role rdfs:label "desempeña la actividad de"@es ;
    rdfs:comment "Actividad que el agente desempeña en una relación de pertenencia a una organización."@es .

org:hasMembership a owl:ObjectProperty, rdf:Property;

    rdfs:label "membership"@en;
    rdfs:label "engagement"@fr;
    rdfs:label "appartenenza"@it;

    rdfs:domain foaf:Agent;
    rdfs:range  org:Membership;

    rdfs:comment """Indicates a membership relationship that the Agent plays. Inverse of `org:member`."""@en;
    rdfs:comment """Indique pour cet Agent un engagement dans une Organisation. Inverse de `org:member`."""@fr;
    rdfs:comment """Indica una relazione di appartenenza che coinvolge un Agent. È l'inverso di `org:member`."""@it;    
    rdfs:comment "エージェントが担う構成員関係を示します。"@ja;

    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:hasMembership rdfs:label "tiene membresía"@es ;
    rdfs:comment "Relación de pertenencia o afiliación a una organización en la que el agente desempeña un cargo o función. Es la relación inversa de `org:member`."@es .

org:hasMembership owl:inverseOf org:member .

org:member        owl:inverseOf org:hasMembership .


org:memberDuring a owl:ObjectProperty, rdf:Property;

    rdfs:label "member During"@en;
    rdfs:label "durée d'engagement"@fr;
    rdfs:label "membro durante"@it;  

    rdfs:domain org:Membership;

# This now an informative, not a normative, range constraint    
#    rdfs:range  owlTime:Interval;

    rdfs:comment """Optional property to indicate the interval for which the membership is/was valid."""@en;
    rdfs:comment """Propriété optionnelle pour indiquer l'intervalle durant lequel l'engagemnet est ou était valide."""@fr;
    rdfs:comment """Proprietà opzionale per indicare l'intervallo per il quale l'appartenenza è/è stata valida."""@it;
    rdfs:comment "構成員が有効である／であった期間を示すためのオプションのプロパティー。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:memberDuring rdfs:label "es miembro durante"@es ;
    rdfs:comment "Propiedad opcional que indica el periodo durante el cual la relación de membresía o pertenencia a una organización se mantiene en vigencia."@es .


org:roleProperty a owl:AnnotationProperty, rdf:Property;

    rdfs:label "role (property)"@en;
    rdfs:label "rôle (propriété)"@fr;
    rdfs:label "ruolo (proprietà)"@it;

    rdfs:domain org:Role;
    rdfs:range  rdf:Property;

    rdfs:comment """This is a metalevel property which is used to annotate an `org:Role` instance with a sub-property of `org:memberOf` that can be used to directly indicate the role for easy of query. The intended semantics is a Membership relation involving the Role implies the existence of a direct property relationship through an inference rule of the form:  `{ [] org:member ?p; org:organization ?o; org:role [org:roleProperty ?r] } -> {?p ?r ?o}`."""@en;
    rdfs:comment """Ceci est une méta-propriété utilisée pour annoter une instance de `org:Role` ayant une sous-propriété `org:memberOf` qui peut être utilisée pour indiquer directement le rôle et pouvoir faire des requêtes plus facilement. La sémantique visée est un Engagement impliquant l'existence d'une relation de propriété directe à travers d'une règle d'inférence de la forme:  `{ [] org:member ?p; org:organization ?o; org:role [org:roleProperty ?r] } -> {?p ?r ?o}`."""@fr;
    rdfs:comment """Questa è una meta-proprietà usata per annotare un'istanza di `org:Role` con una sotto-proprietà di `org:memberOf` e può essere usata per indicare direttamente il ruolo per facilitare un'interrogazione sui dati."""@it;
    rdfs:comment "これは、クエリが容易になるように役割を直接的に示すために使用できるorg:memberOfのサブプロパティーでorg:Roleインスタンスを注釈するために用いられるメタレベルのプロパティーです。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:roleProperty rdfs:label "desempeña la actividad de (propiedad)"@es ;
    rdfs:comment "Meta-propiedad que se utiliza para anotar una instancia de `org:Role` con una sub-propiedad de `org:memberOf`, que puede ser utilizada para indicar directamente la actividad a fin de facilitar las consultas a los datos. The intended semantics is that a Membership relation involving the Role implies the existence of a direct property relationship through an inference rule of the form: { [] org:member ?a; org:organization ?o; org:role [org:roleProperty ?r] } -> {?a ?r ?o}"@es .


org:headOf a owl:ObjectProperty, rdf:Property;

    rdfs:label "head of"@en;
    rdfs:label "responsable de"@fr;
    rdfs:label "responsabile di"@it;

    rdfs:domain foaf:Agent;
    rdfs:range  org:Organization;
    rdfs:subPropertyOf org:memberOf;

    rdfs:comment """Indicates that a person is the leader or formal head of the Organization. This will normally mean that they are the root of the `org:reportsTo` (acyclic) graph, though an organization may have more than one head."""@en;
    rdfs:comment """Indique qu'une personne est le directeur ou le responsable formel d'une Organisation. Ceci indique souvent qu'il est au sommet de du graphe acyclique des `org:reportsTo`, même si une organisation peut avoir plus d'un responsable."""@fr;
    rdfs:comment """Indica che una persona è leader o responsabile formale di una Organization. Questo significa che la persona è alla radice del grafo (aciclico) creato dalle `org:reportsTo`, sebbene un'organizzazione possa avere più di un responsabile."""@it;
    rdfs:comment "人（または他のエージェント）が組織のリーダーや正式なトップであることを示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:headOf rdfs:label "es director ejecutivo de"@es ;
    rdfs:comment "Persona que es jefe o jefa, representante ,,director o directora de la organización. Esto significa que dicha persona es el rango de la relación `org:reportsTo` en el organigrama de la organización (acíclico), aunque una organización puede tener más de un jefe."@es .


org:Head a org:Role;
    # This class is not in the Rec document (PhilA, 2014-02-05)

    rdfs:label "head"@en;
    rdfs:label "responsable"@fr;
    rdfs:label "responsabile"@it;

    skos:prefLabel "head"@en;
    skos:prefLabel "responsable"@fr;
    skos:prefLabel "responsabile"@it;

    rdfs:comment "A role corresponding to the `org:headOf` property"@en;
    rdfs:comment "Un rôle correspondant à la propriété `org:headOf`"@fr;
    rdfs:comment "Un ruolo corrispondente alla proprietà `org:headOf`."@it;
    org:roleProperty org:headOf ;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:Head rdfs:label "director ejecutivo"@es ;
    rdfs:label "directora ejecutiva"@es ;
    rdfs:comment "Actividad correspondiente a la propiedad `org:headOf`."@es .


org:remuneration a owl:ObjectProperty, rdf:Property;

    rdfs:label "remuneration"@en;
    rdfs:label "rémuneration"@fr;
    rdfs:label "remunerazione"@it;

    rdfs:domain org:Role;

    rdfs:comment """Indicates a salary or other reward associated with the role. Typically this will be denoted using an existing representation scheme such as `gr:PriceSpecification` but the range is left open to allow applications to specialize it (e.g. to remunerationInGBP)."""@en;

    rdfs:comment """Indique un salaire ou tout autre compensation associée au Rôle. Typiquement, ceci sera annoté en utilisant un schéma existant comme  `gr:PriceSpecification` mais le champ de cette propriété est laissé ouvert afin de permettre aux applications de la spécialiser (par exemple remunerationEuro)."""@fr;    
    rdfs:comment """Indica il salario o altra forma di remunerazione associata al ruolo. In genere, questo si denota usando uno schema di rappresentazione esistente come il `gr:PriceSpecification` ma il codominio è lasciato libero di essere specializzato a seconda delle applicazioni."""@it;
    rdfs:comment "役割に関係する給料やその他の報酬を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:remuneration rdfs:label "recibe remuneración"@es ;
    rdfs:comment "Salario o cualquier otra remuneración asociada con la actividad. La forma usual de referirse a dicha remuneración será utilizando un esquema de representación como el propuesto en la ontología GoodRelations `gr:PriceSpecification`, pero el rango se deja abierto a que las distintas aplicaciones lo especialicen (por ejemplo, remunerationInGBP)"@es .


# -- Location -----------------------------------------------------------



org:Site a owl:Class, rdfs:Class;

    rdfs:label "Site"@en;
    rdfs:label "Site"@fr;
    rdfs:label "Sede"@it;

    rdfs:comment """An office or other premise at which the organization is located. Many organizations are spread across multiple sites and many sites will host multiple locations. In most cases a Site will be a physical location. However, we don't exclude the possibility of non-physical sites such as a virtual office with an associated post box and phone reception service. Extensions may provide subclasses to denote particular types of site."""@en;

    rdfs:comment """Un établissement ou tout autre lieu dans lequel une Organisation est localisé. Beaucoup d'organisations sont dispersées à travers plusieurs sites. Dans la plupart des cas un Site sera un lieu physique. Toutefois, nous n'excluons pas la possibilité de sites non-physiques comme un bureau virtuel avec une boîte postale et un service de secrétariat mutualisé. Des extensions pourraient fournir des sous-classes pour décrire des types de sites particuliers."""@fr;    
    rdfs:comment """Un ufficio o altra sede dovei l'organizzazione è situata. Molte organizzazione sono distribuite su più sedi e molte sedi ospitano più ubicazioni. Nella maggior parte dei casi un Site è una locazione fisica. Non si esclude la possibilità di indicare sedi non fisiche come ad esempio gli uffici virtuali. Le estensioni dell'ontologia potrebbero usare delle sottoclassi per rappresentare i tipi particolari di sede."""@it;
    rdfs:comment "組織が位置するオフィスやその他の敷地。多くの組織が複数のサイトに散在しており、多くのサイトが多数の場所を持つでしょう。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:Site rdfs:label "sede"@es ;
    rdfs:comment "Oficina, local o cualquier otro lugar en el que se encuentra una organización. Muchas organizaciones están distribuidas en varias sedes, que a su vez están repartidas en distintas ubicaciones. En muchos casos una sede será un sitio o local físico. Sin embargo, no se excluye la posibilidad de lugares no físicos como oficinas virtuales con los correspondientes apartados de correo y servicio de atención telefónica. Se pueden añadir más subtipos mediante extensiones para incluir tipos especiales de lugares."@es .


org:siteAddress a owl:ObjectProperty, rdf:Property;

    rdfs:label "site Address"@en;
    rdfs:label "adresse du Site"@fr;
    rdfs:label "indirizzo della sede"@it;

    rdfs:domain org:Site;
 #   rdfs:range  vcard:VCard;

    rdfs:comment """Indicates an address for the site in a suitable encoding. Use of vCard (using the http://www.w3.org/TR/vcard-rdf/ vocabulary) is encouraged but the range is left open to allow other encodings to be used. The address may include email, telephone, and geo-location information and is not restricted to a physical address. """@en;
    rdfs:comment """Indique une adresse pour le site dans un encodage approprié. L'usage du vocabulaire vCard ( http://www.w3.org/TR/vcard-rdf/) est encouragé, mais le range est ouvert pour permettre l'utilisation d'autres vocabulaires. L'adresse peut comporter le courriel, le téléphone, et l'information de géolocalisation; et n'est donc pas seulement limitée à une adresse physique. """@fr;
    rdfs:comment """Indica un indirizzo per la sede in una codifica appropriata. Il codominio è lasciato libero ma è consigliabile l'uso del vocabolario vCard (http://www.w3.org/TR/vcard-rdf/). L'indirizzo può includere email, numero di telefono e informazioni di geolocalizzazione e non è vincolato ad essere un indirizzo fisico."""@it;
    rdfs:comment "適切にコード化されたサイトのアドレスを示します。vCard[vcard-rdf]語彙などの有名なアドレスのコード化の使用が奨励されますが、他の符号化の使用を可能とするために値域はオープンのままにされます。アドレスには、電子メール、電話およびジオロケーション情報を含むことができ、物理的なアドレスに制限されません。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:siteAddress rdfs:label "es la dirección de la sede"@es ;
    rdfs:comment "Dirección de la sede según una codificación adecuada. Se recomienda el uso de vCard (que utiliza el vocabulario en http://www.w3.org/TR/vcard-rdf/), pero el rango no se restringe únicamente al uso de este vocabulario sino que se permite el uso de otros códigos. La dirección puede constar de una dirección de correo electrónico, un número de teléfono o información de geo-localización, y no se limita a una dirección postal física."@es .


org:hasSite a owl:ObjectProperty, rdf:Property;

    rdfs:label "has site"@en;
    rdfs:label "a un site"@fr;
    rdfs:label "ha sede"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:Site;

    rdfs:comment """Indicates a site at which the Organization has some presence even if only indirect (e.g. virtual office or a professional service which is acting as the registered address for a company). Inverse of `org:siteOf`."""@en;
    rdfs:comment """Indique un site sur lequel l'Organisation possède une présence, même indirecte (domiciliation, boite postale). Inverse de `org:siteOf`."""@fr;    
    rdfs:comment """Indica la sede in cui l'Organization ha una qualche presenza anche in modo indiretto (ad esempio un ufficio virtuale). È l'inverso di `org:siteOf`."""@it;
    rdfs:comment "組織が、間接（例えば、会社の登録住所として機能しているバーチャル・オフィスやプロフェッショナル・サービス）のみであったとしても、ある存在感を持っているサイトを示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:hasSite rdfs:label "tiene sede en"@es ;
    rdfs:comment "Lugar en donde la organización tiene algún tipo de presencia, incluso si es de forma indirecta (por ejemplo, una oficina virtual o servicio profesional que hagan la función de dirección registrada de la compañía). Es la relación inversa de `org:siteOf`."@es .


org:siteOf a owl:ObjectProperty, rdf:Property;

    rdfs:label "site Of"@en;
    rdfs:label "site de"@fr;
    rdfs:label "sede di"@it;

    rdfs:domain org:Site;
    rdfs:range  org:Organization;

    rdfs:comment """Indicates an Organization which has some presence at the given site. This is the inverse of `org:hasSite`."""@en;
    rdfs:comment """Indique une Organisation qui a une présence sur le site en question. Inverse de `org:hasSite`."""@fr;    
    rdfs:comment """Indica un'Organization che ha una qualche presenza nella data sede. È l'inverso di `org:hasSite`."""@it;
    rdfs:comment "あるサイトである存在感を持っている組織を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:siteOf rdfs:label "es sede de"@es ;
    rdfs:comment "Organización que tiene ubicación en un lugar. Es la relación inversa de `org:hasSite`."@es .

org:hasSite owl:inverseOf org:siteOf . 

org:siteOf owl:inverseOf org:hasSite . 



org:hasPrimarySite a owl:ObjectProperty, rdf:Property;

    rdfs:label "primary Site"@en;
    rdfs:label "site principal"@fr;
    rdfs:label "sede principale"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:Site;
    rdfs:subPropertyOf org:hasSite;

    rdfs:comment """Indicates a primary site for the Organization, this is the default means by which an Organization can be contacted and is not necessarily the formal headquarters."""@en;    
    rdfs:comment """Indique le site principal d'une Organisation, le moyen par défaut par lequel l'Organisation peut être contactée et pas nécessairement le siège social légal."""@fr;
    rdfs:comment """Indica la sede principale per l'Organization. È da considerarsi come la sede di default in cui l'Organization deve essere contattata pur non essendo necessariamente il quartier generale."""@it;
    rdfs:comment "組織の主要サイトを示します。組織の窓口となりえるデフォルトの手段ですが、正式な本部とは限りません。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:hasPrimarySite rdfs:label "tiene sede principal en"@es ;
    rdfs:comment "Oficina principal de la organización, la opción por defecto para ponerse en contacto con una organización, aunque no corresponde necesariamente con las oficinas centrales de la organización."@es .


org:hasRegisteredSite a owl:ObjectProperty, rdf:Property;

    rdfs:label "registered Site"@en;
    rdfs:label "siège social"@fr;
    rdfs:label "sede legale"@it;

    rdfs:domain org:FormalOrganization;
    rdfs:range  org:Site;
    rdfs:subPropertyOf org:hasPrimarySite;

    rdfs:comment """Indicates the legally registered site for the organization, in many legal jurisdictions there is a requirement that FormalOrganizations such as Companies or Charities have such a primary designed site. """@en;
    rdfs:comment """Indique l'établissement principal légalement enregistré pour l'Organisation. Dans de nombreuses juridictions existe l'obligation pour une Organisation Formelle d'avoir un tel site principal. """@fr;    
    rdfs:comment """Indica la sede legale per l'Organization. In molte giurisdizioni è richiesto che una FormalOrganization abbia una sede di questo tipo."""@it;
    rdfs:comment "組織の法律上登録されたサイトを示し、多くの法的管轄区域では、会社や慈善団体などのFormalOrganizations（正式な組織）がそのような主要サイトを持っているという要件があります。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

 org:hasRegisteredSite rdfs:label "tiene sede registrada en"@es ;
    rdfs:comment "Oficina o sede legalmente registrada de la organización. En muchas jurisdicciones legales existe el requisito de que organizaciones formales tales como empresas u organizaciones de beneficencia tengan una sede principal de este tipo."@es .


org:basedAt a owl:ObjectProperty, rdf:Property;

    rdfs:label "based At"@en;
    rdfs:label "basé à"@fr;
    rdfs:label "basata a"@it;

    rdfs:domain foaf:Person;
    rdfs:range  org:Site;  

    rdfs:comment """Indicates the site at which a person is based. We do not restrict the possibility that a person is based at multiple sites."""@en;
    rdfs:comment """Indique le site sur lequel une personne est basée. Nous ne limitons pas le nombre de sites sur lesquels une personne peut être basée."""@fr;    
    rdfs:comment """Indica la sede in cui una è stabilita una persona. Non esclude la possibilità che una persona sia allocata su più sedi."""@it;
    rdfs:comment "人が基礎としているサイトを示します。人が複数のサイトを基礎としている可能性を制限しません。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:basedAt rdfs:label "trabaja en la sede"@es ;
    rdfs:comment "Lugar en el que trabaja una persona. No se restringe el hecho de que una persona pueda estar adscrita a múltiples ubicaciones."@es .


org:location a owl:DatatypeProperty, rdf:Property;

    rdfs:label "location"@en;
    rdfs:label "localisation"@fr;
    rdfs:label "luogo"@it;

    rdfs:domain foaf:Person;
    rdfs:range  xsd:string;

    rdfs:comment """Gives a location description for a person within the organization, for example a _Mail Stop_ for internal posting purposes."""@en;
    rdfs:comment """Indique la description de l'endroit ou est basé une personne de l'Organisation, par exemple pour des besoins de messagerie interne (Bureau 42)."""@fr;    
    rdfs:comment """Indica la descrizione del luogo presso cui è possibile reperire una persona dell'organizzazione."""@it;
    rdfs:comment "例えば、内部配送目的のメール・ストップ（Mail Stop）などの、組織内の人の位置記述を提供します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:location rdfs:label "está ubicado en"@es ;
    rdfs:label "está ubicada en"@es ;
    rdfs:comment "Lugar o ubicación exacta de una persona en una organización con el objetivo de facilitar, por ejemplo, la entrega de correo."@es .


# -- Projects and other activities -----------------------------------------------------------


org:OrganizationalCollaboration a owl:Class, rdfs:Class;

    rdfs:subClassOf  org:Organization;
    owl:equivalentClass
         [ a  owl:Class ;
           owl:intersectionOf (
               org:Organization 
               [a  owl:Restriction ;
                   owl:allValuesFrom org:Organization ;
                   owl:onProperty org:hasMember
               ]
           )
         ]; 

    rdfs:label "Endeavour"@en;
    rdfs:label "Partenariat"@fr;
    rdfs:label "Collaborazione"@it;

    rdfs:comment """A collaboration between two or more Organizations such as a project. It meets the criteria for being an Organization in that it has an identity and defining purpose independent of its particular members but is neither a formally recognized legal entity nor a sub-unit within some larger organization. Might typically have a shorter lifetime than the Organizations within it, but not necessarily. All members are `org:Organization`s rather than individuals and those Organizations can play particular roles within the venture. Alternative names: _Project_ _Venture_  _Endeavour_ _Consortium_ _Endeavour_"""@en;
    rdfs:comment """Une collaboration entre deux ou plusieurs Organisations, telle qu'un projet commun. Un partenariat peut être considéré comme Organisation dans le sens ou il possède une identité et un But propre indépendant de ceux de ses membres, mais ce n'est ni une entité légale ni une sous-unité d'une Organisation plus grande. Typiquement, elle peut avoir une durée de vie plus courte que les Organisations qui la composent, mais pas nécessairement. Tous les membres sont des `org:Organization`s plutôt que des individus et ces Organisations peuvent jouer des Rôles particuliers au sein du Partenariat. """@fr;    
    rdfs:comment """È una collaborazione tra due o più Organization come ad esempio un progetto. Consente di rappresentare alcune identità dell'Organization che sono fuori dallo scopo principale e non sono formalmente riconosciute. Potrebbe anche avere un ciclo di vita limitato."""@it;
    rdfs:comment "プロジェクトなどの2つ以上の組織間のコラボレーション。それは、アイデンティティを有し、その特定のメンバーとは無関係に目的を定めているという点で、組織としての基準を満たしますが、正式に認識された法的実体でも、あるより大きな組織内のサブユニットでもありません。一般的には、その内部の組織よりも存続期間が短いかもしれませんが、必ずしもそうとは限りません。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:OrganizationalCollaboration rdfs:label "proyecto de cooperación empresarial"@es ;
    rdfs:comment "Colaboración determinada entre dos o más organizaciones, como en el caso de un proyecto común. Cumple con los criterios de ser una organización en sí misma, en la medida en que tiene una identidad y un propósito definido independiente de sus miembros en particular, pero no es una entidad legal formalmente reconocida ni una sub-unidad dentro de una organización más grande. La duración suele ser más corta que la de las organizaciones que lo componen, pero no necesariamente. Todos sus miembros son de tipo `org:Organization` en vez de individuos, y desempeñan una actividad concreta en el marco del proyecto de cooperación."@es .

# -- Historical information -----------------------------------------------------------

org:ChangeEvent a owl:Class, rdfs:Class;
    rdfs:subClassOf prov:Activity;

    rdfs:label "Change Event"@en;
    rdfs:label "Évènement"@fr;
    rdfs:label "Evento di cambiamento"@it;

    rdfs:comment """Represents an event which resulted in a major change to an organization such as a merger or complete restructuring. It is intended for situations where the resulting organization is sufficient distinct from the original organizations that it has a distinct identity and distinct URI. Extension vocabularies should define sub-classes of this to denote particular categories of event. The instant or interval at which the event occurred should be given by `prov:startAtTime` and `prov:endedAtTime`, a description should be given by `dct:description`. """@en;    
    rdfs:comment """Représente un Évènement impliquant un changement majeur dans l'Organisation, comme une fusion ou une restructuration. Prévu pour des situations ou l'organisation finale est suffisamment différente des Organisations originales pour qu'elle ait une identité et une URI distinctes. Des vocabulaires d'extension devraient définir des sous-classes de celle-ci pour annoter les différentes catégories d'Évènemenents. Le moment ou l'intervalle de l'Évènement devrait être indiqué avec `prov:startAtTime` et `prov:endedAtTime`, et une description avec la classe `dct:description`. """@fr;
    rdfs:comment """Rappresenta un evento risultato essere un importante cambiamento per un'organizzazione come ad esempio una fusione o una riorganizzazione. È pensato per quelle situazioni in cui l'organizzazione risultante si distingue da quella originale sufficientemente da essere rappresentata con una URI differente. Le estensioni del vocabolario dovrebbero definire le sotto-classi per esprimere particolari categorie di eventi. L'istante o l'intervallo in cui l'evento accade dovrebbe essere espresso tramite `prov:startAtTime` e`prov:endedAtTime`. Una descrizione dovrebbe essere fornita attraverso `dct:description`."""@it;
    rdfs:comment "合併や完全な再編などの組織に大きな変化をもたらした出来事を表わします。これは、結果として作成される組織と元の組織とが、別のアイデンティティーと別のURIを持つに足るほど異なる状況を対象としています。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:ChangeEvent rdfs:label "evento de cambio"@es ;
    rdfs:comment "Evento que da como resultado un cambio sustancial en la organización, por ejemplo, una fusión o una reestructuración total. Está pensado para situaciones en las que la organización resultante es lo suficientemente distinta de las organizaciones originales, tiene una identidad distinta y una URI también distinta. Se deberían definir subtipos de eventos mediante vocabularios específicos (Extension vocabularies) para referirse a categorías de eventos específicos. El momento o periodo en el que el evento ocurre se debería expresar mediante las propiedades `prov:startAtTime` y `prov:endedAtTime`, y una descripción del mismo se debería incluir mediante el uso de la propiedad `dct:description`."@es .


org:originalOrganization a owl:ObjectProperty, rdf:Property;

    rdfs:label "original organization"@en;
    rdfs:label "organisation originelle"@fr;
    rdfs:label "organizzazione originale"@it;

    rdfs:domain org:ChangeEvent;
    rdfs:range  org:Organization;
    rdfs:subPropertyOf prov:used;

    rdfs:comment """Indicates one or more organizations that existed before the change event. Depending on the event they may or may not have continued to exist after the event. Inverse of `org:changedBy`."""@en;
    rdfs:comment """Indique une ou plusieurs organisations qui ont existé avant un évènement de changement. Selon l'évènement, ces organisations ont pu continuer à exister ou non. Inverse de `org:changedBy`. """@fr;
    rdfs:comment """Indica una o più organizzazioni pregresse rispetto a un evento di cambiamento. A seconda dell'evento, queste organizzazioni potrebbero essere esistenti dopo l'evento o  aver cessato la loro esistenza. È l'inverso di `org:changedBy`."""@it;
    rdfs:comment "変更のきっかけとなった出来事以前に存在した1つ以上の組織を示します。出来事によって、出来事の後にそれらは存在し続けたかも、存在し続けなかったかもしれません。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:originalOrganization rdfs:label "es organización original"@es ;
    rdfs:comment "Una o más organizaciones que existían antes de que sucediera el cambio en la organización. Dependiendo del tipo de cambio, dichas organizaciones pueden haber dejado de existir o no. Es la relación inversa de `org:changedBy`."@es .


org:changedBy a owl:ObjectProperty, rdf:Property;

    rdfs:label "changed by"@en;
    rdfs:label "modifiée par"@fr;
    rdfs:label "cambiata da"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:ChangeEvent;

    rdfs:comment """Indicates a change event which resulted in a change to this organization. Depending on the event the organization may or may not have continued to exist after the event. Inverse of `org:originalOrganization`."""@en;
    rdfs:comment """Indique un évènement qui a impliqué un changement dans l'Organisation. Selon l'évènement, l'Organisation a continué à exister après l'évènement, ou pas. Inverse de `org:originalOrganization`."""@fr;    
    rdfs:comment """Indica un evento che ha contribuito al cambiamento di questa organizzazione. A seconda dell'evento, l'organizzazione potrebbe essere esistente dopo l'evento o aver cessato la propria esistenza. È l'inverso di `org:originalOrganization`."""@it;
    rdfs:comment "この組織の変更のきっかけとなった出来事を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:changedBy rdfs:label "es modificada por"@es ;
    rdfs:label "es modificado por"@es ;
    rdfs:comment "Evento de cambio que resulta en una modificación en la organización. Dependiendo del evento, la organización puede dejar de existir tras el cambio. Es la relación inversa de `org:originalOrganization`."@es .


org:originalOrganization owl:inverseOf org:changedBy .

org:changedBy            owl:inverseOf org:originalOrganization .



org:resultedFrom a owl:ObjectProperty, rdf:Property;

    rdfs:label "resulted from"@en;
    rdfs:label "issue de"@fr;
    rdfs:label "risultato da"@it;

    rdfs:domain org:Organization;
    rdfs:range  org:ChangeEvent;
    rdfs:subPropertyOf prov:wasGeneratedBy;

    rdfs:comment """Indicates an event which resulted in this organization. Inverse of `org:resultingOrganization`."""@en;
    rdfs:comment """Indique un évènement dont est issue l'Organisation. Inverse de `org:resultingOrganization`."""@fr; 
    rdfs:comment """Indica l'evento che ha permesso all'organizzazione di instaurarsi. È l'inverso di `org:resultingOrganization`."""@it;   
    rdfs:comment "この組織になった（導いた、作成された）きっかけとなった出来事を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ; 
    .

org:resultedFrom rdfs:label "es el resultado de"@es ;
    rdfs:comment "Evento que tiene como resultado la creación de una organización."@es .


org:resultingOrganization a owl:ObjectProperty, rdf:Property;

    rdfs:label "resulted in"@en;
    rdfs:label "a donné naissance à"@fr;
    rdfs:label "risultato in"@it;

    rdfs:domain org:ChangeEvent;
    rdfs:range  org:Organization;

    rdfs:comment """Indicates an organization which was created or changed as a result of the event. Inverse of `org:resultedFrom`."""@en;
    rdfs:comment """Indique une organisation qui a été créée ou a été modifiée à la suite d'un Évènement de changement. Inverse de `org:resultedFrom`."""@fr;
    rdfs:comment """Indica l'organizzazione che è stata creata o mutata a seguito dell'evento. È l'inverso di `org:resultedFrom`."""@it;
    rdfs:comment "出来事の結果、作成、変更された組織を示します。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:resultingOrganization rdfs:label "resulta en"@es ;
    rdfs:comment "Organización que ha sido creada o modificada tras un evento específico.  Es la relación inversa de `org:resultedFrom`."@es .


org:resultedFrom          owl:inverseOf org:resultingOrganization .

org:resultingOrganization owl:inverseOf org:resultedFrom .


# Property chain to license derivation relation
prov:wasDerivedFrom owl:propertyChainAxiom (org:resultedFrom org:originalOrganization) .



# -- Posts - added 2012-09-30 -----------------------------------------------------------

org:Post a owl:Class, rdfs:Class;

    rdfs:label "Post"@en;
  	rdfs:label "Poste"@fr;
    rdfs:label "Impiego"@it;

    rdfs:comment """A Post represents some position within an organization that exists independently of the person or persons filling it. Posts may be used to represent situations where a person is a member of an organization ex officio (for example the Secretary of State for Scotland is part of UK Cabinet by virtue of being Secretary of State for Scotland, not as an individual person). A post can be held by multiple people and hence can be treated as a organization in its own right."""@en;
  	rdfs:comment """Un Poste représente une position au sein d'une Organisation qui existe indépendamment de la personne ou des personnes qui le remplissent. Les postes peuvent être utilisés pour représenter des situations où une personne est membre d'une Organisation d'office (par exemple, le Secrétaire d'Etat pour l'Ecosse fait partie du Cabinet du Royaume-Uni du fait d'être Secrétaire d'Etat pour l'Ecosse, non pas comme une personne physique). Un poste après peut être occupé par plusieurs personnes et peut donc être considéré comme une Organisation à part entière."""@fr;
    rdfs:comment """Un Impiego rappresenta una posizione all'interno dell'organizzazione che esiste indipendentemente dalla persona che la ricopre. Gli impieghi possono essere utilizzati per le situazioni in cui una persona è membro di un'organizzazione o di un ufficio (ad esempio un segretario di stato). Un Impiego può essere ricoperto da più persone."""@it;
    rdfs:comment "ポストは、それを埋める人（人々）とは無関係に存在する組織内のある位置を表わします。ポストは、人が職権上、組織のメンバーである状況を表わすために使用できます（例えば、スコットランド大臣は、個人としてではなく、スコットランド大臣であることにより、英国内閣の一部です）。ポストは、複数の人々によって保持されることが可能だあるため、それ自体を組織として扱うことができます。"@ja;
    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:Post rdfs:label "puesto"@es ;
    rdfs:comment "Puesto o posición que representa algún tipo de empleo dentro de una organización, que existe independientemente de la persona o personas que lo desempeñan. Esta clase puede utilizarse para representar situaciones en las que una persona es miembro de una organización ex oficio (por ejemplo, el Secretario de Estado escocés es parte del Gabinete del gobierno británico por virtud de ser Secretario de Estado en Escocia, y no como individuo). Un puesto puede ser desempeñado por múltiples individuos y de aquí que sea tratado como una organización en sí misma."@es .

org:holds a owl:ObjectProperty, rdf:Property;

    rdfs:label "holds"@en;
  	rdfs:label "occupe"@fr;
    rdfs:label "ricopre"@it;

    rdfs:comment """Indicates a Post held by some Agent."""@en;
    rdfs:comment """Indicate un Poste occupé par un Agent."""@fr;
    rdfs:comment """Indica un Impiego ricoperto da un Agent."""@it;
    rdfs:comment "あるエージェントによって保持されているポストを示します。"@ja;
    rdfs:domain foaf:Agent;
    rdfs:range  org:Post;

    # Corrected 2014-01-25
    # rdfs:subPropertyOf org:memberOf;

    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:holds rdfs:label "ocupa"@es ;
    rdfs:comment "Puesto ocupado por algún agente."@es .

org:heldBy a owl:ObjectProperty, rdf:Property;

    rdfs:label "held by"@en;
  	rdfs:label "occupé par"@fr;
    rdfs:label "ricoperto da"@it;

    rdfs:comment """Indicates an Agent which holds a Post."""@en;
    rdfs:comment """Indicate un Agent qui occupe le Poste."""@fr;
    rdfs:comment  """Indica un Agent che ricopre un Post."""@it;
    rdfs:comment "ポストを保持するエージェントを示します。"@ja;
    rdfs:domain  org:Post;
    rdfs:range foaf:Agent;

    # Corrected 2014-01-25
    # rdfs:subPropertyOf org:hasMember;

    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
    .

org:heldBy rdfs:label "ocupado por"@es ;
    rdfs:comment "Agente que ocupa un puesto."@es .

org:holds owl:inverseOf org:heldBy .


org:postIn a owl:ObjectProperty, rdf:Property;

    rdfs:label "post in"@en;
	rdfs:label "poste chez"@fr;
    rdfs:label "impiego in"@it;

    rdfs:comment """Indicates the Organization in which the Post exists."""@en;
    rdfs:comment """Indicate l'Organisation dans laquelle le Poste existe."""@fr;
    rdfs:comment """Indica l'Organization in cui il Post è presente."""@it;
    rdfs:comment "ポストが存在する組織を示します。"@ja;
    rdfs:domain org:Post;
