    .

org:postIn rdfs:label "es un puesto en"@es ;
    rdfs:comment "Organización en la que existe el puesto."@es .

org:hasPost a owl:ObjectProperty, rdf:Property;

    rdfs:label "post"@en;
	rdfs:label "possède un poste"@fr;
    rdfs:label "impiego"@it;

    rdfs:comment """Indicates a Post which exists within the Organization."""@en;
	rdfs:comment """Indicate un Poste qui existe dans l'Organisation."""@fr;
    rdfs:comment """Indica il Post che è presente in una Organization."""@it;
    rdfs:comment "組織内に存在するポストを示します。"@ja;
    rdfs:domain  org:Organization;
    rdfs:range   org:Post;

    rdfs:isDefinedBy <http://www.w3.org/ns/org> ;
