def text(value, label, maximum=8000, *, empty=False):
    if not isinstance(value, str) or (not empty and not value.strip()) or len(value)>maximum or "\0" in value:
        raise ValueError(label + " is missing or exceeds its supported length.")
    return value.strip()

def integer(value, label, low, high):
    if type(value) is not int or not low <= value <= high:
        raise ValueError(label + " must be an integer from " + str(low) + " to " + str(high) + ".")
    return value

def decoded(value):
    if not isinstance(value, str):
        raise ValueError("Keep the exact original file bytes in data_base64.")
    try:
        data = base64.b64decode(value, validate=True)
    except (ValueError, TypeError) as exc:
        raise ValueError("The original file bytes are not valid base64.") from exc
    if len(data)>MAX_FILE:
        raise ValueError("A source or native result file exceeds 64 MiB.")
    return data

def iri(value, label):
    if not isinstance(value, str) or not re.match(r"^[A-Za-z][A-Za-z0-9+.-]*:", value) or any(c.isspace() for c in value):
        raise ValueError(label + " must be an absolute IRI.")
    return value

class SemanticApplication(DatasetOperations):
    def __init__(self, root, *, start_worker=True):
        self.root = private_directory(root)
        self.lock = threading.RLock()
        self._owner = os.open(self.root/"workspace.lock", os.O_CREAT|os.O_RDWR|getattr(os,"O_NOFOLLOW",0), 0o600)
        try:
            fcntl.flock(self._owner, fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError as exc:
            os.close(self._owner)
            raise ValueError("This workspace already has a running operator. Use its original local address.") from exc
        self.store = ApplicationStore(self.root)
        self.vault = PrivateVault(self.root/"private")
        self.jobs_root = private_directory(self.root/"native-jobs")
        self.receiving_root = private_directory(self.root/"receiving")
        self.stop = threading.Event()
        self.wake = threading.Event()
        self.child = None
        self.child_job = None
        self.child_started = None
        self.child_log = None
        self.thread = None
        self.closed = False
        self.received_hosts = {}
        if start_worker:
            self.thread = threading.Thread(target=self._supervise, name="semantic-native-worker", daemon=True)
            self.thread.start()

    def _id(self, kind, operation_id):
        return kind+"-"+digest(canonical({"workspace":self.store.workspace_id,"operation_id":operation_id}))[:28]

    def _revision(self, kind, key, revision=None):
        identifier(key)
        current = self.store.document(kind, key)
        if revision is None or revision == current["revision"]:
            return current
        integer(revision, "Source revision", 1, current["revision"])
        for row in self.store.history(kind, key):
            if row["revision"] == revision:
                return row
        raise KeyError("The original selected revision does not exist.")

    def _write(self, kind, key, payload, operation_id, actor, expected_revision=0):
        # A business revision can commit before its HTTP result is delivered.
        # Reconcile that exact original revision before checking a retry's stale revision.
        for row in self.store.history(kind, key):
            if row["payload"].get("_operation_id") == operation_id:
                return row
        return self.store.save(kind, key, {**payload, "_operation_id":operation_id},
                               actor=actor, expected_revision=expected_revision)

    def _fingerprint(self, payload):
        value = dict(payload)
        if "data_base64" in value:
            value["data_base64"] = {"sha256":digest(decoded(value["data_base64"]))}
        if value.get("catalog_data_base64"):
            value["catalog_data_base64"] = {"sha256":digest(decoded(value["catalog_data_base64"]))}
        if "passphrase" in value:
            secret = value["passphrase"]
            if not isinstance(secret,str):
                raise ValueError("Enter the recovery passphrase.")
            value["passphrase"] = {"private_hmac":hmac.new(self.vault.key,secret.encode(),hashlib.sha256).hexdigest()}
        return value

    def perform(self, action, payload, *, operation_id, actor):
        identifier(operation_id, "Operation ID")
        text(actor, "Local operator", 200)
        if not isinstance(payload, dict):
            raise ValueError("Operation inputs must be a JSON object.")
        actions = {
            "source.import":self._source_import, "source.reference":self._source_reference, "source.profile":self._source_profile,
            "source.inspect":self._source_inspect, "mapping.save":self._mapping_save,
            "snapshot.build":self._snapshot_build, "validation.run":self._validation_run,
            "query.run":self._query_run, "comparison.run":self._comparison_run,
            "decision.save":self._decision_save, "job.continue":self._job_continue,
            "job.cancel":self._job_cancel, "handoff.export":self._handoff_export,
            "handoff.receive":self._handoff_receive, "recovery.export":self._recovery_export,
            "recovery.restore":self._recovery_restore, "workspace.open":self._workspace_open,
        }
        if action not in actions:
            raise ValueError("Choose a supported semantic operation.")
        with self.lock:
            if self.closed:
                raise ValueError("This operator has closed.")
            original = self.store.begin(operation_id, action, self._fingerprint(payload), actor)
            if original is not None:
                return original
            try:
                result = self._resume_pinned_job(NATIVE_ACTIONS[action], payload, operation_id, actor) if action in NATIVE_ACTIONS else None
                if result is None:
                    result = actions[action](payload, operation_id, actor)
                return self.store.finish(operation_id, result)
            except BaseException as exc:
                self.store.interrupted(operation_id, exc)
                raise
            finally:
                self.wake.set()

    def _source_import(self, p, op, actor):
        data = decoded(p["data_base64"])
        if not data:
            raise ValueError("Choose a nonempty original source file.")
        format = p.get("format")
        role = p.get("role")
        if format not in FORMATS or role not in ROLES or (format=="csv") != (role=="table"):
            raise ValueError("Choose the original RDF format and role, or CSV with the table role.")
        key = p.get("id") or self._id("source",op)
        if p.get("id") and "expected_revision" not in p:
            raise ValueError("A source edit requires its current expected_revision.")
        artifact = self.store.add_artifact(data, name=text(p["name"],"Source filename",240),
            media_type=FORMATS[format], role="source",
            source_reference=text(p["source_reference"],"Original source reference"))
        record = {"title":text(p["title"],"Source title",300), "format":format, "role":role,
                  "edition":text(p.get("edition",""),"Source edition",500,empty=True),
                  "license":text(p.get("license",""),"Source license",2000,empty=True),
                  "source_reference":artifact["source_reference"], "artifact_id":artifact["id"],
                  "sha256":artifact["sha256"], "bytes":artifact["bytes"]}
        if p.get("catalog_data_base64"):
            if format != "nquads":
                raise ValueError("A graph catalogue companion belongs to an N-Quads source.")
            catalogue = decoded(p["catalog_data_base64"])
            value = read_json(catalogue)
            if not isinstance(value,dict) or value.get("schema") != "commons-semantic-graph-catalog/1":
                raise ValueError("Choose the original dataset graph catalogue JSON.")
            if value.get("nquads_sha256") != record["sha256"]:
                raise ValueError("The companion catalogue belongs to different N-Quads bytes.")
            catalog = self.store.add_artifact(catalogue,
                name=text(p.get("catalog_name","graph-catalog.json"),"Catalogue filename",240),
                media_type="application/json",role="source-graph-catalog",
                source_reference=record["source_reference"]+" / retained graph catalogue")
            record["dataset_catalog"]={k:catalog[k] for k in ("id","sha256","bytes","name")}
        return self._write("source",key,record,op,actor,p.get("expected_revision",0))

    def references(self):
        manifest = read_json((ROOT/"reference/SOURCE-MANIFEST.json").read_bytes())
        return manifest

    def _source_reference(self, p, op, actor):
        name = relative(p["path"])
        original = next((f for f in self.references()["files"] if f["path"] == name), None)
        if original is None:
            raise KeyError("Choose one of the bundled original reference sources.")
        data = (ROOT/"reference"/name).read_bytes()
        if len(data) != original["bytes"]:
            raise ValueError("The bundled original reference size changed.")
        if original.get("git_blob_sha"):
            actual = hashlib.sha1(b"blob "+str(len(data)).encode()+b"\0"+data).hexdigest()
            if actual != original["git_blob_sha"]:
                raise ValueError("The bundled original reference differs from its upstream Git object.")
        ext = Path(name).suffix
        format = {".ttl":"turtle",".nt":"nt",".rdf":"xml",".jsonld":"json-ld",".trig":"trig",".nq":"nquads"}.get(ext)
        if not format:
            raise ValueError("Choose a supported original RDF graph or dataset source.")
        role = p.get("role","data")
        return self._source_import({"data_base64":base64.b64encode(data).decode(), "title":p.get("title",Path(name).name),
            "name":Path(name).name,"format":format,"role":role,"license":original.get("license") or "",
            "source_reference":original.get("git_blob_url") or original.get("source_url") or original.get("repo","")+" / "+original.get("source_path",name),
            "edition":original.get("git_blob_sha") or self.references().get("retrieved_at","")},op,actor)

    def _source_profile(self, p, op, actor):
        profile=next((item for item in self.references().get("profiles",[]) if item["id"]==p.get("profile_id")),None)
        if profile is None:
            raise ValueError("Choose one of the retained documented reference profiles.")
        rows=[]
        for role,paths in (("shapes",profile["shape_paths"]),("ontology",profile.get("ontology_paths",[]))):
            for index,path in enumerate(paths):
                # Each source has its own stable original sub-operation. A disk
                # interruption can resume the full profile without duplicate rows.
                child="profile-source-"+digest(canonical({"operation":op,"role":role,"path":path}))[:32]
                row=self._source_reference({"path":path,"role":role,
                    "title":profile["title"]+" / "+Path(path).name},child,actor)
                rows.append(row)
        return {"profile_id":profile["id"],"title":profile["title"],
                "source_reference":profile["source_reference"],"note":profile["note"],
                "sources":rows,"original_files_retained":True}

    def _source_input(self, ref, key=None):
        if not isinstance(ref,dict):
            raise ValueError("Keep each selected source ID and revision together.")
        row = self._revision("source",ref["id"],ref.get("revision"))
        p = row["payload"]
        meta = self.store.artifact(p["artifact_id"])
        return {"key":key or "source-"+row["id"]+"-r"+str(row["revision"]), "artifact_id":meta["id"],
                "sha256":meta["sha256"], "bytes":meta["bytes"], "format":p["format"],
                "role":p["role"],"source_id":row["id"], "revision":row["revision"],
                "title":p["title"], "source_reference":p["source_reference"]}

    def _source_inspect(self, p, op, actor):
        source = self._source_input(p["source"],"selected")
        if p.get("data_model") == "dataset" or source["format"] in ("trig","nquads"):
            return self._dataset_inspect(p,op,actor)
        return self._new_job("inspect",[source],{"input_key":"selected"},p,op,actor)

    def _mapping_save(self, p, op, actor):
        source = self._source_input(p["source"])
        if source["format"]!="csv":
            raise ValueError("A declarative mapping uses an original CSV source.")
        definition = p.get("definition")
        if not isinstance(definition,dict) or set(definition)-{"subject_template","classes","delimiter","null_values","fields"}:
            raise ValueError("Choose the supported explicit CSV mapping fields.")
        definition = read_json(canonical(definition))
        text(definition.get("subject_template"),"Subject IRI template",2000)
        iri(definition["subject_template"],"Subject IRI template")
        if not isinstance(definition.get("classes",[]),list):
            raise ValueError("Mapped RDF classes must be an array.")
        for c in definition.setdefault("classes",[]): iri(c,"Mapped RDF class")
        delimiter=definition.setdefault("delimiter",",")
        if not isinstance(delimiter,str) or len(delimiter)!=1 or delimiter in "\r\n\0":
            raise ValueError("A CSV delimiter must be one character.")
        nulls=definition.setdefault("null_values",[""])
        if not isinstance(nulls,list) or any(not isinstance(n,str) for n in nulls):
            raise ValueError("Declare the exact CSV null strings.")
        fields=definition.get("fields")
        if not isinstance(fields,list) or not fields:
            raise ValueError("Map at least one CSV column.")
        for field in fields:
            if not isinstance(field,dict) or set(field)-{"column","predicate","kind","datatype","language","iri_template"}:
                raise ValueError("A mapping field contains unsupported properties.")
            text(field.get("column"),"CSV column",500)
            iri(field.get("predicate"),"Mapped predicate")
            if field.get("kind") not in ("literal","iri"):
                raise ValueError("Choose literal or IRI for each field.")
            if field.get("datatype"): iri(field["datatype"],"Literal datatype")
            if field.get("datatype") and field.get("language"):
                raise ValueError("A literal may have a datatype or language.")
            if field.get("language") and not re.fullmatch(r"[A-Za-z]+(?:-[A-Za-z0-9]+)*",field["language"]):
                raise ValueError("Choose a valid literal language tag.")
            if field["kind"]=="iri" and (field.get("datatype") or field.get("language")):
                raise ValueError("IRI mappings do not carry literal datatypes or language tags.")
            if field.get("iri_template"): iri(field["iri_template"],"Object IRI template")
        key=p.get("id") or self._id("mapping",op)
        if p.get("id") and "expected_revision" not in p:
            raise ValueError("A mapping edit requires its current expected_revision.")
        return self._write("mapping",key,{"title":text(p["title"],"Mapping title",300),
            "source":{"id":source["source_id"],"revision":source["revision"],"sha256":source["sha256"]},
            "definition":definition,"review_note":text(p.get("review_note",""),"Mapping review note",8000,empty=True)},
            op,actor,p.get("expected_revision",0))

    def _snapshot_build(self, p, op, actor):
        if p.get("data_model") == "dataset":
            return self._dataset_build(p,op,actor)
        if p.get("data_model","graph") != "graph":
            raise ValueError("Choose graph or dataset snapshot mode.")
        inputs, data_keys, mappings = [], [], []
        for index, ref in enumerate(p.get("sources",[])):
            item=self._source_input(ref,"data-"+str(index))
            if item["format"] not in ("turtle","nt","xml","json-ld") or item["role"]!="data":
                raise ValueError("Snapshot data must use original RDF data sources.")
            inputs.append(item); data_keys.append(item["key"])
        for index, ref in enumerate(p.get("mappings",[])):
            row=self._revision("mapping",ref["id"],ref.get("revision"))
            item=self._source_input(row["payload"]["source"],"table-"+str(index))
            if item["sha256"]!=row["payload"]["source"]["sha256"]:
                raise ValueError("The mapping's original table identity changed.")
            inputs.append(item)
            mappings.append({**row["payload"]["definition"],"mapping_id":row["id"],"revision":row["revision"],"input_key":item["key"]})
        if not inputs:
            raise ValueError("Choose at least one RDF source or CSV mapping.")
        return self._new_job("snapshot",inputs,{"data_keys":data_keys,"mappings":mappings},p,op,actor)

    def _snapshot_input(self, ref, key="graph", role="graph"):
        row=self._revision("snapshot",ref["id"],ref.get("revision"))
        item=next((v for v in row["payload"]["files"] if v["role"]==role),None)
        if item is None:
            raise KeyError("The selected snapshot has no complete "+role+" output.")
        meta=self.store.artifact(item["artifact_id"])
        return {"key":key,"artifact_id":meta["id"],"sha256":meta["sha256"],"bytes":meta["bytes"],
                "format":{"graph":"nt","dataset":"nquads"}.get(role,"json"),
                "role":"snapshot" if role in ("graph","dataset") else role,
                "source_id":row["id"],"revision":row["revision"],"title":row["payload"]["title"],
                "source_reference":"Original snapshot "+row["id"]+" revision "+str(row["revision"])}

    def _validation_run(self,p,op,actor):
        if self._dataset_snapshot(p["snapshot"]):
            return self._dataset_validate(p,op,actor)
        inputs=[self._snapshot_input(p["snapshot"])]
        shapes,ontologies=[],[]
        for role,refs,keys in (("shapes",p.get("shapes",[]),shapes),("ontology",p.get("ontologies",[]),ontologies)):
            for index,ref in enumerate(refs):
                item=self._source_input(ref,role+"-"+str(index))
                if item["role"]!=role or item["format"] not in ("turtle","nt","xml","json-ld"):
                    raise ValueError("Choose original RDF "+role+" inputs.")
                inputs.append(item);keys.append(item["key"])
        if not shapes:
            raise ValueError("Select the SHACL shapes that define this validation.")
        inference=p.get("inference","none")
        if inference not in ("none","rdfs","owlrl","both"):
            raise ValueError("Choose an explicit inference mode.")
        for name in ("allow_infos","allow_warnings"):
            if name in p and type(p[name]) is not bool:
                raise ValueError(name+" must be true or false.")
        return self._new_job("validate",inputs,{"graph_key":"graph","shape_keys":shapes,"ontology_keys":ontologies,
            "inference":inference,"allow_infos":p.get("allow_infos",False),"allow_warnings":p.get("allow_warnings",False)},p,op,actor)

    def _query_run(self,p,op,actor):
        if self._dataset_snapshot(p["snapshot"]):
            return self._dataset_query(p,op,actor)
        query=text(p.get("query"),"SPARQL query",100000)
        limit=integer(p.get("row_limit",10000),"Query row limit",1,100000)
        return self._new_job("query",[self._snapshot_input(p["snapshot"])],{"graph_key":"graph","query":query,"row_limit":limit},p,op,actor)

    def _comparison_run(self,p,op,actor):
        if self._dataset_snapshot(p["before"]) or self._dataset_snapshot(p["after"]):
            return self._dataset_compare(p,op,actor)
        inputs=[self._snapshot_input(p["before"],"before"),self._snapshot_input(p["after"],"after")]
        params={"before_graph_key":"before","after_graph_key":"after",
                "before_provenance_key":None,"after_provenance_key":None}
        for side in ("before","after"):
            with contextlib.suppress(KeyError):
                item=self._snapshot_input(p[side],side+"-provenance","provenance")
                inputs.append(item);params[side+"_provenance_key"]=item["key"]
        edges=p.get("edge_predicates",[])
        if not isinstance(edges,list): raise ValueError("Impact predicates must be an array of IRIs.")
        for value in edges: iri(value,"Impact predicate")
        params.update(edge_predicates=edges,depth=integer(p.get("depth",2),"Impact depth",0,8),
                      node_limit=integer(p.get("node_limit",100000),"Impact node limit",1,100000))
        return self._new_job("compare",inputs,params,p,op,actor)

    def _decision_save(self,p,op,actor):
        target_kind=p.get("record_kind")
        if target_kind not in ("mapping","snapshot","validation","query","comparison"):
            raise ValueError("Link a decision to an exact engineering record.")
        target=self._revision(target_kind,p["record_id"],p.get("record_revision"))
        disposition=p.get("disposition")
        if disposition not in ("accepted","changes_requested","reviewed"):
            raise ValueError("Choose an explicit review disposition.")
        key=p.get("id") or self._id("decision",op)
        if p.get("id") and "expected_revision" not in p:
            raise ValueError("A decision edit requires its current expected_revision.")
        return self._write("decision",key,{"title":text(p["title"],"Decision title",300),
            "record_kind":target_kind,"record_id":target["id"],"record_revision":target["revision"],
            "record_sha256":target["sha256"],"disposition":disposition,
            "note":text(p["note"],"Review decision",16000)},op,actor,p.get("expected_revision",0))

    def _resume_pinned_job(self, action, p, op, actor):
        # job.json can commit before the application row under interruption or
        # ENOSPC. It is the original selection, even if mutable source heads have
        # since advanced. begin() already checked the original request fingerprint.
        key = self._id("job", op)
        path = self.jobs_root / key / "job.json"
        if not path.exists():
            return None
        raw = private_read(path)
        original = read_json(raw)
        if job_schema(original) not in (JOB_SCHEMA,DATASET_JOB_SCHEMA):
            raise ValueError("The retained job has an unsupported graph or dataset contract.")
        expected = {"job_id":key, "action":action,
                    "operation_id":op, "actor":actor, "workspace_id":self.store.workspace_id,
                    "input_storage":"workspace-content-addressed/1"}
        if not isinstance(original, dict) or any(original.get(k) != v for k,v in expected.items()):
            raise ValueError("The retained native job belongs to another original request or workspace.")
        prior = self.store.history("job", key)
        if prior:
            if prior[0]["payload"].get("job_sha256") != digest(raw):
                raise ValueError("The original retained native job no longer matches its application history.")
            return prior[0]
        return self._new_job(action, original["inputs"], original["parameters"], p, op, actor)

    def _new_job(self,action,inputs,parameters,p,op,actor):
        key=self._id("job",op)
        prior=self.store.history("job",key)
        if prior:
            return prior[0]
        timeout=integer(p.get("timeout_seconds",120),"Native timeout",5,600)
        memory=integer(p.get("memory_mib",1024),"Native memory budget",256,4096)
        title=text(p.get("title",action.title()+" operation"),"Operation title",300)
        schema=DATASET_JOB_SCHEMA if parameters.get("data_model")=="dataset" else JOB_SCHEMA
        original={"schema":schema,"job_id":key,"action":action,"inputs":inputs,"parameters":parameters,
                  "limits":{"timeout_seconds":timeout,"memory_mib":memory},
                  "operation_id":op,"actor":actor,"workspace_id":self.store.workspace_id,"input_storage":"workspace-content-addressed/1"}
        raw=canonical(original)
        directory=private_directory(self.jobs_root/key)
        for item in inputs:
            identifier(item["key"],"Native input key")
            meta,data=self.store.artifact(item["artifact_id"],with_bytes=True)
            if meta["sha256"]!=item["sha256"] or len(data)!=item["bytes"]:
                raise ValueError("The selected native input changed before capture.")
        if (directory/"job.json").exists():
            if private_read(directory/"job.json")!=raw:
                raise ValueError("The original native job belongs to different pinned inputs.")
        else:
            atomic_write(directory/"job.json",raw,replace=False)
        return self._write("job",key,{"title":title,"action":action,"status":"queued","job_sha256":digest(raw),
            "spec":original,"generation":0,"native_result":None,"result_record":None,
            "created_by":actor,"original_operation_id":op},op,actor)

    def _job_continue(self,p,op,actor):
        key=identifier(p["job_id"])
        row=self.store.document("job",key)
        self._adopt_completed(row)
        row=self.store.document("job",key)
        if row["payload"]["status"]=="complete":
            return row
        if row["payload"]["status"] in ("running","queued","cancelling"):
            return row
        directory=self.jobs_root/key
        if self.child_job==key and self.child and self.child.poll() is None:
            raise ValueError("The original native worker is still closing.")
        raw=private_read(directory/"job.json")
        if digest(raw)!=row["payload"]["job_sha256"]:
            raise ValueError("Continue requires the original job and its unchanged pinned inputs.")
        marker=directory/"cancel.json"
        if marker.exists():
            private_read(marker)
            marker.unlink()
        return self._write("job",key,{**row["payload"],"status":"queued","error":None,
            "continued_at":now(),"continued_by":actor},op,actor,row["revision"])

    def _job_cancel(self,p,op,actor):
        key=identifier(p["job_id"])
        row=self.store.document("job",key)
        self._adopt_completed(row)
        row=self.store.document("job",key)
        if row["payload"]["status"] in TERMINAL:
            return row
        directory=self.jobs_root/key
        marker=directory/"cancel.json"
        if not marker.exists():
            atomic_write(marker,canonical({"job_id":key,"operation_id":op,"actor":actor,"at":now()}),replace=False)
        live=self.child_job==key and self.child and self.child.poll() is None
        status="cancelling" if live else "cancelled"
        result=self._write("job",key,{**row["payload"],"status":status,"cancelled_by":actor},op,actor,row["revision"])
        if live:
            self.child.terminate()
        return result

    def _save_job_status(self,row,changes):
        payload={**row["payload"],**changes}
        if canonical(payload)==canonical(row["payload"]):
            return row
        return self.store.save("job",row["id"],payload,actor="local native worker",expected_revision=row["revision"])

    def _adopt_completed(self,row):
        result=verified_result(self.jobs_root/row["id"])
        if result is None:
            return False
        if row["payload"]["status"]=="complete":
            if row["payload"]["native_result"]["job_sha256"]!=result["job_sha256"]:
                raise ValueError("The original adopted native result changed.")
            return True
        outputs=self.jobs_root/row["id"]/"attempts"/str(result["generation"])/"outputs"
        retained=[]
        for item in result["files"]:
            meta=self.store.add_artifact(private_read(outputs/item["path"]),name=Path(item["path"]).name,
                media_type=item["media_type"],role="native-"+item["role"],
                source_reference="Original native job "+row["id"]+" / "+item["path"])
            retained.append({**item,"artifact_id":meta["id"]})
        kind={"inspect":None,"snapshot":"snapshot","validate":"validation","query":"query","compare":"comparison"}[result["action"]]
        record=None
        if kind:
            key=kind+"-"+digest(row["id"].encode())[:28]
            adoption="adopt-"+row["id"]
            record=self._write(kind,key,{"title":row["payload"]["title"],"job_id":row["id"],
                "summary":result["summary"],"warnings":result.get("warnings",[]),"files":retained,
                "inputs":row["payload"]["spec"]["inputs"],"parameters":row["payload"]["spec"]["parameters"],
                "native_generation":result["generation"],"completed_at":result["completed_at"]},
                adoption,"local native worker")
        native={**result,"files":retained}
        self._save_job_status(self.store.document("job",row["id"]),{"status":"complete",
            "generation":result["generation"],"native_result":native,
            "result_record":{"kind":kind,"id":record["id"],"revision":record["revision"]} if record else None,
            "completed_at":result["completed_at"],"error":None})
        return True

    def _stop_owned_child(self):
        if self.child is not None and self.child.poll() is None:
            self.child.terminate()
            try:
                self.child.wait(timeout=3)
            except subprocess.TimeoutExpired:
                self.child.kill()
                self.child.wait(timeout=3)

    def _poll_native(self):
        if self.child is not None:
            row=self.store.document("job",self.child_job)
            timeout=row["payload"]["spec"]["limits"]["timeout_seconds"]
            if self.child.poll() is None and time.monotonic()-self.child_started>timeout+5:
                self._stop_owned_child()
            if self.child.poll() is None:
                return
            code=self.child.returncode
            if self.child_log is not None:
                self.child_log.close()
            self.child=None;self.child_job=None;self.child_log=None;self.child_started=None
            if not self._adopt_completed(row):
                native=load_state(self.jobs_root/row["id"]) or {}
                status=native.get("status")
                if status not in ("failed","cancelled","interrupted"):
                    status="cancelled" if (self.jobs_root/row["id"]/"cancel.json").exists() else "interrupted"
                self._save_job_status(self.store.document("job",row["id"]),{"status":status,
                    "generation":native.get("generation",row["payload"].get("generation",0)),
                    "error":native.get("error") or {"type":"NativeProcessExit","message":"Original worker exited with status "+str(code)+". Continue this job with its retained inputs."},
                    "native_exit_code":code})
        # Reconcile an already completed worker before any possible new dispatch.
        for row in self.store.documents("job"):
            if row["payload"]["status"]=="complete":
                continue
            if self._adopt_completed(row):
                continue
            if row["payload"]["status"] in ("running","cancelling"):
                native=load_state(self.jobs_root/row["id"]) or {}
                self._save_job_status(row,{"status":"cancelled" if (self.jobs_root/row["id"]/"cancel.json").exists() else "interrupted",
                    "generation":native.get("generation",row["payload"].get("generation",0)),
                    "error":native.get("error") or {"type":"OriginalSupervisorClosed","message":"Continue the original job to finish from its pinned inputs."}})

    def advance(self):
        with self.lock:
            self._poll_native()
            if self.stop.is_set() or self.child is not None:
                return
            queued=sorted((r for r in self.store.documents("job") if r["payload"]["status"]=="queued"),key=lambda r:(r["created_at"],r["id"]))
            if not queued:
                return
            row=queued[0]
            directory=self.jobs_root/row["id"]
            raw=private_read(directory/"job.json")
            if digest(raw)!=row["payload"]["job_sha256"]:
                self._save_job_status(row,{"status":"failed","error":{"type":"PinnedJobChanged","message":"The original native job bytes changed."}})
                return
            log_dir=private_directory(directory/"logs")
            self.child_log=os.fdopen(os.open(log_dir/("worker-"+secrets.token_hex(8)+".log"),os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600),"wb",buffering=0)
            self._save_job_status(row,{"status":"running","dispatched_at":now()})
            env={key:value for key,value in os.environ.items() if key in ("PATH","LANG","LC_ALL","PYTHONPATH","SYSTEMROOT")}
            env["PYTHONDONTWRITEBYTECODE"]="1"
            env["PYTHONUNBUFFERED"]="1"
            temporary=private_directory(directory/"temporary")
            env["TMPDIR"]=str(temporary)
            try:
                self.child=subprocess.Popen([sys.executable,"-B","-m","semantic_operator.worker","--operation",str(directory)],
                    cwd=ROOT,env=env,stdin=subprocess.DEVNULL,stdout=self.child_log,stderr=subprocess.STDOUT)
                self.child_job=row["id"];self.child_started=time.monotonic()
            except BaseException:
                self.child_log.close();self.child_log=None
                self._save_job_status(self.store.document("job",row["id"]),{"status":"interrupted",
                    "error":{"type":"NativeDispatchInterrupted","message":"Continue the original pinned native job."}})
                raise

    def _supervise(self):
        while not self.stop.is_set():
            try:
                self.advance()
                self.worker_error=None
            except Exception as exc:
                self.worker_error={"type":type(exc).__name__,"message":str(exc)[:2000]}
            self.wake.wait(0.35)
            self.wake.clear()

    def state(self):
        with self.lock:
            state={"schema":"commons-semantic-operator-state/1","workspace_id":self.store.workspace_id,
                   "workspace_path":str(self.root),"engine_contract":"commons-semantic-native-job/1",
                   "engine_contracts":[JOB_SCHEMA,DATASET_JOB_SCHEMA],
                   "capabilities":{"graph":True,"dataset":True,"dataset_algorithm":"URDNA2015"},
                   "worker_error":getattr(self,"worker_error",None),
                   "records":{kind:self.store.documents(kind) for kind in KINDS},
                   "artifacts":self.store.artifacts(),"operations":self.store.operations(),
                   "native_worker":{"running":self.child is not None and self.child.poll() is None,"job_id":self.child_job}}
            return state

    def close(self):
        if self.closed:
            return
        self.stop.set();self.wake.set()
        if self.thread:
            self.thread.join(timeout=5)
        with self.lock:
            try:
                self._stop_owned_child()
                self._poll_native()
            finally:
                self.closed=True
                if self.child_log is not None:
                    self.child_log.close()
                for child,stream,ready in self.received_hosts.values():
                    if child.poll() is None:
                        child.terminate()
                        try: child.wait(timeout=3)
                        except subprocess.TimeoutExpired:
                            child.kill();child.wait(timeout=3)
                    stream.close()
                self.received_hosts.clear()
                self.store.close()
                fcntl.flock(self._owner,fcntl.LOCK_UN)
                os.close(self._owner)

    def _workspace_files(self):
        self._poll_native()
        if self.child is not None and self.child.poll() is None:
            raise ValueError("Finish or cancel the original native job before exporting a consistent workspace.")
        files=self.store.snapshot()
        for row in self.store.documents("job"):
            directory=self.jobs_root/row["id"]
            for path in directory.rglob("*"):
                if not path.is_file():
                    continue
                name=str(path.relative_to(directory))
                if path.is_symlink():
                    raise ValueError("Native recovery cannot include symbolic links.")
                if name=="native.lock" or name.startswith("temporary/") or any(p.startswith(".write-") for p in Path(name).parts):
                    continue
                files["native-jobs/"+row["id"]+"/"+name]=private_read(path)
        metadata={"schema":"commons-semantic-workspace/1","workspace_id":self.store.workspace_id,
                  "created_at":now(),"contains_private_key":False,"scope":"Complete original source and engineering history"}
        return files,metadata

    def _handoff_export(self,p,op,actor):
        files,metadata=self._workspace_files()
        body,manifest=pack_files(files,metadata)
        name="Semantic-Workspace-"+self.store.workspace_id[:8]+".zip"
        artifact=self.store.add_artifact(body,name=name,media_type="application/zip",role="workspace-handoff",
            source_reference="Complete original semantic workspace "+self.store.workspace_id,include_in_backup=False)
        return {"artifact":artifact,"workspace_id":self.store.workspace_id,
                "files":len(manifest["files"]),"uncompressed_bytes":sum(v["bytes"] for v in manifest["files"]),
                "scope":metadata["scope"],"encrypted":False}

    def _intake_transfer(self,p,*,encrypted=False):
        if p.get("artifact_id"):
            meta,data=self.store.artifact(p["artifact_id"],with_bytes=True)
            return meta,data
        body=decoded(p["data_base64"])
        meta=self.store.add_artifact(body,name=p.get("name","Semantic-Workspace.csw" if encrypted else "Semantic-Workspace.zip"),
            media_type="application/octet-stream" if encrypted else "application/zip",
            role="received-recovery" if encrypted else "received-handoff",
            source_reference=text(p.get("source_reference","Local operator's complete workspace transfer"),"Transfer source"),
            include_in_backup=not encrypted)
        return meta,body

    def _handoff_receive(self,p,op,actor):
        from .portable import receive_workspace,validate_workspace
        artifact,body=self._intake_transfer(p)
        for row in self.store.documents("receiving"):
            if row["payload"].get("archive_sha256")==artifact["sha256"]:
                return row
        files,manifest=unpack_files(body)
        summary=validate_workspace(files,manifest)
        key=self._id("receiving",op)
        destination=self.receiving_root/key
        current={(kind,row["id"]):row for kind in KINDS for row in self.store.documents(kind)}
        conflicts=[{"kind":head["kind"],"id":head["id"],
                    "current_revision":current[(head["kind"],head["id"])]["revision"],
                    "received_revision":head["revision"],"current_sha256":current[(head["kind"],head["id"])]["sha256"],
                    "received_sha256":head["sha256"]} for head in summary["heads"]
                   if (head["kind"],head["id"]) in current and current[(head["kind"],head["id"])]["sha256"]!=head["sha256"]]
        receive_workspace(files,manifest,destination,archive_sha256=artifact["sha256"],operation_id=op)
        return self._write("receiving",key,{"title":text(p.get("title","Received semantic workspace"),"Receiving title",300),
            "artifact_id":artifact["id"],"archive_sha256":artifact["sha256"],"source_workspace_id":summary["workspace_id"],
            "workspace_path":str(destination),"local_workspace_root":str(self.root),"location_status":"local",
            "receiving_operation_id":op,"summary":summary,"conflicts":conflicts,
            "resolution":"Independent received workspace; both complete branches and original IDs are retained.",
            "received_at":now()},op,actor)

    def _recovery_export(self,p,op,actor):
        files,metadata=self._workspace_files()
        body,manifest=pack_files(files,metadata)
        encrypted=encrypt_recovery(body,p["passphrase"])
        artifact=self.store.add_artifact(encrypted,name="Semantic-Recovery-"+self.store.workspace_id[:8]+".csw",
            media_type="application/octet-stream",role="encrypted-recovery",
            source_reference="Encrypted complete semantic workspace "+self.store.workspace_id,include_in_backup=False)
        return {"artifact":artifact,"workspace_id":self.store.workspace_id,"files":len(manifest["files"]),
                "encrypted":True,"algorithm":"AES-256-GCM / PBKDF2-HMAC-SHA256 / 600000 iterations",
                "original_ids_retained":True,"local_key_excluded":True}

    def _recovery_restore(self,p,op,actor):
        from .portable import receive_workspace
        artifact,body=self._intake_transfer(p,encrypted=True)
        raw=decrypt_recovery(body,p["passphrase"])
        files,manifest=unpack_files(raw)
        destination=Path(text(p["destination"],"New private recovery directory",4000)).expanduser().absolute()
        if destination==self.root or self.root in destination.parents:
            raise ValueError("Choose a new recovery workspace outside this original workspace.")
        summary=receive_workspace(files,manifest,destination,archive_sha256=artifact["sha256"],operation_id=op)
        return self._write("recovery",self._id("recovery",op),{"title":"Restored original semantic workspace",
            "artifact_id":artifact["id"],"archive_sha256":artifact["sha256"],"workspace_path":str(destination),
            "local_workspace_root":str(self.root),"location_status":"local","restoring_operation_id":op,
            "source_workspace_id":summary["workspace_id"],"summary":summary,"restored_at":now(),
            "original_ids_retained":True,"fresh_local_key_on_open":True},op,actor)

    def _workspace_open(self,p,op,actor):
        kind=p.get("kind")
        if kind not in ("receiving","recovery"):
            raise ValueError("Choose one of this operator's received or recovered workspaces.")
        row=self.store.document(kind,p["id"])
        value=row["payload"]
        if kind=="receiving":
            # Always use this receiver's own destination. Never follow a path
            # serialized by another host, even when that old path still exists.
            from .portable import receive_workspace
            meta,body=self.store.artifact(value["artifact_id"],with_bytes=True)
            if meta["sha256"]!=value["archive_sha256"]:
                raise ValueError("The retained receiving archive changed.")
            files,manifest=unpack_files(body)
            target=self.receiving_root/identifier(row["id"])
            origin=value.get("receiving_operation_id") or self.store.history(kind,row["id"])[0]["payload"]["_operation_id"]
            receive_workspace(files,manifest,target,archive_sha256=meta["sha256"],operation_id=origin)
            if value.get("workspace_path")!=str(target) or value.get("local_workspace_root")!=str(self.root):
                row=self._write(kind,row["id"],{**value,"workspace_path":str(target),
                    "local_workspace_root":str(self.root),"location_status":"local",
                    "receiving_operation_id":origin,"located_at":now()},op,actor,row["revision"])
        else:
            if value.get("location_status")!="local" or value.get("local_workspace_root")!=str(self.root):
                raise ValueError("This transferred recovery record needs its original encrypted archive. Restore that archive into a new local directory.")
            target=private_directory(value["workspace_path"],create=False)
            origin=read_json(private_read(target/"RECEIVED.json"))
            if (origin.get("archive_sha256")!=value["archive_sha256"]
                    or origin.get("workspace_id")!=value["source_workspace_id"]
                    or origin.get("operation_id")!=value["restoring_operation_id"]
                    or origin.get("destination")!=str(target)):
                raise ValueError("The original local recovery destination no longer matches this record.")
        target=private_directory(target,create=False)
        existing=self.received_hosts.get(str(target))
        if existing and existing[0].poll() is None:
            return existing[2]
        log_dir=private_directory(self.root/"received-hosts")
        ready_path=log_dir/(op+".ready.json")
        log=os.fdopen(os.open(log_dir/(op+".log"),os.O_WRONLY|os.O_CREAT|os.O_APPEND|os.O_NOFOLLOW,0o600),"ab",buffering=0)
        env={key:value for key,value in os.environ.items() if key in ("PATH","LANG","LC_ALL","PYTHONPATH","SYSTEMROOT")}
        env["PYTHONDONTWRITEBYTECODE"]="1"
        child=subprocess.Popen([sys.executable,"-B",str(ROOT/"run.py"),"serve","--workspace",str(target),
            "--ready-file",str(ready_path),"--parent-pid",str(os.getpid())],
            cwd=ROOT,env=env,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT)
        try:
            deadline=time.monotonic()+15
            while time.monotonic()<deadline:
                if child.poll() is not None:
                    raise ValueError("The received operator could not open; its original workspace remains intact.")
                if ready_path.exists():
                    ready=read_json(private_read(ready_path))
                    if ready.get("pid")==child.pid and ready.get("workspace_id")==row["payload"]["source_workspace_id"]:
                        self.received_hosts[str(target)]=(child,log,ready)
                        return ready
                time.sleep(0.05)
            raise ValueError("The received operator has not opened within 15 seconds; its original workspace remains intact.")
        except BaseException:
            if child.poll() is None:
                child.terminate()
                try: child.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    child.kill();child.wait(timeout=3)
            log.close()
            raise

"""Dataset operations composed with the original semantic application and Store.

This module freezes selections into native jobs. Parsing, canonicalization and
calculation belong to dataset_engine; every artifact and revision uses the
original application machinery.
"""
from __future__ import annotations
import re
from .security import canonical, read_json

DATASET_FORMATS = {"turtle", "nt", "xml", "json-ld", "trig", "nquads"}
DATASET_JOB_SCHEMA = "commons-semantic-native-job/2"


def graph_selector(value, *, named_only=False, destination=False):
    if not isinstance(value, dict):
        raise ValueError("Select an explicit default or named graph.")
    kind = value.get("type")
    if kind == "default" and set(value) == {"type"} and not named_only:
        return {"type": "default"}
    if kind not in (("uri",) if destination else ("uri", "bnode")) or set(value) != {"type", "value"}:
        raise ValueError("A graph selector must be default, an absolute IRI, or its retained blank-node identifier.")
    name = value.get("value")
    if not isinstance(name, str) or not name or len(name) > 8000 or "\0" in name:
        raise ValueError("Keep the complete retained graph identifier.")
    if kind == "uri" and (not re.match(r"^[A-Za-z][A-Za-z0-9+.-]*:", name) or
                         any(c.isspace() or c in '<>"{}|^\x60\\' for c in name)):
        raise ValueError("A named graph destination must be an absolute RDF IRI.")
    if kind == "bnode" and (name.startswith("_:") or any(c.isspace() for c in name)):
        raise ValueError("Use the retained graph catalogue blank-node value without the _: prefix.")
    return {"type": kind, "value": name}


def graph_selection(value, *, named_only=False, allow_empty=False):
    if value == "all":
        return "all"
    if not isinstance(value, list) or (not value and not allow_empty):
        raise ValueError("Choose all graphs or a nonempty explicit graph selection.")
    result = [graph_selector(v, named_only=named_only) for v in value]
    if len({canonical(v) for v in result}) != len(result):
        raise ValueError("A graph selection must not repeat an identifier.")
    return result


class DatasetOperations:
    def _dataset_snapshot(self, ref):
        row = self._revision("snapshot", ref["id"], ref.get("revision"))
        return row["payload"].get("parameters", {}).get("data_model") == "dataset"

    def _dataset_inputs(self, ref, prefix=""):
        key = (prefix + "-") if prefix else ""
        result = []
        for role, name, fmt in (("dataset", "dataset", "nquads"),
                                ("graph_catalog", "catalog", "json")):
            item = self._snapshot_input(ref, key + name, role)
            item.update(format=fmt, role=role)
            result.append(item)
        return result

    def _source_catalog_input(self, ref, key):
        row = self._revision("source", ref["id"], ref.get("revision"))
        catalogue = row["payload"].get("dataset_catalog")
        if not catalogue:
            return None
        meta = self.store.artifact(catalogue["id"])
        if meta["sha256"] != catalogue["sha256"] or meta["bytes"] != catalogue["bytes"]:
            raise ValueError("The retained source graph catalogue identity changed.")
        return {"key": key, "artifact_id": meta["id"], "sha256": meta["sha256"],
                "bytes": meta["bytes"], "format": "json", "role": "graph_catalog",
                "source_id": row["id"], "revision": row["revision"],
                "title": catalogue["name"], "source_reference": row["payload"]["source_reference"]}

    def _dataset_inspect(self, p, op, actor):
        source = self._source_input(p["source"], "selected")
        if source["format"] not in DATASET_FORMATS:
            raise ValueError("Dataset inspection requires an original RDF source.")
        inputs = [source]
        catalog = self._source_catalog_input(p["source"], "selected-catalog")
        params = {"data_model": "dataset", "input_key": "selected", "source_catalogs": {}}
        if catalog:
            inputs.append(catalog)
            params["source_catalogs"]["selected"] = catalog["key"]
        return self._new_job("inspect", inputs, params, p, op, actor)

    def _dataset_build(self, p, op, actor):
        source_refs, mapping_refs = p.get("sources", []), p.get("mappings", [])
        if not isinstance(source_refs, list) or not isinstance(mapping_refs, list):
            raise ValueError("Select exact source and mapping revisions.")
        source_graphs = p.get("source_graphs", {})
        mapping_graphs = p.get("mapping_graphs", {})
        if not isinstance(source_graphs, dict) or not isinstance(mapping_graphs, dict):
            raise ValueError("Keep graph choices keyed by their original record ID and revision.")
        inputs, data_keys, mappings, selections, catalogs = [], [], [], {}, {}
        seen_sources, seen_mappings = set(), set()
        for index, ref in enumerate(source_refs):
            item = self._source_input(ref, "data-" + str(index))
            if item["format"] not in DATASET_FORMATS or item["role"] != "data":
                raise ValueError("Dataset snapshots use original RDF data sources.")
            identity = item["source_id"] + "@" + str(item["revision"])
            if identity in seen_sources:
                raise ValueError("Select an original source revision only once.")
            seen_sources.add(identity)
            inputs.append(item)
            data_keys.append(item["key"])
            catalog = self._source_catalog_input(ref, item["key"] + "-catalog")
            if catalog:
                inputs.append(catalog)
                catalogs[item["key"]] = catalog["key"]
            selections[item["key"]] = graph_selection(source_graphs.get(identity, "all"))
        for index, ref in enumerate(mapping_refs):
            row = self._revision("mapping", ref["id"], ref.get("revision"))
            identity = row["id"] + "@" + str(row["revision"])
            if identity in seen_mappings:
                raise ValueError("Select a mapping revision only once.")
            seen_mappings.add(identity)
            item = self._source_input(row["payload"]["source"], "table-" + str(index))
            if item["sha256"] != row["payload"]["source"]["sha256"]:
                raise ValueError("The mapping's original table identity changed.")
            destination = graph_selector(mapping_graphs.get(identity, {"type": "default"}), destination=True)
            inputs.append(item)
            mappings.append({**row["payload"]["definition"], "mapping_id": row["id"],
                             "revision": row["revision"], "input_key": item["key"],
                             "destination_graph": destination})
        if set(source_graphs) - seen_sources or set(mapping_graphs) - seen_mappings:
            raise ValueError("A graph choice refers to a source or mapping outside this snapshot.")
        if not inputs:
            raise ValueError("Choose at least one RDF source or CSV mapping.")
        return self._new_job("snapshot", inputs,
            {"data_model": "dataset", "data_keys": data_keys, "source_graphs": selections,
             "source_catalogs": catalogs, "mappings": mappings},
            p, op, actor)

    def _dataset_validate(self, p, op, actor):
        inputs = self._dataset_inputs(p["snapshot"])
        shapes, ontologies = [], []
        for role, refs, keys in (("shapes", p.get("shapes", []), shapes),
                                 ("ontology", p.get("ontologies", []), ontologies)):
            if not isinstance(refs, list):
                raise ValueError("Select exact shape and ontology revisions.")
            for index, ref in enumerate(refs):
                item = self._source_input(ref, role + "-" + str(index))
                if item["role"] != role or item["format"] not in ("turtle", "nt", "xml", "json-ld"):
                    raise ValueError("Validation shapes and ontologies must be explicit RDF graph sources.")
                inputs.append(item)
                keys.append(item["key"])
        if not shapes:
            raise ValueError("Select the original SHACL shapes for this validation.")
        inference = p.get("inference", "none")
        if inference not in ("none", "rdfs", "owlrl", "both"):
            raise ValueError("Choose an explicit inference mode.")
        for name in ("allow_infos", "allow_warnings"):
            if name in p and type(p[name]) is not bool:
                raise ValueError(name + " must be true or false.")
        scope = p.get("validation_scope")
        if not isinstance(scope, dict) or set(scope) != {"mode", "graphs"} or scope["mode"] not in ("per_graph", "union"):
            raise ValueError("Choose per-graph validation or an explicit selected union and retain its graph scope.")
        scope = {"mode": scope["mode"], "graphs": graph_selection(scope["graphs"])}
        return self._new_job("validate", inputs,
            {"data_model": "dataset", "dataset_key": "dataset", "catalog_key": "catalog",
             "shape_keys": shapes, "ontology_keys": ontologies, "inference": inference,
             "allow_infos": p.get("allow_infos", False), "allow_warnings": p.get("allow_warnings", False),
             "validation_scope": scope}, p, op, actor)

    def _dataset_query(self, p, op, actor):
        from .application import text, integer
        scope = p.get("query_scope")
        if (not isinstance(scope, dict) or set(scope) != {"default_graph", "named_graphs"} or
                scope["default_graph"] not in ("default", "union")):
            raise ValueError("Choose the SPARQL default graph and available named graphs explicitly.")
        scope = {"default_graph": scope["default_graph"],
                 "named_graphs": graph_selection(scope["named_graphs"], named_only=True, allow_empty=True)}
        return self._new_job("query", self._dataset_inputs(p["snapshot"]),
            {"data_model": "dataset", "dataset_key": "dataset", "catalog_key": "catalog",
             "query": text(p.get("query"), "SPARQL query", 100000),
             "row_limit": integer(p.get("row_limit", 10000), "Query row limit", 1, 100000),
             "query_scope": scope}, p, op, actor)

    def _dataset_compare(self, p, op, actor):
        from .application import iri, integer
        if not self._dataset_snapshot(p["before"]) or not self._dataset_snapshot(p["after"]):
            raise ValueError("Choose two dataset snapshots; graph and dataset snapshots have different identities.")
        inputs = self._dataset_inputs(p["before"], "before") + self._dataset_inputs(p["after"], "after")
        params = {"data_model": "dataset", "before_dataset_key": "before-dataset",
                  "before_catalog_key": "before-catalog", "after_dataset_key": "after-dataset",
                  "after_catalog_key": "after-catalog"}
        for side in ("before", "after"):
            item = self._snapshot_input(p[side], side + "-provenance", "provenance")
            inputs.append(item)
            params[side + "_provenance_key"] = item["key"]
        edges = p.get("edge_predicates", [])
        if not isinstance(edges, list):
            raise ValueError("Impact predicates must be an array of absolute IRIs.")
        for edge in edges:
            iri(edge, "Impact predicate")
        scope = p.get("comparison_scope")
        if (not isinstance(scope, dict) or set(scope) != {"graphs", "impact_mode"} or
                scope["impact_mode"] not in ("within_graph", "union")):
            raise ValueError("Choose a graph scope and whether impact traverses within graphs or across their union.")
        params.update(comparison_scope={"graphs": graph_selection(scope["graphs"]), "impact_mode": scope["impact_mode"]},
                      edge_predicates=edges, depth=integer(p.get("depth", 2), "Impact depth", 0, 8),
                      node_limit=integer(p.get("node_limit", 100000), "Impact node limit", 1, 100000))
        return self._new_job("compare", inputs, params, p, op, actor)

"""Whole-dataset semantics over the original retained-input RDF engine.

RDFLib 7.6.0 parses and queries; PyLD 3.3.0 supplies URDNA2015.  Empty graph
inventory is retained separately and bound into the dataset identity.  This
module never opens a remote source, creates a workspace, or edits a source.
"""
from __future__ import annotations

import copy
import hashlib
import importlib.metadata
import io
import json
import re
from collections import Counter, defaultdict, deque
from pathlib import Path

from rdflib import BNode, ConjunctiveGraph, Dataset, Graph, Literal, URIRef
from rdflib.namespace import RDF, XSD
from rdflib.parser import InputSource, PythonInputSource
from rdflib.plugins.parsers.jsonld import JsonLDParser
from rdflib.plugins.parsers.nquads import NQuadsParser
from rdflib.plugins.parsers.trig import TrigSinkParser
from pyld.canon import URDNA2015
from pyld.nquads import serialize_nquad

from . import rdf_engine as native

SCHEMA = "commons-semantic-native-engine-result/2"
JOB_SCHEMA = "commons-semantic-native-job/2"
CATALOG_SCHEMA = "commons-semantic-graph-catalog/1"
PROVENANCE_SCHEMA = "commons-semantic-dataset-provenance/1"
CANONICALIZATION = {"algorithm": "URDNA2015", "implementation": "PyLD", "version": "3.3.0",
                    "profile": "commons-semantic-dataset-inventory/1"}
DATASET_FORMATS = set(native.RDF_FORMATS) | {"trig", "nquads"}
ALLOWED_FORMATS = DATASET_FORMATS | {"csv", "json"}
INTERNAL_DEFAULT = URIRef("urn:commons:semantic:dataset-default")
RDFLIB_DEFAULT = URIRef("urn:x-rdflib:default")
RESERVED_GRAPH_NAMES = {INTERNAL_DEFAULT, RDFLIB_DEFAULT}
_SOURCE_BYTES = Path(__file__).read_bytes()
ENGINE_SOURCE = {
    "path": "semantic_operator/dataset_engine.py",
    "sha256": hashlib.sha256(_SOURCE_BYTES).hexdigest(),
    "git_blob_sha1": hashlib.sha1(
        b"blob " + str(len(_SOURCE_BYTES)).encode("ascii") + b"\0" + _SOURCE_BYTES).hexdigest(),
    "bytes": len(_SOURCE_BYTES), "captured": "module-load",
}
SemanticError, require = native.SemanticError, native.require
sha, json_bytes = native.sha, native.json_bytes


def _stable(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def graph_selector(value):
    return {"type": "default"} if value is None else native.term(value)


def graph_key(value):
    return _stable(graph_selector(value))


def selector_term(value, *, named_only=False):
    require(isinstance(value, dict), "A graph selector must be an object")
    kind = value.get("type")
    if kind == "default":
        require(set(value) == {"type"} and not named_only, "Default graph is not a named graph selector")
        return None
    require(kind in {"uri", "bnode"} and set(value) == {"type", "value"},
            "A graph selector must be default, uri, or bnode")
    raw = value.get("value")
    require(isinstance(raw, str) and raw, "A graph selector requires a value")
    if kind == "uri":
        result = native.absolute_iri(raw, "Named graph IRI")
        require(result not in RESERVED_GRAPH_NAMES,
                "Named graph collides with a reserved native default-graph identifier: " + raw)
        return result
    require(not raw.startswith("_:") and not re.search(r"[\s<>{}\"\\]", raw),
            "Blank graph selectors use the retained label without '_:'")
    return BNode(raw)


def _term(value):
    if isinstance(value, URIRef):
        return native.absolute_iri(str(value), "RDF IRI")
    if isinstance(value, BNode):
        require(bool(str(value)), "Blank RDF identifiers must be nonempty")
        return value
    if isinstance(value, Literal):
        # RDF 1.1 simple literals denote xsd:string. Language tags compare
        # case-insensitively; source spelling remains in the retained input.
        if value.language:
            return Literal(str(value), lang=value.language.lower(), normalize=False)
        datatype = native.absolute_iri(str(value.datatype), "Literal datatype") if value.datatype else XSD.string
        return Literal(str(value), datatype=datatype, normalize=False)
    raise SemanticError("Only RDF 1.1 terms are supported in retained datasets")


def normalized_quad(quad):
    require(isinstance(quad, (tuple, list)) and len(quad) == 4, "An RDF quad has four terms")
    s, p, o, g = quad
    require(isinstance(s, (URIRef, BNode)) and isinstance(p, URIRef)
            and isinstance(o, (URIRef, BNode, Literal))
            and (g is None or isinstance(g, (URIRef, BNode))),
            "Generalized RDF and quoted triples are not supported")
    require(g not in RESERVED_GRAPH_NAMES, "Named graph collides with a reserved native identifier")
    return _term(s), _term(p), _term(o), _term(g) if g is not None else None


class DatasetValue:
    def __init__(self, quads=(), graphs=None):
        self.quads = {normalized_quad(q) for q in quads}
        self.graphs = {None} | set(graphs or ()) | {q[3] for q in self.quads}
        for graph in self.graphs:
            if graph is not None:
                require(isinstance(graph, (URIRef, BNode)) and graph not in RESERVED_GRAPH_NAMES,
                        "A retained named graph must have a nonreserved RDF IRI or blank-node name")
                _term(graph)
        self.quad_origins = defaultdict(list)
        self.graph_origins = defaultdict(list)

    def ordinary_graph(self, graphs):
        selected = set(graphs)
        graph = Graph()
        for s, p, o, g in self.quads:
            if g in selected:
                graph.add((s, p, o))
        return graph


def _pyld_term(value):
    if isinstance(value, URIRef):
        return {"type": "IRI", "value": str(value)}
    if isinstance(value, BNode):
        return {"type": "blank node", "value": "_:" + str(value)}
    result = {"type": "literal", "value": str(value),
              "datatype": str(RDF.langString if value.language else (value.datatype or XSD.string))}
    if value.language:
        result["language"] = value.language.lower()
    return result


def _pyld_quad(quad):
    s, p, o, g = quad
    result = {"subject": _pyld_term(s), "predicate": _pyld_term(p), "object": _pyld_term(o)}
    if g is not None:
        result["name"] = _pyld_term(g)
    return result


def nq_line(quad):
    return serialize_nquad(_pyld_quad(quad))


def quad_value(quad):
    return {**native.triple_value(quad[:3]), "graph": graph_selector(quad[3])}


def _replace_quad(quad, mapping):
    return tuple(mapping.get(value, value) if isinstance(value, BNode) else value for value in quad)


def _dedup_origins(values):
    return [value for _, value in sorted({_stable(value): value for value in values}.items())]


def _inventory_markers(value):
    """Represent only otherwise-unrepresented blank graph membership in labeling."""
    counts = Counter(q[3] for q in value.quads)
    empty_names = [g for g in value.graphs if isinstance(g, BNode) and counts[g] == 0]
    if not empty_names:
        return set()
    iris = {str(v) for q in value.quads for v in q if isinstance(v, URIRef)}
    iris.update(str(g) for g in value.graphs if isinstance(g, URIRef))
    iris.update(str(q[2].datatype) for q in value.quads
                if isinstance(q[2], Literal) and q[2].datatype is not None)
    index = 0
    while True:
        base = "urn:commons:semantic:empty-graph-inventory:" + str(index)
        predicate, obj, graph = (URIRef(base + suffix) for suffix in (":member", ":Graph", ":graph"))
        if not {str(predicate), str(obj), str(graph)} & iris:
            break
        index += 1
    return {(name, predicate, obj, graph) for name in empty_names}


def canonical_dataset(value):
    """URDNA2015 with the explicitly recorded complete-inventory labeling profile.

    Empty blank graph membership must distinguish otherwise quad-symmetric
    nodes. Collision-free auxiliary statements enter only the native labeling
    problem; they are removed before serializing any retained RDF artifact.
    """
    markers = _inventory_markers(value)
    labeling_quads = value.quads | markers
    blank_nodes = {v for q in labeling_quads for v in q if isinstance(v, BNode)}
    blank_nodes.update(g for g in value.graphs if isinstance(g, BNode))
    # PyLD's pinned implementation treats its own output prefix specially.
    # Scope every supplied label away from that prefix before calling it.
    temporary = {old: BNode("input" + str(i)) for i, old in enumerate(sorted(blank_nodes, key=str))}
    dataset = defaultdict(list)
    for quad in sorted(labeling_quads, key=nq_line):
        s, p, o, g = _replace_quad(quad, temporary)
        name = "@default" if g is None else ("_:" + str(g) if isinstance(g, BNode) else str(g))
        dataset[name].append({"subject": _pyld_term(s), "predicate": _pyld_term(p), "object": _pyld_term(o)})
    algorithm = URDNA2015()
    output = algorithm.main(copy.deepcopy(dict(dataset)), {"format": "application/n-quads"})
    mapping = {}
    for old, interim in temporary.items():
        key = "_:" + str(interim)
        require(algorithm.canonical_issuer.has_id(key),
                "A graph-inventory blank node was omitted from the native labeling problem")
        mapping[old] = BNode(algorithm.canonical_issuer.get_id(key)[2:])
    check_bytes = "".join(sorted(nq_line(_replace_quad(q, mapping)) for q in labeling_quads)).encode("utf-8")
    require(check_bytes == output.encode("utf-8"), "Native dataset canonicalization map/output disagreed")
    canonical = DatasetValue((_replace_quad(q, mapping) for q in value.quads),
                             [mapping.get(g, g) for g in value.graphs])
    canonical_bytes = "".join(sorted(nq_line(q) for q in canonical.quads)).encode("utf-8")
    for q, origins in value.quad_origins.items():
        canonical.quad_origins[_replace_quad(q, mapping)].extend(origins)
    for g, origins in value.graph_origins.items():
        canonical.graph_origins[mapping.get(g, g)].extend(origins)
    return canonical, mapping, canonical_bytes


def dataset_identity(value, canonical_bytes):
    inventory = [graph_selector(g) for g in sorted(value.graphs, key=graph_key)]
    return sha(b"commons-semantic-dataset-identity/1\n" + canonical_bytes + b"\0" + json_bytes(inventory))


def graph_catalog(value, canonical_bytes):
    counts = Counter(q[3] for q in value.quads)
    return {
        "schema": CATALOG_SCHEMA, "data_model": "dataset",
        "canonicalization": dict(CANONICALIZATION),
        "dataset_sha256": dataset_identity(value, canonical_bytes),
        "nquads_sha256": sha(canonical_bytes), "quad_count": len(value.quads),
        "graphs": [{"graph": graph_selector(g), "quad_count": counts[g], "empty": counts[g] == 0,
                    "origins": _dedup_origins(value.graph_origins[g])}
                   for g in sorted(value.graphs, key=graph_key)],
    }


def _trig_bytes(value):
    blocks = []
    grouped = defaultdict(list)
    for quad in value.quads:
        grouped[quad[3]].append(quad[:3])
    for g in sorted(value.graphs, key=graph_key):
        title = "" if g is None else (("_:" + str(g)) if isinstance(g, BNode) else "<" + str(g) + ">")
        triples = sorted(grouped[g], key=native.nt_line)
        # Full native N-Triples statements are a valid TriG body. Using them
        # avoids Turtle numeric shorthand rewriting a retained literal lexeme.
        blocks.append(title + " {\n" + "".join("  " + native.nt_line(t) for t in triples) + "}\n")
    return ("\n".join(blocks)).encode("utf-8")


class _TrackedSink(native._LexicalSink):
    named_candidate = None

    def newGraph(self, identifier):
        if self.named_candidate is not None:
            require(identifier not in RESERVED_GRAPH_NAMES,
                    "An explicit named graph uses a reserved native default-graph identifier")
        graph = super().newGraph(identifier)
        self.graph.store.add_graph(graph)
        return graph


class _LexicalTrigParser(TrigSinkParser, native._LexicalTurtleParser):
    def graph(self, text, start):
        self._store.named_candidate = None
        return super().graph(text, start)

    def labelOrSubject(self, text, start, result):
        previous = len(result)
        end = super().labelOrSubject(text, start, result)
        self._store.named_candidate = result[-1] if end >= 0 and len(result) > previous else None
        return end


class _LocalJSONDataset(Dataset):
    def __init__(self):
        self.observe_names = False
        super().__init__(default_union=False)
        self.observe_names = True

    def get_context(self, identifier, *args, **kwargs):
        if self.observe_names:
            require(identifier not in RESERVED_GRAPH_NAMES,
                    "JSON-LD named graph uses a reserved native default-graph identifier")
        graph = super().get_context(identifier, *args, **kwargs)
        if self.observe_names:
            self.store.add_graph(graph)
        return graph


class _ObservedNQuadsParser(NQuadsParser):
    def parseline(self, bnode_context=None):
        if not getattr(self, "_names_observed", False):
            original = self.sink.get_context
            def named(identifier, *args, **kwargs):
                require(identifier not in RESERVED_GRAPH_NAMES,
                        "N-Quads named graph uses a reserved native default-graph identifier")
                graph = original(identifier, *args, **kwargs)
                self.sink.store.add_graph(graph)
                return graph
            self.sink.get_context = named
            self._names_observed = True
        return super().parseline(bnode_context)


def _collect_store(store, default_identifier, labels=None):
    labels = labels or {}
    graphs = {None}
    quads = set()
    # Store contexts expose registered empty graphs without Dataset.graphs()
    # inventing an extra sentinel context when its default graph was rebound.
    for context in store.contexts():
        identifier = context.identifier
        name = None if identifier == default_identifier else labels.get(identifier, identifier)
        if name is not None:
            require(name not in RESERVED_GRAPH_NAMES, "Ambiguous native default/named graph identity")
        graphs.add(name)
        for s, p, o in context:
            quads.add((labels.get(s, s), p, labels.get(o, o), name))
    return DatasetValue(quads, graphs)


def parse_dataset(raw, fmt, base):
    require(fmt in DATASET_FORMATS, "A declared RDF dataset or graph format is required")
    if fmt in native.RDF_FORMATS - {"json-ld"}:
        graph = native.parse_graph(raw, fmt, base)
        return DatasetValue((s, p, o, None) for s, p, o in graph)
    if fmt == "trig":
        root = Graph(identifier=INTERNAL_DEFAULT)
        joined = ConjunctiveGraph(store=root.store, identifier=INTERNAL_DEFAULT)
        joined.default_context = root
        parser = _LexicalTrigParser(_TrackedSink(joined), baseURI=base, turtle=True)
        parser.loadStream(io.BytesIO(raw))
        return _collect_store(root.store, INTERNAL_DEFAULT)
    if fmt == "nquads":
        root = Graph(identifier=INTERNAL_DEFAULT)
        source = InputSource(base)
        source.setPublicId(base)
        source.setByteStream(io.BytesIO(raw))
        labels = {}
        parsed = _ObservedNQuadsParser().parse(source, root, bnode_context=labels)
        original_labels = {node: BNode(label) for label, node in labels.items()}
        return _collect_store(parsed.store, INTERNAL_DEFAULT, original_labels)
    document = native.load_json(raw)
    native.no_remote_contexts(document)
    parsed = _LocalJSONDataset()
    JsonLDParser().parse(PythonInputSource(document, system_id=base), parsed,
                         base=base, version=1.1, generalized_rdf=False, skolemize=False)
    return _collect_store(parsed.store, parsed.default_graph.identifier)


def attach_catalog(raw_value, raw_nquads, catalogue):
    require(isinstance(catalogue, dict) and catalogue.get("schema") == CATALOG_SCHEMA
            and catalogue.get("data_model") == "dataset", "Unknown companion graph catalogue")
    require(catalogue.get("canonicalization") == CANONICALIZATION,
            "Companion catalogue uses a different canonicalization contract")
    require(catalogue.get("nquads_sha256") == sha(raw_nquads),
            "Companion catalogue does not bind these exact N-Quads bytes")
    require(type(catalogue.get("quad_count")) is int and catalogue["quad_count"] == len(raw_value.quads),
            "Companion catalogue quad count differs from the parsed source")
    rows = catalogue.get("graphs")
    require(isinstance(rows, list) and rows, "Complete companion graph inventory is required")
    names, counts = [], Counter(q[3] for q in raw_value.quads)
    origins = {}
    for row in rows:
        require(isinstance(row, dict), "Invalid companion graph row")
        name = selector_term(row.get("graph"))
        require(name not in names, "Duplicate companion graph identity")
        require(type(row.get("quad_count")) is int and row["quad_count"] == counts[name],
                "Companion graph count differs from its source quads")
        require(type(row.get("empty")) is bool and row["empty"] == (counts[name] == 0),
                "Companion graph empty flag disagrees with its count")
        require(isinstance(row.get("origins", []), list)
                and all(isinstance(o, dict) for o in row.get("origins", [])),
                "Companion graph origins must be retained metadata objects")
        names.append(name)
        origins[name] = row.get("origins", [])
    require(None in names and raw_value.graphs <= set(names),
            "Companion catalogue omits the default graph or represented graph membership")
    raw_value.graphs = set(names)
    for name in names:
        raw_value.graph_origins[name] = origins[name]
    canonical, _, canonical_bytes = canonical_dataset(raw_value)
    require(canonical_bytes == raw_nquads, "Companion requires canonical N-Quads in its recorded byte form")
    canonical_names = [graph_selector(g) for g in sorted(canonical.graphs, key=graph_key)]
    require([r["graph"] for r in rows] == canonical_names,
            "Companion graph inventory is not in its exact canonical identity/order")
    require(catalogue.get("dataset_sha256") == dataset_identity(canonical, canonical_bytes),
            "Companion dataset digest does not bind the complete graph inventory")
    return canonical, canonical_bytes


class Context(native.Context):
    def __init__(self, job, input_paths, output_dir):
        require(isinstance(job, dict) and job.get("schema") == JOB_SCHEMA, "Unknown dataset native job schema")
        require(isinstance(job.get("job_id"), str) and job["job_id"], "A stable job_id is required")
        require(isinstance(job.get("inputs"), list), "Declared inputs are required")
        self.job, self.parameters = job, job.get("parameters") or {}
        require(isinstance(self.parameters, dict) and self.parameters.get("data_model") == "dataset",
                "Dataset jobs require an explicit data_model='dataset'")
        self.inputs, self.raw, self.graphs, self.datasets = {}, {}, {}, {}
        self.files, self.warnings = [], []
        self.output = Path(output_dir)
        self.output.mkdir(parents=True, exist_ok=True)
        require(not any(self.output.iterdir()), "The owned native output directory must be empty")
        for entry in job["inputs"]:
            require(isinstance(entry, dict), "Each input must be a declared object")
            key = entry.get("key")
            require(isinstance(key, str) and key and key not in self.inputs, "Input keys must be unique text")
            require(entry.get("format") in ALLOWED_FORMATS, "Unsupported declared dataset input format")
            require(key in input_paths, "Missing declared original local input: " + key)
            path = Path(input_paths[key])
            require(path.is_absolute() and path.is_file(), "An absolute original input file is required: " + key)
            raw = path.read_bytes()
            require(type(entry.get("bytes")) is int and len(raw) == entry["bytes"],
                    "Original input length changed: " + key)
            require(sha(raw) == entry.get("sha256"), "Original input SHA-256 changed: " + key)
            self.inputs[key], self.raw[key] = dict(entry), raw

    def dataset(self, key, catalog_key=None):
        if catalog_key is None:
            companions = self.parameters.get("source_catalogs", {})
            require(isinstance(companions, dict), "source_catalogs must map source input keys to catalogue input keys")
            catalog_key = companions.get(key)
        cache_key = (key, catalog_key)
        if cache_key not in self.datasets:
            entry = self.entry(key)
            value = parse_dataset(self.raw[key], entry["format"], self.base(key))
            if catalog_key is not None:
                require(entry["format"] == "nquads" and self.entry(catalog_key)["format"] == "json",
                        "A graph catalogue companion belongs to an exact N-Quads source")
                value, raw = attach_catalog(value, self.raw[key], native.load_json(self.raw[catalog_key]))
            else:
                value, _, raw = canonical_dataset(value)
                if entry["format"] == "nquads":
                    self.warnings.append("This N-Quads source has no companion catalogue. Only represented "
                                         "named-graph membership is known; absent empty named graphs cannot be inferred.")
            self.datasets[cache_key] = (value, raw)
        return self.datasets[cache_key]

    def retained_dataset(self, dataset_key, catalogue_key):
        require(catalogue_key is not None, "A retained snapshot requires its graph catalogue")
        return self.dataset(dataset_key, catalogue_key)


def _selection(value, selection, label, *, named_only=False, allow_absent=False):
    if selection == "all":
        return sorted((g for g in value.graphs if not named_only or g is not None), key=graph_key)
    require(isinstance(selection, list), label + " must be 'all' or an explicit graph-selector list")
    names = [selector_term(v, named_only=named_only) for v in selection]
    require(len(set(names)) == len(names), label + " contains duplicate graph selectors")
    if not allow_absent:
        require(set(names) <= value.graphs, label + " selects a graph absent from the retained catalogue")
    return sorted(names, key=graph_key)


def _dataset_summary(value, raw):
    counts = Counter(q[3] for q in value.quads)
    return {"data_model": "dataset", "dataset_sha256": dataset_identity(value, raw),
            "nquads_sha256": sha(raw), "quad_count": len(value.quads),
            "graph_count": len(value.graphs), "named_graph_count": len(value.graphs) - 1,
            "empty_graph_count": sum(counts[g] == 0 for g in value.graphs),
            "canonicalization": dict(CANONICALIZATION)}


def _write_dataset(context, value, raw):
    context.write("dataset.nq", raw, "application/n-quads", "dataset", "Complete canonical RDF dataset")
    context.write("dataset.trig", _trig_bytes(value), "application/trig", "trig",
                  "Complete RDF dataset including empty named graphs")
    catalogue = graph_catalog(value, raw)
    context.json("graph-catalog.json", catalogue, "graph_catalog", "Complete canonical graph inventory")
    return catalogue


def inspect_source(context):
    key = context.parameters.get("input_key")
    entry = context.entry(key)
    if entry["format"] not in DATASET_FORMATS:
        summary = native.inspect_source(context)
        return {**summary, "data_model": "dataset", "source_format": entry["format"]}
    value, raw = context.dataset(key)
    for graph in value.graphs:
        value.graph_origins[graph].append({
            "input_key": key, "source_id": entry.get("source_id"), "revision": entry.get("revision"),
            "sha256": entry["sha256"], "source_graph": graph_selector(graph),
        })
    catalogue = _write_dataset(context, value, raw)
    union = value.ordinary_graph(value.graphs)
    preview = sorted(value.quads, key=nq_line)[:50]
    inspection = {
        "schema": "commons-semantic-dataset-inspection/1",
        "kind": "rdf_dataset", "source": context.source(key),
        **_dataset_summary(value, raw), "graphs": catalogue["graphs"],
        "stats": native.graph_stats(union),
        "preview_quads": [quad_value(q) for q in preview],
        "preview_limited": len(value.quads) > len(preview),
        "stats_scope": "explicit union for descriptive term counts only; quad and graph counts remain separate",
    }
    context.json("inspection.json", inspection, "inspection", "Whole-source dataset inspection and graph selectors")
    summary = {**_dataset_summary(value, raw), "source_format": entry["format"], "native_outcome": "complete"}
    context.report("Retained RDF dataset inspection", summary, [("Complete graph inventory", catalogue["graphs"]),
                   ("Quad preview (first 50; dataset.nq is complete)", inspection["preview_quads"])])
    return summary


def snapshot(context):
    p = context.parameters
    data_keys, mappings = p.get("data_keys", []), p.get("mappings", [])
    require(isinstance(data_keys, list) and all(isinstance(k, str) for k in data_keys)
            and len(set(data_keys)) == len(data_keys), "data_keys must be a unique ordered list")
    require(isinstance(mappings, list) and all(isinstance(m, dict) for m in mappings)
            and (data_keys or mappings), "Snapshot needs selected RDF sources or reviewed CSV mappings")
    require(len({m.get("mapping_id") for m in mappings}) == len(mappings),
            "Mapping IDs must be unique within a dataset snapshot")
    source_graphs = p.get("source_graphs", {})
    companions = p.get("source_catalogs", {})
    require(isinstance(source_graphs, dict) and set(source_graphs) <= set(data_keys),
            "source_graphs must refer to selected RDF input keys")
    require(isinstance(companions, dict), "source_catalogs must be an object")
    merged, sources, original_rows, selected_sources = DatasetValue(), {}, [], []
    skipped, ill_typed = 0, 0
    for key in data_keys:
        source = context.source(key)
        value, source_raw = context.dataset(key)
        selected = _selection(value, source_graphs.get(key, "all"), "Source graph selection")
        selected_set = set(selected)
        sources[key] = source
        companion_key = companions.get(key)
        if companion_key is not None:
            sources[companion_key] = context.source(companion_key)
        identity = _stable({name: source.get(name) for name in ("key", "source_id", "revision", "sha256")})
        prefix = "source" + sha(identity.encode("utf-8")) + "_"
        nodes = {node for q in value.quads for node in q if isinstance(node, BNode)}
        nodes.update(g for g in value.graphs if isinstance(g, BNode))
        scoped = {node: BNode(prefix + str(node)) for node in nodes}
        selected_sources.append({"input_key": key, "source_dataset_sha256": dataset_identity(value, source_raw),
                                 "graphs": [graph_selector(g) for g in selected],
                                 "selection_before_document_scope": True,
                                 "catalogue_input_key": companion_key})
        for graph in selected:
            destination = scoped.get(graph, graph)
            merged.graphs.add(destination)
            origin = {"input_key": key, "source_id": source.get("source_id"),
                      "revision": source.get("revision"), "sha256": source["sha256"],
                      "source_graph": graph_selector(graph)}
            if companion_key is not None:
                origin["catalogue"] = {"input_key": companion_key, "sha256": context.entry(companion_key)["sha256"]}
            merged.graph_origins[destination].append(origin)
        for quad in value.quads:
            if quad[3] not in selected_set:
                continue
            destination = _replace_quad(quad, scoped)
            merged.quads.add(destination)
            merged.quad_origins[destination].append({
                "kind": "rdf", "input_key": key, "source_id": source.get("source_id"),
                "revision": source.get("revision"), "sha256": source["sha256"],
                "source_dataset_sha256": dataset_identity(value, source_raw),
                "source_quad": quad_value(quad), "source_nquads": nq_line(quad).rstrip("\n"),
            })
            if isinstance(quad[2], Literal) and getattr(quad[2], "ill_typed", False):
                ill_typed += 1
        if source["format"] == "json-ld":
            context.warnings.append("JSON-LD uses the original native JSON-to-RDF conversion. "
                                    "JSON numeric token spelling and precision remain in original source bytes; "
                                    "explicit typed string values retain their RDF lexical forms.")
    for mapping in mappings:
        require("destination_graph" in mapping,
                "Dataset CSV mappings require an explicit retained destination_graph")
        destination = selector_term(mapping["destination_graph"])
        require(destination is None or isinstance(destination, URIRef),
                "CSV mapping destinations must be the default graph or an explicit graph IRI")
        key = mapping.get("input_key")
        headers, rows, null_values = native.reviewed_mapping(mapping, context)
        source = context.source(key)
        sources[key] = source
        merged.graphs.add(destination)
        merged.graph_origins[destination].append({
            "input_key": key, "source_id": source.get("source_id"), "revision": source.get("revision"),
            "sha256": source["sha256"], "source_graph": graph_selector(destination),
            "mapping_id": mapping["mapping_id"], "mapping_revision": mapping.get("revision", 1),
            "kind": "reviewed CSV destination",
        })
        for row in rows:
            row_id = mapping["mapping_id"] + ":" + str(mapping.get("revision", 1)) + ":" + str(row["row"])
            original_rows.append({"id": row_id, "mapping_id": mapping["mapping_id"],
                                  "mapping_revision": mapping.get("revision", 1), "input_key": key,
                                  "source_id": source.get("source_id"), "source_revision": source.get("revision"),
                                  "source_sha256": source["sha256"], "headers": headers,
                                  "destination_graph": graph_selector(destination), **row})
            subject = native.template_iri(mapping["subject_template"], row["values"], null_values)
            common = {"kind": "csv", "input_key": key, "source_id": source.get("source_id"),
                      "revision": source.get("revision"), "sha256": source["sha256"],
                      "mapping_id": mapping["mapping_id"], "mapping_revision": mapping.get("revision", 1),
                      "row_id": row_id, "row": row["row"], "physical_line_start": row["physical_line_start"],
                      "physical_line_end": row["physical_line_end"],
                      "subject_template": mapping["subject_template"],
                      "destination_graph": graph_selector(destination)}
            for class_iri in mapping.get("classes", []):
                q = normalized_quad((subject, RDF.type, native.absolute_iri(class_iri), destination))
                merged.quads.add(q)
                merged.quad_origins[q].append({**common, "rule": "declared class", "class": class_iri})
            for field_index, field in enumerate(mapping.get("fields", [])):
                raw_cell = row["values"][field["column"]]
                if raw_cell in null_values:
                    skipped += 1
                    continue
                predicate = native.absolute_iri(field["predicate"])
                if field["kind"] == "iri":
                    obj = (native.template_iri(field["iri_template"], row["values"], null_values)
                           if field.get("iri_template") is not None
                           else native.absolute_iri(raw_cell, "Original IRI cell"))
                else:
                    obj = Literal(raw_cell, datatype=URIRef(field["datatype"]) if field.get("datatype") else None,
                                  lang=field.get("language") or None, normalize=False)
                    if getattr(obj, "ill_typed", False):
                        ill_typed += 1
                q = normalized_quad((subject, predicate, obj, destination))
                merged.quads.add(q)
                merged.quad_origins[q].append({
                    **common, "rule": "declared field", "field_index": field_index, "column": field["column"],
                    "raw_cell": raw_cell, "predicate": field["predicate"], "value_kind": field["kind"],
                    "datatype": field.get("datatype"), "language": field.get("language"),
                    "iri_template": field.get("iri_template"),
                })
    value, node_map, raw = canonical_dataset(merged)
    catalogue = _write_dataset(context, value, raw)
    provenance = {
        "schema": PROVENANCE_SCHEMA, "job_id": context.job["job_id"],
        "data_model": "dataset", "dataset_sha256": catalogue["dataset_sha256"],
        "nquads_sha256": catalogue["nquads_sha256"], "quad_count": len(value.quads),
        "canonicalization": dict(CANONICALIZATION),
        "sources": [sources[k] for k in sorted(sources)], "selected_sources": selected_sources,
        "mappings": copy.deepcopy(mappings), "csv_rows": original_rows,
        "graphs": catalogue["graphs"],
        "blank_nodes": [{"source_scoped": str(old), "snapshot": str(new)}
                        for old, new in sorted(node_map.items(), key=lambda item: str(item[0]))],
        "quads": [{**quad_value(q), "nquads": nq_line(q).rstrip("\n"),
                   "origins": _dedup_origins(value.quad_origins[q])} for q in sorted(value.quads, key=nq_line)],
    }
    context.json("provenance.json", provenance, "provenance", "Complete quad, graph and source-row provenance")
    summary = {**_dataset_summary(value, raw), "source_count": len(sources), "rdf_source_count": len(data_keys),
               "mapping_count": len(mappings), "mapped_rows": len(original_rows),
               "null_fields_skipped": skipped, "ill_typed_literal_occurrences": ill_typed,
               "provenance_complete": True, "native_outcome": "complete"}
    if ill_typed:
        context.warnings.append("Ill-typed literal lexical values are retained for validation; "
                                + str(ill_typed) + " source/mapping occurrences were observed.")
    context.report("Retained semantic dataset snapshot", summary,
                   [("Selected original source graphs", selected_sources),
                    ("Complete graph inventory", catalogue["graphs"])])
    return summary


class _ScopedContext(native.Context):
    """Use the unchanged native graph operations on an explicit selected view."""
    def __init__(self, parent, key, selected_graph, value, raw, scope, prefix=""):
        self.parent, self.data_key, self.selected_graph = parent, key, selected_graph
        self.value, self.raw_dataset, self.scope, self.prefix = value, raw, copy.deepcopy(scope), prefix
        self.job, self.inputs, self.raw = parent.job, parent.inputs, parent.raw
        self.parameters = {**parent.parameters, "graph_key": key}
        self.files, self.warnings, self.output = parent.files, parent.warnings, parent.output
        self.captured = {}

    def graph(self, key):
        return self.selected_graph if key == self.data_key else self.parent.graph(key)

    def _enrich(self, value):
        if not isinstance(value, dict):
            return value
        result = copy.deepcopy(value)
        if "graph_sha256" in result:
            result.pop("graph_sha256")
            result.update({"data_model": "dataset", "dataset_sha256": dataset_identity(self.value, self.raw_dataset),
                           "nquads_sha256": sha(self.raw_dataset), "dataset_scope": self.scope})
        return result

    def write(self, name, body, media_type, role, title):
        return self.parent.write(self.prefix + name, body, media_type, role, title)

    def json(self, name, value, role, title):
        value = self._enrich(value)
        self.captured[name] = copy.deepcopy(value)
        return self.write(name, json_bytes(value), "application/json", role, title)

    def report(self, title, summary, sections=()):
        return native.Context.report(self, title, self._enrich(summary),
                                     [("Explicit retained dataset scope", self.scope), *sections])


def _scoped_quads(value, selected):
    names = set(selected)
    return {q for q in value.quads if q[3] in names}


def _focus_quads(value, selected, finding):
    focus = {native.term_from_json(t) for t in finding.get("original_focus_nodes", [])}
    return [quad_value(q) for q in sorted(_scoped_quads(value, selected), key=nq_line)
            if q[0] in focus or q[2] in focus]


def validation(context):
    p = context.parameters
    key, catalogue_key = p.get("dataset_key"), p.get("catalog_key")
    value, raw = context.retained_dataset(key, catalogue_key)
    scope = p.get("validation_scope")
    require(isinstance(scope, dict) and scope.get("mode") in {"per_graph", "union"},
            "Validation requires explicit per_graph or union scope")
    selected = _selection(value, scope.get("graphs"), "Validation graphs")
    require(selected, "Validation requires at least one explicitly selected graph")
    targets = [[g] for g in selected] if scope["mode"] == "per_graph" else [selected]
    results, findings, files_by_target = [], [], []
    severities = Counter()
    for index, graphs in enumerate(targets, 1):
        target_scope = {"mode": scope["mode"], "graphs": [graph_selector(g) for g in graphs]}
        target_id = "graph-" + str(index).zfill(4) if scope["mode"] == "per_graph" else "union"
        ordinary = value.ordinary_graph(graphs)
        proxy = _ScopedContext(context, key, ordinary, value, raw, target_scope, prefix=target_id + "-")
        before = len(context.files)
        result = native.validation(proxy)
        result = proxy._enrich(result)
        result.update({"target_id": target_id, "validation_scope": target_scope,
                       "selected_quads": len(_scoped_quads(value, graphs)), "selected_triples": len(ordinary)})
        results.append(result)
        files_by_target.append({"target_id": target_id, "files": copy.deepcopy(context.files[before:])})
        captured = proxy.captured.get("findings.json", {})
        for finding in captured.get("findings", []):
            item = {**finding, "target_id": target_id, "validation_scope": target_scope,
                    "source_dataset_sha256": dataset_identity(value, raw)}
            if result.get("validation_phase") == "data":
                item["source_quads"] = _focus_quads(value, graphs, finding)
            else:
                item["source_quads"] = []
            findings.append(item)
        severities.update(result.get("severity_counts", {}))
    complete = all(r.get("report_complete", False) for r in results)
    valid_shapes = all(r.get("shapes_valid", False) for r in results)
    assessed = complete and valid_shapes and all(r.get("data_validation_performed") for r in results)
    conforms = all(r.get("conforms") is True for r in results) if assessed else None
    outcome = ("invalid_shapes" if not valid_shapes else "validation_failure" if not complete
               else "conforms" if conforms else "nonconforming")
    summary = {**_dataset_summary(value, raw), "native_outcome": outcome, "conforms": conforms,
               "validation_scope": {"mode": scope["mode"], "graphs": [graph_selector(g) for g in selected]},
               "targets": len(results), "validation_results": results,
               "data_validation_performed": assessed, "shapes_valid": valid_shapes,
               "root_results": sum(r.get("root_results", 0) for r in results),
               "all_results_including_details": len(findings),
               "severity_counts": dict(sorted(severities.items())),
               "inference": p.get("inference", "none"), "allow_infos": p.get("allow_infos", False),
               "allow_warnings": p.get("allow_warnings", False),
               "report_complete": complete, "implicit_dataset_union": False}
    document = {"schema": "commons-semantic-dataset-findings/1", **summary,
                "sources": [context.source(k) for k in [key, catalogue_key]
                            + p.get("shape_keys", []) + p.get("ontology_keys", [])],
                "reports": files_by_target, "findings": findings}
    context.json("findings.json", document, "findings", "Complete graph-scoped SHACL findings")
    context.report("Explicit dataset SHACL validation", summary,
                   [("Complete graph-scoped findings", findings)])
    return summary


def query(context):
    p = context.parameters
    key, catalogue_key = p.get("dataset_key"), p.get("catalog_key")
    value, raw = context.retained_dataset(key, catalogue_key)
    scope = p.get("query_scope")
    require(isinstance(scope, dict) and scope.get("default_graph") in {"default", "union"},
            "Query requires an explicit default_graph choice")
    named = _selection(value, scope.get("named_graphs"), "Query named graphs", named_only=True)
    selected_default = [None] if scope["default_graph"] == "default" else [None, *named]
    dataset = Dataset(default_union=False)
    targets = {name: dataset.graph(name) for name in named}
    for subject, predicate, obj, graph in value.quads:
        if graph in targets:
            targets[graph].add((subject, predicate, obj))
    for triple in value.ordinary_graph(selected_default):
        dataset.default_graph.add(triple)
    exact_scope = {"default_graph": scope["default_graph"],
                   "named_graphs": [graph_selector(g) for g in named],
                   "default_graph_sources": [graph_selector(g) for g in selected_default],
                   "default_triples": len(dataset.default_graph),
                   "named_quads": len(_scoped_quads(value, named))}
    if any(isinstance(name, BNode) for name in named):
        context.warnings.append("Blank-node graph names remain present in the selected dataset and may be "
                                "returned by GRAPH variables in RDFLib. SPARQL GRAPH constants use IRIs; "
                                "a '_:label' in a query is not a stable graph-name constant.")
    proxy = _ScopedContext(context, key, dataset, value, raw, exact_scope)
    # RDFLib's bound GRAPH branch calls get_context without checking whether
    # that graph belongs to the active dataset. An empty BGP could otherwise
    # match an excluded graph, including the internal default sentinel.
    from rdflib.plugins.sparql import evaluate as evaluator
    original_eval_graph = evaluator.evalGraph
    visible_names = set(named)
    def scoped_eval_graph(query_context, part):
        bound = query_context[part.term]
        if bound is not None and bound not in visible_names:
            return iter(())
        return original_eval_graph(query_context, part)
    evaluator.evalGraph = scoped_eval_graph
    try:
        result = native.query(proxy)
    finally:
        evaluator.evalGraph = original_eval_graph
    result = proxy._enrich(result)
    result.update({"query_scope": exact_scope, "implicit_dataset_union": False,
                   "result_data_model": "graph" if result.get("query_form") in {"ConstructQuery", "DescribeQuery"}
                   else "bindings" if result.get("query_form") == "SelectQuery" else "boolean"})
    context.json("dataset-query-scope.json", {**result, "dataset_source": context.source(key),
                                            "catalogue_source": context.source(catalogue_key)},
                 "query_result", "Exact dataset query scope and result model")
    return result


def provenance_index(context, key, value, raw):
    if key is None:
        return {}, None
    require(context.entry(key)["format"] == "json", "Quad provenance must be retained JSON")
    document = native.load_json(context.raw[key])
    require(isinstance(document, dict) and document.get("schema") == PROVENANCE_SCHEMA,
            "Unknown retained dataset provenance")
    require(document.get("dataset_sha256") == dataset_identity(value, raw)
            and document.get("nquads_sha256") == sha(raw),
            "Provenance does not bind this exact dataset and graph inventory")
    require(type(document.get("quad_count")) is int and document["quad_count"] == len(value.quads),
            "Provenance quad count differs from its selected dataset")
    graph_rows = document.get("graphs")
    require(isinstance(graph_rows, list), "Provenance requires the complete graph inventory")
    expected_catalogue = graph_catalog(value, raw)
    require([{k: r.get(k) for k in ("graph", "quad_count", "empty")} for r in graph_rows]
            == [{k: r[k] for k in ("graph", "quad_count", "empty")} for r in expected_catalogue["graphs"]],
            "Provenance graph identities/counts differ from the selected catalogue")
    rows = document.get("quads")
    require(isinstance(rows, list) and len(rows) == len(value.quads), "Complete retained quad provenance is required")
    index = {}
    for row in rows:
        require(isinstance(row, dict), "Invalid retained provenance quad")
        q = normalized_quad(tuple(native.term_from_json(row.get(name))
                                  for name in ("subject", "predicate", "object"))
                            + (selector_term(row.get("graph")),))
        require(q in value.quads and q not in index, "Provenance has an absent or duplicate quad")
        require(row.get("nquads") == nq_line(q).rstrip("\n"), "Provenance typed terms and N-Quads disagree")
        origins = row.get("origins")
        require(isinstance(origins, list) and all(isinstance(o, dict) for o in origins),
                "Quad origins must be retained metadata objects")
        index[q] = origins
    return index, {"input_key": key, "sha256": context.entry(key)["sha256"],
                   "dataset_sha256": document["dataset_sha256"], "sources": document.get("sources", []),
                   "mappings": document.get("mappings", []),
                   "all_quads_have_origins": all(bool(origins) for origins in index.values())}


def _graph_changes(before, after, selected):
    before_names, after_names = before.graphs & set(selected), after.graphs & set(selected)
    records = []
    for side, kind, value, names in (("before", "removed_graph", before, before_names - after_names),
                                    ("after", "added_graph", after, after_names - before_names)):
        counts = Counter(q[3] for q in value.quads)
        for graph in sorted(names, key=graph_key):
            records.append({"change": kind, "snapshot": side, "graph": graph_selector(graph),
                            "quad_count": counts[graph], "empty": counts[graph] == 0,
                            "origins": _dedup_origins(value.graph_origins[graph])})
    return records


def _ground_membership_changes(before_quads, after_quads):
    indexes = []
    for quads in (before_quads, after_quads):
        index = defaultdict(set)
        for s, p, o, g in quads:
            if not any(isinstance(v, BNode) for v in (s, o, g)):
                index[(s, p, o)].add(g)
        indexes.append(index)
    before, after = indexes
    result = []
    for triple in sorted(set(before) & set(after), key=native.nt_line):
        if before[triple] == after[triple]:
            continue
        result.append({**native.triple_value(triple),
                       "before_graphs": [graph_selector(g) for g in sorted(before[triple], key=graph_key)],
                       "after_graphs": [graph_selector(g) for g in sorted(after[triple], key=graph_key)],
                       "removed_graphs": [graph_selector(g) for g in sorted(before[triple] - after[triple], key=graph_key)],
                       "added_graphs": [graph_selector(g) for g in sorted(after[triple] - before[triple], key=graph_key)],
                       "identity_basis": "same ground RDF triple; only default and IRI-named graphs"})
    return result


def compare(context):
    p = context.parameters
    before, before_raw = context.retained_dataset(p.get("before_dataset_key"), p.get("before_catalog_key"))
    after, after_raw = context.retained_dataset(p.get("after_dataset_key"), p.get("after_catalog_key"))
    scope = p.get("comparison_scope")
    require(isinstance(scope, dict) and scope.get("impact_mode") in {"within_graph", "union"},
            "Comparison requires an explicit within_graph or union impact scope")
    combined = DatasetValue(graphs=before.graphs | after.graphs)
    selected = _selection(combined, scope.get("graphs"), "Comparison graphs")
    require(selected, "Comparison requires at least one selected graph")
    bquads, aquads = _scoped_quads(before, selected), _scoped_quads(after, selected)
    removed, added, common = bquads - aquads, aquads - bquads, bquads & aquads
    changes_to_graphs = _graph_changes(before, after, selected)
    membership_changes = _ground_membership_changes(bquads, aquads)
    bi, bsource = provenance_index(context, p.get("before_provenance_key"), before, before_raw)
    ai, asource = provenance_index(context, p.get("after_provenance_key"), after, after_raw)
    indexes = {"before": bi, "after": ai}
    hashes = {"before": dataset_identity(before, before_raw), "after": dataset_identity(after, after_raw)}
    provenance_complete = bool(bsource and asource and bsource["all_quads_have_origins"]
                               and asource["all_quads_have_origins"])
    if not provenance_complete:
        context.warnings.append("Complete original quad origins were not supplied for both datasets. "
                                "The quad and graph-inventory differences remain complete.")
    context.warnings.append("URDNA2015 blank-node labels are local to each whole dataset, not cross-edition "
                            "business identifiers. A structural edit can relabel other connected blank nodes. "
                            "Canonical quad differences are complete but are not a minimum edit or a claimed "
                            "entity correspondence. Ground triple membership changes are identified separately.")
    if any(isinstance(g, BNode) for g in selected):
        context.warnings.append("A selected blank graph name addresses that dataset's local canonical label; "
                                "matching label text in another edition does not establish graph business identity.")
    predicates = p.get("edge_predicates", [])
    require(isinstance(predicates, list), "edge_predicates must be an explicit list")
    selected_predicates = {native.absolute_iri(v, "Impact edge predicate") for v in predicates}
    depth = native.positive_integer(p.get("depth"), "Impact depth", 2, minimum=0)
    node_limit = native.positive_integer(p.get("node_limit"), "Impact node_limit", 100000)
    exact_scope = {"graphs": [graph_selector(g) for g in selected], "impact_mode": scope["impact_mode"]}
    context.write("additions.nq", "".join(nq_line(q) for q in sorted(added, key=nq_line)),
                  "application/n-quads", "additions", "Complete added quads with after-dataset labels")
    context.write("removals.nq", "".join(nq_line(q) for q in sorted(removed, key=nq_line)),
                  "application/n-quads", "removals", "Complete removed quads with before-dataset labels")
    context.json("graph-changes.json", {
        "schema": "commons-semantic-dataset-graph-changes/1", "comparison_scope": exact_scope,
        "before_dataset_sha256": hashes["before"], "after_dataset_sha256": hashes["after"],
        "graph_inventory_changes": changes_to_graphs, "ground_membership_changes": membership_changes,
        "membership_identity_basis": "Ground RDF terms and default/IRI graph names only. "
                                     "All other membership differences remain in complete quad changes.",
    }, "impact", "Complete graph inventory changes and definite ground triple membership changes")
    node_details, node_origins, node_graphs = {}, defaultdict(dict), defaultdict(set)
    adjacency, predicate_uses, relationships = defaultdict(list), defaultdict(list), {}
    def node_key(node, side, graph):
        require(isinstance(node, (URIRef, BNode)), "Impact resources must be IRIs or blank nodes")
        key = (side, graph_key(graph) if scope["impact_mode"] == "within_graph" else "", native.term_key(node))
        node_details[key] = {"term": native.term(node), "snapshot_scope": side}
        node_graphs[key].add(graph)
        return key
    def node_json(key):
        return {**node_details[key], "graphs": [graph_selector(g) for g in sorted(node_graphs[key], key=graph_key)],
                "impact_mode": scope["impact_mode"]}
    for side, quads in (("before", bquads), ("after", aquads)):
        for q in sorted(quads, key=nq_line):
            s, pred, obj, graph = q
            skey = node_key(s, side, graph)
            rid = side + ":" + sha(nq_line(q).encode("utf-8"))
            origins = indexes[side].get(q, [])
            relationships[rid] = {"id": rid, "snapshot": side, "dataset_sha256": hashes[side],
                                  **quad_value(q), "nquads": nq_line(q).rstrip("\n"), "origins": origins}
            predicate_uses[node_key(pred, side, graph)].append((skey, rid, "predicate-use"))
            for origin in origins:
                node_origins[skey][_stable(origin)] = origin
            if isinstance(obj, (URIRef, BNode)):
                okey = node_key(obj, side, graph)
                for origin in origins:
                    node_origins[okey][_stable(origin)] = origin
                if not selected_predicates or pred in selected_predicates:
                    adjacency[skey].append((okey, rid, "outgoing"))
                    adjacency[okey].append((skey, rid, "incoming"))
    changes, seeds, changed_subjects = [], set(), set()
    for side, kind, quads in (("before", "removed", removed), ("after", "added", added)):
        for q in sorted(quads, key=nq_line):
            subject, _, obj, graph = q
            skey = node_key(subject, side, graph)
            seeds.add(skey)
            changed_subjects.add(skey)
            if isinstance(obj, (URIRef, BNode)):
                seeds.add(node_key(obj, side, graph))
            changes.append({"change": kind, "snapshot": side, "dataset_sha256": hashes[side],
                            **quad_value(q), "nquads": nq_line(q).rstrip("\n"),
                            "origins": indexes[side].get(q, [])})
    ordered_seeds = sorted(seeds)
    visited = {key: 0 for key in ordered_seeds[:node_limit]}
    reasons = {key: [{"kind": "changed quad"}] for key in visited}
    queue = deque(visited)
    observed = set(seeds)
    used_relationships = set()
    truncated = len(seeds) > node_limit
    while queue:
        current = queue.popleft()
        distance = visited[current]
        if distance >= depth:
            continue
        neighbors = adjacency.get(current, []) + predicate_uses.get(current, [])
        for neighbor, rid, direction in sorted(neighbors):
            observed.add(neighbor)
            used_relationships.add(rid)
            if neighbor in visited:
                continue
            if len(visited) >= node_limit:
                truncated = True
                continue
            visited[neighbor] = distance + 1
            reasons[neighbor] = [{"kind": direction, "from": node_json(current), "relationship_id": rid}]
            queue.append(neighbor)
    affected = [{**node_json(key), "distance": visited[key], "changed_subject": key in changed_subjects,
                 "reasons": reasons[key],
                 "origins": [node_origins[key][k] for k in sorted(node_origins[key])]}
                for key in sorted(visited, key=lambda k: (visited[k], k))]
    context.write("changes.jsonl", "".join(_stable(row) + "\n" for row in changes),
                  "application/x-ndjson", "impact", "Complete added and removed quads with source references")
    context.write("impact-relationships.jsonl",
                  "".join(_stable(relationships[k]) + "\n" for k in sorted(used_relationships)),
                  "application/x-ndjson", "impact", "Actual traversed relationships with side and graph")
    bnames, anames = before.graphs & set(selected), after.graphs & set(selected)
    summary = {
        "data_model": "dataset", "native_outcome": "limited_impact" if truncated else "complete",
        "before_dataset_sha256": hashes["before"], "after_dataset_sha256": hashes["after"],
        "before_nquads_sha256": sha(before_raw), "after_nquads_sha256": sha(after_raw),
        "comparison_scope": exact_scope,
        "before_quads": len(bquads), "after_quads": len(aquads), "common_quads": len(common),
        "added_quads": len(added), "removed_quads": len(removed),
        "before_graphs": len(bnames), "after_graphs": len(anames),
        "added_graphs": len(anames - bnames), "removed_graphs": len(bnames - anames),
        "ground_membership_changes": len(membership_changes),
        "equivalent": not added and not removed and bnames == anames,
        "equivalence_scope": "selected canonical quads and graph inventory",
        "quad_difference_complete": True, "graph_inventory_difference_complete": True,
        "changed_subjects": len(changed_subjects), "seed_nodes": len(seeds),
        "impact_nodes": len(affected), "impact_depth": depth, "impact_node_limit": node_limit,
        "impact_truncated": truncated, "impact_total_within_depth": None if truncated else len(affected),
        "observed_candidate_nodes_at_least": len(observed), "traversed_relationships": len(used_relationships),
        "edge_predicates": sorted(str(v) for v in selected_predicates),
        "provenance_complete": provenance_complete,
        "direction": "incoming and outgoing selected resource edges, plus use of a visited predicate IRI",
        "cross_edition_traversal": False,
        "blank_node_comparison": "local whole-dataset canonical labels; no cross-edition business identity",
    }
    context.json("impact.json", {
        "schema": "commons-semantic-dataset-impact/1", **summary, "before_provenance": bsource,
        "after_provenance": asource, "graph_inventory_changes": changes_to_graphs,
        "ground_membership_changes_detail": membership_changes, "nodes": affected,
    }, "impact", "Selected graph-aware impact with complete dataset differences")
    context.report("Dataset comparison and graph-aware impact", summary,
                   [("Graph inventory changes", changes_to_graphs),
                    ("Definite ground triple membership changes", membership_changes),
                    ("Changed quad preview (first 50; changes.jsonl is complete)", changes[:50])])
    return summary


def execute(job: dict, input_paths: dict[str, Path], output_dir: Path) -> dict:
    """Execute one pinned dataset job through the original native operations."""
    versions = native.native_versions()
    installed = importlib.metadata.version("PyLD")
    require(installed == CANONICALIZATION["version"], "Exact PyLD 3.3.0 is required; found " + installed)
    versions["PyLD"] = installed
    with native.native_scope():
        context = Context(job, input_paths, output_dir)
        action = job.get("action")
        operations = {"inspect": inspect_source, "snapshot": snapshot, "validate": validation,
                      "query": query, "compare": compare}
        require(action in operations, "Unknown dataset native action")
        summary = operations[action](context)
        return {
            "schema": SCHEMA, "action": action,
            "summary": {**summary, "engine_versions": versions,
                        "engine_source_sha256": ENGINE_SOURCE["sha256"],
                        "supporting_engine_source_sha256": native.ENGINE_SOURCE["sha256"]},
            "engine_source": dict(ENGINE_SOURCE),
            "supporting_engine_sources": [dict(native.ENGINE_SOURCE)],
            "files": context.files, "warnings": list(dict.fromkeys(context.warnings)),
        }

"""Origin-bound loopback HTTP interface for the private semantic workspace."""
from __future__ import annotations
import contextlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import signal
import threading
from urllib.parse import quote, urlsplit
from .application import SemanticApplication, KINDS
from .security import atomic_write, canonical, read_json, private_directory

MAX_REQUEST=90*1024*1024
CSP="default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'"

class OperatorServer(ThreadingHTTPServer):
    daemon_threads=True
    allow_reuse_address=True
    def __init__(self,address,application):
        self.application=application
        self.assets=Path(__file__).resolve().parent.parent/"ui"
        super().__init__(address,OperatorHandler)
        self.origins={"http://localhost:"+str(self.server_port),"http://127.0.0.1:"+str(self.server_port)}
        self.origin="http://localhost:"+str(self.server_port)

class OperatorHandler(BaseHTTPRequestHandler):
    protocol_version="HTTP/1.1"
    server_version="SemanticOperator/1.0"
    def log_message(self,format,*args):
        return
    def _host(self):
        origin="http://"+self.headers.get("Host","")
        if origin not in self.server.origins:
            raise PermissionError("Open the workspace through its original local address.")
        return origin
    def _api(self):
        origin=self._host()
        if self.headers.get("Origin") not in (None,origin) or self.headers.get("Sec-Fetch-Site") not in (None,"same-origin","none"):
            raise PermissionError("The workspace request came from another origin.")
        if self.headers.get("X-Semantic-Operator")!="1":
            raise PermissionError("Use the local operator or its documented local API.")
    def _body(self):
        if self.headers.get("Transfer-Encoding"):
            raise ValueError("Send the exact operation length.")
        try: length=int(self.headers.get("Content-Length","0"))
        except ValueError as exc: raise ValueError("Send a valid operation length.") from exc
        if not 0<length<=MAX_REQUEST:
            raise ValueError("The operation payload is missing or exceeds 90 MiB.")
        self.connection.settimeout(60)
        body=self.rfile.read(length)
        if len(body)!=length:
            raise ValueError("The original operation body is incomplete.")
        return body
    def _send(self,status,body,media_type="application/json; charset=utf-8",*,headers=None):
        if isinstance(body,str): body=body.encode()
        self.send_response(status)
        for key,value in {"Content-Type":media_type,"Content-Length":str(len(body)),"Cache-Control":"no-store",
            "X-Content-Type-Options":"nosniff","X-Frame-Options":"DENY","Referrer-Policy":"no-referrer",
            "Cross-Origin-Resource-Policy":"same-origin","Content-Security-Policy":CSP,**(headers or {})}.items():
            self.send_header(key,value)
        self.end_headers()
        self.wfile.write(body)
    def _error(self,exc):
        status=403 if isinstance(exc,PermissionError) else 404 if isinstance(exc,KeyError) else 422 if isinstance(exc,(ValueError,TypeError)) else 500
        code={403:"local_origin_required",404:"record_missing",422:"operation_inputs",500:"operation_interrupted"}[status]
        with contextlib.suppress(BrokenPipeError,ConnectionResetError):
            self._send(status,canonical({"error":{"code":code,"message":str(exc).strip("'")[:2000]}}))
    def do_GET(self):
        try:
            self._host()
            path=urlsplit(self.path).path
            app=self.server.application
            if path.startswith("/api/"):
                self._api()
                if path=="/api/state": return self._send(200,canonical(app.state()))
                if path=="/api/references": return self._send(200,canonical(app.references()))
                if path.startswith("/api/history/"):
                    parts=path.removeprefix("/api/history/").split("/")
                    if len(parts)!=2 or parts[0] not in KINDS: raise ValueError("Choose a supported record history.")
                    app.store.document(*parts)
                    return self._send(200,canonical(app.store.history(*parts)))
                if path.startswith("/api/operations/"):
                    return self._send(200,canonical(app.store.operation(path.removeprefix("/api/operations/"))))
                if path.startswith("/api/files/"):
                    meta,body=app.store.artifact(path.removeprefix("/api/files/"),with_bytes=True)
                    return self._send(200,body,meta["media_type"],headers={
                        "Content-Disposition":"attachment; filename*=UTF-8''"+quote(meta["name"],safe="")})
                raise KeyError("No local endpoint has this path.")
            mapping={"/":"index.html","/index.html":"index.html","/app.js":"app.js","/datasets.js":"datasets.js","/style.css":"style.css"}
            if path not in mapping: raise KeyError("No operator view has this path.")
            name=mapping[path]
            media={"index.html":"text/html; charset=utf-8","app.js":"text/javascript; charset=utf-8","datasets.js":"text/javascript; charset=utf-8","style.css":"text/css; charset=utf-8"}[name]
            return self._send(200,(self.server.assets/name).read_bytes(),media)
        except Exception as exc:
            self._error(exc)
    def do_POST(self):
        try:
            self._api()
            if urlsplit(self.path).path!="/api/operate":
                raise KeyError("No local endpoint has this path.")
            if not self.headers.get("Content-Type","").startswith("application/json"):
                raise ValueError("Send the original JSON operation inputs.")
            request=read_json(self._body())
            if not isinstance(request,dict) or set(request)-{"action","payload","operation_id","actor"}:
                raise ValueError("Choose the documented local operation envelope.")
            result=self.server.application.perform(request["action"],request.get("payload",{}),
                operation_id=request["operation_id"],actor=request["actor"])
            self._send(200,canonical({"result":result,"operation_id":request["operation_id"]}))
        except Exception as exc:
            self._error(exc)

def serve(workspace,*,port=0,ready_file=None):
    os.umask(0o077)
    app=SemanticApplication(workspace)
    server=OperatorServer(("127.0.0.1",port),app)
    ready={"url":server.origin+"/","origin":server.origin,"workspace_id":app.store.workspace_id,"pid":os.getpid()}
    if ready_file:
        target=Path(ready_file).expanduser().absolute()
        private_directory(target.parent)
        atomic_write(target,canonical(ready))
    print(json.dumps(ready),flush=True)
    original={}
    def shutdown(signum,frame):
        threading.Thread(target=server.shutdown,daemon=True).start()
    if threading.current_thread() is threading.main_thread():
        for sig in (signal.SIGTERM,signal.SIGINT):
            original[sig]=signal.signal(sig,shutdown)
    try:
        server.serve_forever(poll_interval=0.25)
    finally:
        server.server_close()
        app.close()
        for sig,handler in original.items(): signal.signal(sig,handler)

"""Complete workspace transfer with original histories and independent received branches."""
from __future__ import annotations
import contextlib
import ctypes
import errno
import os
from pathlib import Path
import re
import shutil
import sqlite3
import tempfile
from .security import atomic_write, canonical, digest, private_directory, private_read, read_json, MAX_BUNDLE
from .store import ApplicationStore, identifier, standalone_database, now
from .worker import job_schema, JOB_SCHEMA, DATASET_JOB_SCHEMA

TABLES={"metadata","documents","history","artifacts","operations"}
KINDS={"source","mapping","snapshot","validation","query","comparison","decision","job","receiving","recovery"}

def validate_workspace(files,manifest):
    metadata=manifest.get("metadata",{})
    if metadata.get("schema")!="commons-semantic-workspace/1":
        raise ValueError("Choose a complete semantic operator workspace.")
    raw=files.get("application.sqlite3")
    if raw is None:
        raise ValueError("The original workspace database is missing.")
    db=sqlite3.connect(":memory:")
    db.row_factory=sqlite3.Row
    try:
        db.deserialize(standalone_database(raw))
        db.execute("PRAGMA trusted_schema=OFF")
        db.execute("PRAGMA query_only=ON")
        structures=db.execute("SELECT type,name,tbl_name,sql FROM sqlite_master").fetchall()
        tables={r["name"] for r in structures if r["type"]=="table"}
        if tables!=TABLES or any(r["type"] not in ("table","index") or
           (r["type"]=="index" and not r["name"].startswith("sqlite_autoindex_")) or
           (r["sql"] and "VIRTUAL" in r["sql"].upper()) for r in structures):
            raise ValueError("The original workspace has an unsupported database schema.")
        if db.execute("PRAGMA quick_check").fetchone()[0]!="ok":
            raise ValueError("The original workspace database is incomplete.")
        saved=dict(db.execute("SELECT key,value FROM metadata"))
        if saved.get("workspace_id")!=metadata.get("workspace_id"):
            raise ValueError("The workspace identity differs from the transfer manifest.")
        identifier(saved["workspace_id"],"Original workspace ID")
        artifacts={}
        for row in db.execute("SELECT * FROM artifacts"):
            identifier(row["id"],"Artifact ID")
            if not re.fullmatch(r"[a-f0-9]{64}",row["sha256"]) or row["backup"]!=1:
                raise ValueError("A transferred source identity is invalid.")
            name="sources/"+row["sha256"]+".bin"
            body=files.get(name)
            if body is None or len(body)!=row["bytes"] or digest(body)!=row["sha256"]:
                raise ValueError("The transfer omits or changes an original source.")
            artifacts[row["id"]]=dict(row)
        histories={}
        for row in db.execute("SELECT * FROM history ORDER BY kind,id,revision"):
            if row["kind"] not in KINDS:
                raise ValueError("The transfer contains an unsupported record kind.")
            identifier(row["id"],"Record ID")
            value=read_json(row["payload"])
            if not isinstance(value,dict) or digest(row["payload"].encode())!=row["sha256"]:
                raise ValueError("An original revision payload no longer matches its identity.")
            key=(row["kind"],row["id"])
            previous=histories.get(key)
            if row["revision"]!=(previous["revision"]+1 if previous else 1):
                raise ValueError("The transfer has incomplete original revision history.")
            histories[key]=dict(row)
        heads=[]
        for row in db.execute("SELECT * FROM documents ORDER BY kind,id"):
            final=histories.get((row["kind"],row["id"]))
            if not final or any(final[k]!=row[k] for k in ("revision","payload","sha256")):
                raise ValueError("A transferred record head differs from its complete original history.")
            value=read_json(row["payload"])
            if row["kind"]=="source":
                item=artifacts.get(value.get("artifact_id"))
                if not item or item["sha256"]!=value.get("sha256") or item["bytes"]!=value.get("bytes"):
                    raise ValueError("An original source record has lost its bytes.")
                catalogue=value.get("dataset_catalog")
                if catalogue:
                    companion=artifacts.get(catalogue.get("id"))
                    if not companion or companion["sha256"]!=catalogue.get("sha256") or companion["bytes"]!=catalogue.get("bytes"):
                        raise ValueError("An N-Quads source has lost its original graph catalogue.")
            if row["kind"]=="job":
                original=files.get("native-jobs/"+row["id"]+"/job.json")
                if original is None or digest(original)!=value.get("job_sha256"):
                    raise ValueError("An original native job has lost its pinned inputs.")
                job=read_json(original)
                if job_schema(job) not in (JOB_SCHEMA,DATASET_JOB_SCHEMA) or job.get("job_id")!=row["id"] or job.get("workspace_id")!=saved["workspace_id"]:
                    raise ValueError("A native job belongs to a different original workspace.")
                for item in job["inputs"]:
                    pinned=artifacts.get(item["artifact_id"])
                    if not pinned or pinned["sha256"]!=item["sha256"] or pinned["bytes"]!=item["bytes"]:
                        raise ValueError("A native job input is missing from the complete source set.")
            for item in value.get("files",[]) if row["kind"] in ("snapshot","validation","query","comparison") else []:
                retained=artifacts.get(item.get("artifact_id"))
                if not retained or retained["sha256"]!=item["sha256"] or retained["bytes"]!=item["bytes"]:
                    raise ValueError("An engineering result is missing a complete native output.")
            if row["kind"]=="snapshot" and value.get("parameters",{}).get("data_model")=="dataset":
                roles={v["role"] for v in value.get("files",[])}
                if not {"dataset","graph_catalog","provenance"}.issubset(roles):
                    raise ValueError("A dataset snapshot requires its quad bytes, graph catalogue and provenance.")
            heads.append({"kind":row["kind"],"id":row["id"],"revision":row["revision"],"sha256":row["sha256"],
                          "title":value.get("title",row["id"])})
        if len(heads)!=len(histories):
            raise ValueError("The transfer contains history without its original record head.")
        expected_sources={"sources/"+v["sha256"]+".bin" for v in artifacts.values()}
        if {n for n in files if n.startswith("sources/")}!=expected_sources:
            raise ValueError("The transfer contains unlisted source files.")
        for name in files:
            if name=="application.sqlite3" or name in expected_sources:
                continue
            parts=name.split("/")
            if (len(parts)<3 or parts[0]!="native-jobs" or (parts[1] not in {r["id"] for r in heads if r["kind"]=="job"})
                or parts[2] not in ("job.json","state.json","result.json","cancel.json","attempts","logs")):
                raise ValueError("The transfer includes a file outside its original native jobs.")
        counts={kind:sum(r["kind"]==kind for r in heads) for kind in KINDS}
        return {"workspace_id":saved["workspace_id"],"heads":heads,"records":len(heads),
                "revisions":db.execute("SELECT COUNT(*) FROM history").fetchone()[0],
                "artifacts":len(artifacts),"bytes":sum(len(v) for v in files.values()),"counts":counts}
    except sqlite3.Error as exc:
        raise ValueError("The transferred workspace schema or records cannot be read.") from exc
    finally:
        db.close()

def publish_directory(stage, target):
    """Atomically publish the complete owned stage without reserving an empty target.

    Linux renameat2(RENAME_NOREPLACE) leaves both sides intact if the destination
    already exists. There is no mkdir-to-receipt crash window and no replacement
    of another operation's empty directory.
    """
    library = ctypes.CDLL(None, use_errno=True)
    rename = getattr(library, "renameat2", None)
    if rename is None:
        raise RuntimeError("Atomic workspace receiving requires Linux renameat2 support.")
    rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    rename.restype = ctypes.c_int
    if rename(-100, os.fsencode(stage), -100, os.fsencode(target), 1) != 0:
        code = ctypes.get_errno()
        if code in (errno.EEXIST, errno.ENOTEMPTY):
            raise ValueError("The destination was created by another operation; its workspace was preserved.")
        raise OSError(code, os.strerror(code), str(target))


def receive_workspace(files,manifest,destination,*,archive_sha256,operation_id):
    summary=validate_workspace(files,manifest)
    target=Path(destination).expanduser().absolute()
    private_directory(target.parent)
    marker={"schema":"commons-semantic-receiving-origin/1","operation_id":operation_id,
            "archive_sha256":archive_sha256,"workspace_id":summary["workspace_id"],"destination":str(target)}
    if target.exists():
        private_directory(target,create=False)
        retained=target/"RECEIVED.json"
        if not retained.exists() or read_json(private_read(retained))!=marker:
            raise ValueError("The destination already belongs to another workspace or receiving operation.")
        return summary
    stage=target.parent/(".semantic-receiving-"+digest(canonical(marker))[:24])
    if stage.exists():
        private_directory(stage,create=False)
        if read_json(private_read(stage/"RECEIVED.json"))!=marker:
            raise ValueError("The receiving staging directory belongs to another operation.")
        # Only this operation's unpublished, fully reproducible staging is replaced.
        shutil.rmtree(stage)
    # Publish a named stage only after its durable ownership marker exists.
    # An interruption before that point cannot poison the operation's stage name.
    prepared=Path(tempfile.mkdtemp(prefix=".semantic-building-",dir=target.parent))
    prepared.chmod(0o700)
    try:
        atomic_write(prepared/"RECEIVED.json",canonical(marker),replace=False)
        publish_directory(prepared,stage)
    finally:
        if prepared.exists():
            shutil.rmtree(prepared)
    store=None
    try:
        for name,body in sorted(files.items()):
            path=stage/name
            private_directory(path.parent)
            atomic_write(path,body,replace=False)
        store=ApplicationStore(stage)
        # Preserve every original revision; add one explicit lifecycle transition
        # for work whose former process cannot survive transfer.
        for row in store.documents("job"):
            if row["payload"]["status"] in ("queued","running","cancelling"):
                store.save("job",row["id"],{**row["payload"],"status":"interrupted",
                    "error":{"type":"WorkspaceReceived","message":"Continue this original job from its retained inputs."}},
                    actor="workspace receiving",expected_revision=row["revision"])
        # Received child locations belong to the previous host. Preserve their
        # history, while making their new local lifecycle explicit. A retained
        # handoff can be opened again from its complete incoming edition; an
        # encrypted recovery requires its separately held original archive.
        for kind in ("receiving", "recovery"):
            for row in store.documents(kind):
                value = row["payload"]
                origin_operation = value.get("receiving_operation_id") or value.get("restoring_operation_id")
                if not origin_operation:
                    origin_operation = store.history(kind, row["id"])[0]["payload"].get("_operation_id")
                store.save(kind, row["id"], {
                    **value,
                    "original_workspace_path": value.get("workspace_path") or value.get("original_workspace_path"),
                    "workspace_path": None, "local_workspace_root": None,
                    "location_status": "retained_archive_available" if kind == "receiving" else "original_archive_required",
                    "receiving_operation_id" if kind == "receiving" else "restoring_operation_id": origin_operation,
                    "relocated_at": now(),
                    "location_note": ("Open reconstructs the retained incoming edition in this operator's receiving directory. "
                        "Later edits in the former independent child workspace require that child's own export."
                        if kind == "receiving" else
                        "This history retains the recovery identity. Restore the separately held encrypted archive into a new local directory.")
                }, actor="workspace receiving", expected_revision=row["revision"])
        with store.lock:
            store.db.execute("INSERT OR REPLACE INTO metadata VALUES('received_from',?)",(canonical(marker).decode(),))
        store.close();store=None
        publish_directory(stage, target)
        fd=os.open(target.parent,os.O_RDONLY)
        try: os.fsync(fd)
        finally: os.close(fd)
        return summary
    finally:
        if store is not None:
            store.close()

